INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(9, 'frFR', 'Ah ! je vois que vous êtes revenu ! J''espère que vous avez bien fait votre travail et débarrassé les champs des Gardiens des moissons. En avez-vous tué 20 ?', 0),
(12, 'frFR', 'Peut-être que je ne me suis pas bien fait comprendre. Pour prouver que vous méritez de faire partie de la Milice du peuple et de la Lumière, vous devez impérativement tuer 15 Trappeurs défias et 15 Contrebandiers défias et ne revenir que lorsque vous aurez accompli cela.', 0),
(13, 'frFR', 'Nous n''avons pas le temps de discuter, $N. Les pilleurs défias empêchent les gens de la marche de l''Ouest de prospérer et de vivre en paix. Débarrassez-nous au moins de 15 Pilleurs défias et de 15 Pillards défias. Le message devrait être assez clair, nous ne voulons pas de cette corruption chez nous.', 0),
(14, 'frFR', '$N, le temps n''est pas aux bavardages inutiles. Si vous voulez prouver votre valeur à la Milice du peuple vous devez tuer les Défias dont je vous ai parlé tout à l''heure. Revenez me voir quand vous aurez accompli votre devoir.', 0),
(16, 'frFR', 'Cultiver la terre est un travail difficile et qui donne diablement soif, je suis toujours partant pour un peu d''eau claire et fraîche.$B$BSi vous en avez, eh bien ! je ferai bien affaire avec vous.', 0),
(22, 'frFR', 'Tout ce dont j''ai besoin pour faire ma fameuse tourte à la viande, c''est de 8 foies de Broche-tripes !', 0),
(23, 'frFR', 'Ah, $N, je pensais à vous justement ! Et cette chasse ?', 0),
(24, 'frFR', 'Bonjour, $N ! Revenez-vous avec la preuve de votre chasse ?', 0),
(30, 'frFR', 'Avez-vous assemblé le pendentif pour que je puisse le vérifier, $N ? Si vous avez besoin d''aide pour trouver les morceaux, essayez d''interroger la population locale. Non seulement cela vous mènera à ce que vous cherchez mais cela vous donnera de surcroît un prétexte pour explorer ces magnifiques contrées sacrées.', 0),
(31, 'frFR', 'Votre retour à Thunder Bluff m''a été annoncé, cependant je vais avoir besoin d''une preuve comme quoi vous avez étudié à Reflet-de-Lune avant de vous enseigner votre forme aquatique.$B$BAvez-vous le Pendentif du lion de mer ?', 0),
(32, 'frFR', 'Veuillez m''excuser, je ne vous connais pas. . . Mais il semble que vous, vous avez entendu parler de moi. Maintenant, comment puis-je vous aider ? Avez-vous quelque chose pour moi ?', 0),
(48, 'frFR', 'Hic ! Oh ! Oh ! Je vous le répète?$B$BDans la campagne du Sud, là où la vigne pousse, en rampant et se tordant$BSe cache un puits où l''eau coule profondément$BAussi pure que la Sœur sacrée de la Lumière, elle est$BApportez-moi un peu de cette eau de source sacrée.', 0),
(49, 'frFR', 'Encore ? Bien sûr !$B$BLe whisky, de ma vie est le plus ancien amour$BComme les étoiles qui durent pour toujours$BRapportez-moi, pour que mon amour revienne majestueux tel un aigle$BUn sac de chacune de ces céréales : orge, maïs et seigle.', 0),
(50, 'frFR', 'Encore une fois pour vous ? Mais bien sûr !$B$BJe mélangerai et mélangerai, jusqu''à de la pulpe obtenir$BPour que ce soit notre secret sans faiblir$BEn métal solide, il faut que cela soit fait$BPour me permettre de finir cette chanson, du vrai-argent il faut me rapporter.', 0),
(51, 'frFR', 'Un rappel ? Mais bien sûr, tout ce que vous voulez !$B$BPas encore filtré, mais déjà distillé$BComme une terre inconnue attendant d''être trouvée$BPuis pour faire un tas de charbon il faut être actif$BLivrez-moi une branche de sycomore, ceci est votre objectif.', 0),
(52, 'frFR', 'Avez-vous tué ces ours et ces loups ?', 0),
(53, 'frFR', 'Bien sûr, je la chante encore pour vous !$B$BDouce eau aussi translucide que des larmes d''enfant$BUne merveilleuse et profonde couleur ambre prend avec le temps$BMais avant de nous saouler$BUn fût de chêne doit être fabriqué.', 0),
(63, 'frFR', 'Le brasero réfléchit encore la lumière ambiante et les flammes ondulent un peu alors que vous approchez.$B$BLa corruption des collines semble gardée à distance. En dehors des éléments nécessaires, tout semble prêt pour l’accomplissement du rituel de purification et l''invocation d''une manifestation d''eau purifiée.', 0),
(75, 'frFR', 'Avez-vous trouvé la page dont je vous ai parlé, $N ?', 0),
(80, 'frFR', 'De retour, $N ? Qu''est-ce que vous avez maintenant?', 0),
(84, 'frFR', 'Ugh. . . Je suis affamé ! Vous m''avez apporté la tourte, $N ?', 0),
(96, 'frFR', 'Vous êtes revenu. Splendide !$B$BComment s''est passé votre voyage jusqu''aux Pins argentés ? Cela vous a-t-il pris beaucoup de temps ?$B$BJe ne sais pas si ce que vous avez fait va servir à quelque chose, il y a tellement d’endroits corrompus. La corruption submerge toutes les choses bonnes que vous avez faites. Mais les petites réussites sont parfois aussi importantes que les grandes. Le fait d''avoir purifié l''eau a été déterminant pour vous, ainsi que pour tous les chamans.', 0),
(99, 'frFR', 'Vous avez les Chaînes enchantées de Bois-du-Bûcher $N ?', 0),
(103, 'frFR', 'La flamme ne durera pas longtemps sans huile, $N.', 0),
(113, 'frFR', 'Eh bien, géomètre novice $N, ce bon vieux Pestlezugg a terminé son rapport ?', 0),
(134, 'frFR', 'Vous avez ma caisse ? Si c''est le cas, donnez-la vite !', 0),
(151, 'frFR', 'La vieille Blanchy ne tient plus debout. Avez-vous réussi à lui trouver de l''avoine ?', 0),
(169, 'frFR', 'Qu''avez-vous donc là, $N ?', 0),
(171, 'frFR', 'C''est un plaisir de vous revoir, $N. Avez-vous pu accomplir les tâches pour lesquelles vous vous êtes portée volontaire pendant la Semaine des Enfants ?', 0),
(181, 'frFR', 'Avez-vous pu convaincre Zzarc''Vul de nous prêter son monocle pour notre petite expérience ?', 0),
(184, 'frFR', 'Vous avez le titre de propriété de ma ferme ?  C''est une merveilleuse nouvelle ! Des forbans nous l''ont volé il y a quelques jours. . . Je le croyais perdu pour de bon !$B$BJe vous en prie, rendez-le-moi. Nous sommes en route pour la marche de l''Ouest et nous allons sans doute y rester un moment, mais si nous revenons par ici. . . Nous aurons besoin de ces papiers !', 0),
(185, 'frFR', 'Je n''ai pas l''intention de vous former, $N, en tout cas pas tant que vous n''aurez pas fait vos preuves en tuant d''abord des jeunes tigres...', 0),
(188, 'frFR', 'Alors, on en est où de la traque de Sin''Dall ?', 0),
(195, 'frFR', 'Tout véritable $C ne pense qu''à sa proie. Vous, en revanche, vous montrez plus enthousiaste lorsqu''il s''agit de papoter autour du feu de camp. À présent filez d''ici et tuez-moi 10 de ces fichus raptors flagellants, avant que je ne m''en charge moi-même et ne débarrasse la jungle entière de ces maudits reptiles en une seule chasse.', 0),
(196, 'frFR', 'Eh bien ! Que faites-vous donc encore dans le coin, $N ! Tout chasseur digne de ce nom ne lâche jamais sa proie une fois son objectif fixé. Ces Traqueurs ne vont pas accourir ici pour se jeter eux-mêmes dans ces flammes. Idiot.', 0),
(199, 'frFR', 'Alors, avez-vous découvert quelque indice, $N ?', 0),
(202, 'frFR', 'Puis-je espérer que Kurzen et ses défenseurs sont morts, $N ?', 0),
(203, 'frFR', 'J''espère que votre chasse a été fructueuse, $N. Sans votre aide, nous ne tiendrons pas longtemps contre lui.', 0),
(205, 'frFR', 'Avez-vous ces fétiches, $N ? Ils renferment peut-être le secret de la déchéance de Kurzen… Je dois savoir !', 0),
(212, 'frFR', '$N ! Avez-vous ce cuissot ? Je vais bientôt devoir commencer à cuisiner, ou le banquet sera un fiasco !', 0),
(214, 'frFR', 'Alors, avez-vous chassé le gang défias de nos terres ? Si tel est le cas, prouvez-le en me montrant 10 masques rouges en soie.', 0),
(220, 'frFR', 'Bonjour, $N. Vous semblez en pleine forme.$B$BQu''est-ce qui vous amène ici si tôt ?', 0),
(237, 'frFR', 'Nous avons besoin de plus de temps, $N. Vos ordres sont de tuer 10 Brise-crâne et 10 Prophètes Brisepierre. Maintenez la pression sur l''ennemi jusqu''à l’arrivée de nos renforts. L’heure n''est pas à l''immobilisme.', 0),
(246, 'frFR', 'Pardonnez-moi, $N, mais il y a beaucoup à faire ici. Si vous n''avez aucune information à me donner, laissez-moi m''occuper des questions importantes.', 0),
(249, 'frFR', 'Hâtez-vous, $N, avant que mes craintes ne se réalisent !', 0),
(263, 'frFR', 'De retour, déjà ! Au cas où je n''aurais pas été suffisamment explicite, vous devez tuer 10 Chamans et 10 Briseurs d''Os Brisepierre, $N. À présent prenez soin d''eux, tueur de troggs.', 0),
(272, 'frFR', 'Avez-vous assemblé le pendentif pour que je puisse le vérifier, $N ? Si vous avez besoin d''aide pour trouver les morceaux, essayez d''interroger la population locale. Non seulement cela vous mènera à ce que vous cherchez mais cela vous donnera de surcroît un prétexte pour explorer ces magnifiques contrées sacrées.', 0),
(275, 'frFR', 'Les Paluns pleurent toujours, et les Rampants des tourbières continuent de sévir. Revenez me voir lorsque vous aurez accompli votre tâche.', 0),
(276, 'frFR', 'Votre tâche n''est pas terminée, jeune $C.', 0),
(278, 'frFR', 'Avez-vous trouvé les composants nécessaires ? Le temps presse !', 0),
(279, 'frFR', 'Nos marchands ne seront pas en sûreté tant que nous ne serons pas débarrassés d''Enfourneur et de ces murlocs.', 0),
(294, 'frFR', 'Tuez 10 Raptors tachetés et 10 Hurleurs tachetés, $N. Mes équipiers n''ont pas mérité un tel sort. Il est temps d''égaliser le score.', 0),
(299, 'frFR', 'Avez-vous déjà retrouvé les quatre fragments, $N ? Ados, Modr, Golm et Neru. . .', 0),
(308, 'frFR', 'Hum ! Toute cette boisson stockée là, et dire que j''ai l''interdiction formelle d''y toucher ! Si seulement je pouvais goûter un peu de notre Thunder Ale... Ça me donnerait un esprit plus vif, sans mentir !', 0),
(311, 'frFR', 'Avez-vous fait l''échange ?', 0),
(387, 'frFR', 'La Prison est toujours hors de contrôle ! Ces Rats de Défias doivent comprendre que leurs actions ne seront pas tolérées. Maintenant retournez là-bas et faites preuve d''un peu d''autorité !', 0),
(410, 'frFR', 'C''est une vieille table ensanglantée.', 0),
(433, 'frFR', 'Si nous nettoyons la carrière de Gol''Bolar de ses troggs, nous aurons assurément fait un premier pas pour nous débarrasser de cette menace, mais la route sera longue.', 0),
(507, 'frFR', 'Qu-que voulez-vous ?', 0),
(527, 'frFR', 'En tant que Haute Exécutrice de Moulin-de-Tarren, placée sous le commandement direct de Varimathras et de la Dame noire, vous devez m’obéir.$B$BPeut-être prenez-vous cette guerre contre l''Alliance à la légère ? Si tel est le cas, je vous décapiterai ici même, sur l''heure. Sinon, partez à l''ouest, vers la ville de Hautebrande et lancez l''assaut contre les humains, comme je vous l''ai ordonné.$B$BRompez.', 0),
(562, 'frFR', 'J''ai une lettre prête à partir pour le major Samuelson à Hurlevent. Je n''ai besoin que de résultats.', 0),
(579, 'frFR', 'Le Roi Anduin accorde une grand importance à l''éducation, et c''est pourquoi il a débloqué des fonds pour rendre accessible au public des copies de divers ouvrages et écrits. C''est très simple. Vous me donnez un titre de bibliothécaire, et je puis vous fournir la copie de l''un des livres disponibles.', 0),
(593, 'frFR', 'Yenniku se tient étourdi devant vous, l''esprit ailleurs…', 0),
(660, 'frFR', 'Le temps des discours est terminé. Protégez Kinelory si le peuple de Hautebrande vous importe un tant soit peu.', 0),
(676, 'frFR', 'Je n''ai déjà pas le temps d''affûter ma hache, alors quitter le poste pour traquer ces bêtes qui s''en prennent aux miens. . .$B$BVous ne semblez même pas avoir l''expérience d''un grunt, encore moins celle d''un vrai $C. Alors que voulez-vous, $N ?', 0),
(681, 'frFR', '$N, chaque heure perdue rend notre situation plus précaire. Vous devez vous presser ou notre ville tombera.', 0),
(763, 'frFR', 'Quels vents vous poussent jusqu''à moi, $C ?', 0),
(768, 'frFR', 'Ah, vous voici. La chasse fut-elle bonne ? Avez-vous les peaux ?', 0),
(769, 'frFR', 'Avez-vous mes fournitures, $N ?', 0),
(777, 'frFR', '<Sans lever les yeux des ses Entraves, Lotwil tend une main et remue les doigts, impatiemment. >$B$BLe rouage, $N, le rouage !', 0),
(778, 'frFR', 'Ce n''est pas exactement l''issue à laquelle je m''attendais. Avez-vous pu récupérer mes Entraves ?', 0),
(779, 'frFR', 'Le Sceau de la Terre est ici, avec trois alcôves pour la Pierre runique d''améthyste, la Pierre runique d''opale et la Pierre runique de diamant.', 0),
(794, 'frFR', 'Avez-vous terminé votre travail, $N ? Le Médaillon de la Lame ardente est-il en votre possession ?', 0),
(795, 'frFR', 'Le Sceau de la Terre est ici, avec trois alcôves pour la Pierre runique d''améthyste, la Pierre runique d''opale et la Pierre runique de diamant.', 0),
(806, 'frFR', 'Avez-vous trouvé Féplouf, $N ? Lui et le reste de la Lame ardente doivent être éradiqués de nos terres !', 0),
(808, 'frFR', 'Avez-vous le crâne de mon frère, $N ? Est-il enfin libre ?', 0),
(822, 'frFR', 'Alors, vous travaillez dur pour rechercher ces ingrédients, $N ?', 0),
(826, 'frFR', 'Avez-vous battu Zalazane, $N ?', 0),
(827, 'frFR', 'Êtes-vous entré dans le Rocher du crâne, $N ? Avez-vous des Colliers brûlants ?', 0),
(835, 'frFR', 'Vous ne penseriez pas ça d''un type comme mon patron Gazleu, mais il semblait toujours savoir de quoi il en retournait. "N''aie pas peur d''accomplir ce grand pas," qu''il disait.$B$BLes harpies ne vont pas arrêter de nous ennuyer et les caravanes ne vont pas passer sans être attaquées à moins que nous y fassions quelque chose, hein ?', 0),
(837, 'frFR', 'Bien qu''ils possèdent quelque intelligence et quelque organisation, je trouve ahurissant que les hurans aient été capables de s’approprier et de défendre un si vaste territoire en Kalimdor. Ce sont peut-être des ennemis plus aguerris que je ne l''aurais pensé.', 0),
(848, 'frFR', 'Avez-vous les spores, $N ? Je dois envoyer à mon associée de Thunder Bluff une mixture qui en utilise. . .', 0),
(851, 'frFR', 'Avez-vous trouvé Verog, $N ?', 0),
(852, 'frFR', 'Hezrul Marque-de-sang est-il vaincu, $N ?', 0),
(855, 'frFR', 'Comment se passe la chasse, $N ?', 0),
(861, 'frFR', 'Salutations. Vous avez une allure qui en dit long. Avons-nous des affaires en cours, vous et moi ?', 0),
(862, 'frFR', 'Z''avez éclaté assez de rats, $N ?', 0),
(864, 'frFR', 'Soyez à nouveau le bienvenu. Ou du moins, je vous souhaite la bienvenue si vous revenez avec la Trousse d''analyse de terrain verrouillée. Dans le cas contraire, je prétendrai ne pas avoir remarqué votre totale incompétence et vous épargnerai ma rage jusqu''à ce que vous fassiez ce que vous avez à faire et que vous accomplissiez la quête que je vous ai confiée.', 0),
(865, 'frFR', 'Avez-vous ces cornes, $N ? Ces trucs vont me rapporter une fortune !', 0),
(869, 'frFR', 'Avez-vous ces têtes, $N ?', 0),
(876, 'frFR', 'Vous n''aurez rien tant que je ne verrai pas la tête de Serena.', 0),
(888, 'frFR', 'Avez-vous trouvé, $N ?', 0),
(889, 'frFR', 'Apportez 10 Joyaux de sang à Mutiledent et je vous doterai d''une vitesse impressionnante. Vous courrez avec les zhévras et le vent vous jalousera.$B$BCela ne durera pas longtemps, mais cela devrait suffire à vous faire traverser les Tarides.', 0),
(890, 'frFR', 'Des marchandises à envoyer par le prochain bateau, $N ?', 0),
(896, 'frFR', 'Si seulement nous savions quel mineur a trouvé l''émeraude, ce serait une promenade de santé.', 0),
(897, 'frFR', 'Vous avez l''air soucieux, $N. Comment se déroulent vos leçons dans les Tarides ? Avez-vous découvert quelque chose de préoccupant ?', 0),
(900, 'frFR', 'Des lumières clignotant sur la console de contrôle indiquent que les valves de contrôle principales ne sont pas fermées.', 0),
(902, 'frFR', 'Oh ! Vous êtes de retour, $N ! Avez-vous le Samophlange ?', 0),
(903, 'frFR', 'Comment se déroule votre chasse, $N ? Avez-vous trouvé les rôdeurs ?', 0),
(906, 'frFR', 'Oui ? Qu''est-ce que c''est ?', 0),
(907, 'frFR', 'Avez-vous battu les lézards-tonnerre, $N ?', 0),
(915, 'frFR', 'J''aimerais bien qu''ils fassent d''autres parfums de glace que la fraise. Mais j''ai de la chance, la glace à la fraise est ma préférée !', 0),
(916, 'frFR', 'Avez-vous trouvé les glandes à venin, $N ?', 0),
(917, 'frFR', 'Êtes-vous allé à l''intérieur de la grotte de Sombrefil, $N ? Avez-vous trouvé un œuf d''araignée ?', 0),
(923, 'frFR', 'Êtes-vous allé au lac d''Aigue-vive, $N ? Avez-vous détruit des sylvains là-bas ?', 0),
(925, 'frFR', 'Quand les orcs étaient seuls et sans alliés, les taurens les ont accueillis sur cette terre qui leur était étrangère, sans rien leur demander en échange. C''est un honneur, $N.', 0),
(927, 'frFR', '$N ! Avez-vous quelque chose pour moi ?', 0),
(938, 'frFR', 'Brume… C''était ma faute ! Les sorcières m''ont surprise la garde baissée… Je n''aurais pas dû les laisser te prendre…', 0),
(939, 'frFR', 'Qu''y a-t-il, $C ? Vous avez l''air préoccupé.', 0),
(943, 'frFR', 'Une fois que je serai en possession de la Pierre de Relu je pourrai libérer les secrets cachés de mon fossile, mais également ceux du fossile de Remtravel de Sombrivage, $N.', 0),
(944, 'frFR', 'Le Glaive du Maître, $N.$B$BAllez-y, puis parlez-moi à nouveau de là-bas.', 0),
(947, 'frFR', 'Avez-vous mes champignons, $N ? Êtes-vous allé à la caverne ?', 0),
(953, 'frFR', 'Lorsque vous aurez étudié les tablettes et compris les circonstances de la chute d''Ameth''Aran, je relaierai cette connaissance jusqu''à Auberdine, et informerai le Cercle des Anciens.', 0),
(964, 'frFR', 'Tuez beaucoup et tuez souvent, $C - il nous faudra suffisamment de fragments de squelettes pour façonner la couche externe de la clé. Elle ne s''appelle pas Clé squelette par hasard, vous savez.', 0),
(967, 'frFR', 'Voulez-vous me parler d''une affaire, $C ?', 0),
(978, 'frFR', 'D''où ces pouvoirs peuvent-ils venir ? Je pense que nous sommes en bonne voie pour trouver la réponse, $N.', 0),
(992, 'frFR', 'Bienvenue, géomètre novice $N ! Avez-vous déjà terminé votre mission ?', 0),
(996, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(998, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(1007, 'frFR', 'Avez-vous trouvé la statuette, $N ?', 0),
(1009, 'frFR', 'On dit que l''Anneau de Zoram ouvre toutes les serrures de la cité. L''avez-vous trouvé, $N ?', 0),
(1011, 'frFR', 'Avez-vous trouvé le camp, $N ? Avez-vous rapporté une Bouteille des maladies ?', 0),
(1012, 'frFR', 'Mes rêves sont toujours remplis d''angoisse à cause des druides de Dor''danil, $N. Vous devez éliminer leurs chefs !', 0),
(1013, 'frFR', 'Vous avez trouvé le livre, $N ?', 0),
(1027, 'frFR', 'Avez-vous trouvé le dernier morceau du Bâtonnet, $N ?', 0),
(1043, 'frFR', 'Les bois sont dangereux si l''on est mal préparé. Gardez l''esprit clair et vos armes à portée de main, ou votre prochain voyage dans la forêt hantée sera le dernier.', 0),
(1045, 'frFR', 'Avez-vous déjà tué Ran ?$B$BMême les elfes de la nuit ne méritent pas vraiment sa colère. Ses éclats de haine sont encore plus violents que les miens, mais son esprit ne lui appartient plus. Il est une menace pour toutes les créatures naturelles de cette forêt.', 0),
(1052, 'frFR', 'Qui va là ? Que voulez-vous de moi ?', 0),
(1067, 'frFR', 'Vous voilà de retour, $N ! Apportez-vous une l''aide de l''Apothicaire Lydon ?', 0),
(1069, 'frFR', 'Avez-vous récupéré les oeufs, $N ? J''ai déjà convenu d''un arrangement avec le Maître des quais Dizzywig !', 0),
(1077, 'frFR', 'Ha ha ! Vous êtes de retour ! Vous l''avez ? Avez-vous le sort ?', 0),
(1079, 'frFR', 'Avez-vous les plans, $N ?', 0),
(1080, 'frFR', 'Comment ça se passe, $N ?', 0),
(1088, 'frFR', 'Lorsque mon maître m''a enjoint de venir au pic des Serres-Rocheuses, je pensais que mon unique tâche consisterait à écraser les elfes de la nuit qui rampaient dans les ruines sacrées de notre ancien temple d''Azshara, souillant la sainteté du lieu. . . Mais Ordanus a échappé à mon étreinte.', 0),
(1091, 'frFR', 'Oui, $N ? Que puis-je faire pour vous ?', 0),
(1100, 'frFR', 'D''après votre mine inquiète, je peux dire que quelque chose va mal…', 0),
(1101, 'frFR', 'Tant que Trancheflanc rassemble des forces au Kraal de Tranchebauge, ces régions courent un grand danger.', 0),
(1104, 'frFR', 'Salut salut salut ! Avez-vous ce venin ?', 0),
(1105, 'frFR', 'Mon frère progresse dans la conception de son nouveau carburant, et cela m''inquiète. Je dois commencer à travailler sur des réservoirs en carapace de tortue aussi tôt que possible !$B$B$N, avez-vous ces carapaces ?', 0),
(1107, 'frFR', 'Avez-vous les nageoires ? Si je ne peux pas protéger notre chariot de l’échauffement, alors il ne fera pas long feu dans ces courses.', 0),
(1108, 'frFR', 'Avez-vous trouvé des flocons d''indurium, $N ? Ma forge est chaude et prête à les tester.', 0),
(1113, 'frFR', 'Êtes-vous revenu du Monastère écarlate ? J''ai besoin de beaucoup de cœurs pour cette merveilleuse expérience !$B$BVarimathras et la Dame noire seront ravis d''être débarrassés de cette vermine écarlate.', 0),
(1116, 'frFR', 'Déjà de retour ? Avez-vous ma Poussière de rêve ?', 0),
(1118, 'frFR', 'Salut salut. Et qu''est-ce qui vous amène à Baie-du-Butin, $N ?', 0),
(1119, 'frFR', 'Salutations, $N. Est-ce que Fizzlebub a été capable de nous aider ?', 0),
(1120, 'frFR', 'Salut ! Vous avez quelque chose pour moi ?', 0),
(1121, 'frFR', 'Qu''est-ce que vous regardez ?', 0),
(1122, 'frFR', 'Salutations, $N. Comment ça s''est passé avec cette bière ? Elle est forte, pas vrai ?', 0),
(1125, 'frFR', 'Alliance ou Horde, aucune importance ; personne ne mérite d''être piégé dans ce monde sous la forme d''un esprit torturé. Il faut libérer ces âmes, $N.', 0),
(1131, 'frFR', 'Avez-vous détruit l''horrible Broie-l''acier, $N ?', 0),
(1135, 'frFR', 'Avez-vous trouvé Haut-perchoir, $N ? Rencontré quelques wyvernes ?', 0),
(1136, 'frFR', 'Alors, vous avez visité les montagnes d''Alterac, $N ? Vous avez débusqué l''insaisissable Gueule-glacée ?', 0),
(1139, 'frFR', 'La quête d''Hammertoe doit être reprise, $N. Je lui dois au moins ça.$B$BVous devez impérativement retourner à Uldaman, non seulement dans ce but, mais également dans l''intérêt de toute la race des nains. Si la Tablette tombe entre les mains des Sombrefer, qui sait le pouvoir que pourrait avoir leur armée de golems.', 0),
(1142, 'frFR', 'Qu''est-ce qui vous amène dans ma maison, $R ?', 0),
(1149, 'frFR', 'La Foi. Elle est plus importante que vous ne l''imaginez.$B$BParfois, croire est plus important que ce à quoi l''on croit.', 0),
(1153, 'frFR', 'J''ai revu ces voyageurs... Ceux qui refusent de me vendre l’échantillon de minerai. Je leur ai craché dessus, car ils refusent d''aider le Chef de guerre.$B$BPuissent-ils périr en lâches dans la bataille et non en guerriers, comme il est juste pour tous les alliés de la Horde !', 0),
(1172, 'frFR', 'Dépêchez-vous de rejoindre le Cloaque aux dragons, $N. Avec les œufs d''Onyxia répartis tout autour de la tourbière du Ver, nous serons vite débordés par le nombre des dragons si nous ne faisons rien.$B$BDétruisez ses œufs ! Ne laissez pas la malédiction des dragons noirs se répandre sur notre terre natale !', 0),
(1176, 'frFR', 'Avez-vous trouvé ces os pour moi ? Je travaille à l''allégement de la structure de manœuvre, mais je ne veux pas la démonter tant que je ne dispose pas de toutes les pièces nécessaires.', 0),
(1179, 'frFR', 'Attention où vous mettez les pieds ! Attention, attention, attention ! C''est un engin délicat que vous voyez là, et il doit être en parfait état de marche si nous voulons gagner !', 0),
(1183, 'frFR', '$N ! Avez-vous réussi à trouver le régulateur de carburant ?', 0),
(1192, 'frFR', 'J''aimerais intégrer de l''Indurium dans les différents composants de mes voitures, mais il me faut une grande quantité de ce minerai pour les fabriquer.$B$BVous trouverez de l''Indurium à Khaz Modan, dans les mines d''Uldaman, dans les Terres ingrates, de l''autre côté de la mer.$B$BLes gnomes ont désormais leur propre source d''approvisionnement. Il est donc vital que nous ayons la nôtre pour rester au même niveau qu''eux.', 0),
(1193, 'frFR', 'Un grand piège cassé se trouve devant vous. On dirait que les ogres ont tenté de le réparer sans succès. Une note hâtivement griffonnée se trouve juste à côté. Curieusement, elle détaille tout ce qui est nécessaire pour le réparer : il faut un rouage en thorium et un peu d’huile glaciale. Si le piège était réparé, un ogre qui passerait à côté pourrait s’y faire prendre, et pourrait être évité.$B$BC’est vraiment une bonne chose que très peu d’ogres sachent lire.$B$BVraiment.', 0),
(1202, 'frFR', 'Avez-vous trouvé les documents, $N ? Ils contiennent des informations vitales pour la stabilité de l''Alliance et, par là même, pour la sécurité de la Horde.', 0),
(1205, 'frFR', 'Vous avez la dent de Mortebourbe, $N ? Vous avez mis un terme aux souffrances de la pauvre créature ?', 0),
(1221, 'frFR', 'Avez-vous les racines, $N ?', 0),
(1239, 'frFR', 'Vous avez quelque chose d''autre à signaler, $N ?', 0),
(1242, 'frFR', 'Bonjour, $N. Que puis-je faire pour vous ? Peut-être aimeriez-vous goûter un peu de notre cheddar spécial de Trias ? Ou un morceau de bleu de Darnassus ?', 0),
(1249, 'frFR', 'Il s''est enfui ? La manière dont il nous regardait était vraiment louche.', 0),
(1251, 'frFR', 'Qu''avez-vous là, $N ? Des indices trouvés à l''auberge du Repos ombragé ?', 0),
(1258, 'frFR', 'Mes recherches sur les langues de Rochefange progressent. J''espère que votre chasse aux crabes se passe bien ?', 0),
(1321, 'frFR', 'Quelque chose pour moi, $C ?', 0),
(1364, 'frFR', 'Qu''est-ce qui vous amène au Rempart-du-Néant, $N ?', 0),
(1366, 'frFR', 'Comment se porte votre collection d''oreilles, $N ? Est-elle déjà impressionnante ?', 0),
(1369, 'frFR', 'Si vous n''êtes pas notre ennemi alors vous ferez ce que je dis !', 0),
(1371, 'frFR', 'Si vous n''êtes pas notre ennemi alors vous ferez ce que je dis !', 0),
(1373, 'frFR', 'Montrez-moi que vous êtes un ami des Gelkis, $N.', 0),
(1374, 'frFR', 'Montrez-moi que vous êtes un ami des Gelkis, $N.', 0),
(1375, 'frFR', 'Servez les Magram et je vous aiderai.', 0),
(1381, 'frFR', 'Faites ce que je demande. Prouvez-moi que vous êtes l''allié des Magram !', 0),
(1388, 'frFR', 'J''espère que vous vous êtes montré utile à notre cher ami, l''apothicaire Faustin.', 0),
(1391, 'frFR', 'Ayez pitié de moi ! Je possède des informations qui dépassent le cadre de la seule l''Alliance. Bien que je ne sois pas un sympathisant de la Horde, je suis au courant de trahisons qui doivent être révélées !', 0),
(1398, 'frFR', 'Avez-vous trouvé ce bois, $N ?', 0),
(1421, 'frFR', 'Avez-vous les composants pour les sorciers, $N ?', 0),
(1426, 'frFR', 'Je suis patient. Patient et inusable telle une vieille pierre kank de Draenor. Tant que je suis debout, les hommes-poissons ne franchiront pas nos frontières. Si nous avions une armée à notre disposition, je nettoierais ce monde et tous les autres de leur infecte présence. Le simple fait de parler d''eux fait bouillonner ma haine.', 0),
(1428, 'frFR', 'Je ne serai pas heureux tant que la mer et ses enfants ne seront pas réduits au silence… Et spécialement ces hommes-poissons dégoûtants.', 0),
(1442, 'frFR', 'Si quelqu''un venait s''informer sur la Gemme de Kor en dehors du chemin sacré, je serai soupçonneux. Mais j''ai plus confiance en votre race qu''en certains membres de ma propre famille. Je ne juge pas tout votre ordre à l’aune de ceux qui sont déchus.', 0),
(1452, 'frFR', 'Vous connaissez la bière au malt Rhapsody ? L''une de mes meilleures bières, si je peux me permettre moi-même de le dire personnellement. Hic !$B$BMais si je dois revivre les horreurs de ce vol fatidique au-dessus du… hic… marais, alors je vais avoir besoin de quelque chose d''un tout petit peu plus fort. Hic !$B$BJe présume que vous n''avez pas trouvé ces gésiers et ces foies dont j''ai besoin pour ajouter ce petit plus à mon Kocktail Kalimdor ?$B$BHic !', 0),
(1456, 'frFR', 'Sans vouloir offenser Nijel, qui qu''il soit, ce camp n''est pas l''endroit le plus confortable pour passer la nuit, si vous voyez ce que je veux dire, $N.', 0),
(1459, 'frFR', 'Cela me désole de ne pas avoir pu vous dire où trouver de kodos ou de scorpashis. Ce secteur ne m''est guère familier, et je n''ai pas trouvé le temps de l''explorer.', 0),
(1466, 'frFR', 'Je n''ai même pas remarqué que ces choses démoniaques se trouvaient en Désolace. Aux dernières nouvelles, les centaures possédaient plus ou moins la terre après que les elfes de la nuit aient vidé les lieux, il y a des années.$B$BJe me demande pourquoi ils ont pris possession des lieux, et comment.', 0),
(1467, 'frFR', 'Bienvenue, $N. Les affaires prospèrent, le son des enclumes frappées résonne dans tout Forgefer, les soufflets nourrissent un feu ardent, et ma femme me prépare une tourte pour le dessert de ce soir. La vie pourrait-elle être plus belle ?', 0),
(1469, 'frFR', 'Enfin vous voilà de retour, $N. Cela fait longtemps que nous nous sommes parlé. Je pensais que vous aviez oublié ma quête ?$B$BÊtes-vous parvenu à localiser ce chevaucheur de gryphons ? Avait-il quelque chose à dire ?', 0),
(1475, 'frFR', 'Alors que le crépuscule tombe doucement sur ma carrière, je me tourne vers vous, $N, pour m''aider dans ma dernière quête au service de la Ligue des Explorateurs. Si mes vieux os pouvaient rassembler la résistance nécessaire pour braver le marais des Chagrins et le temple englouti, je me battrais à vos côtés.$B$BLa fierté fait qu''il m''est difficile de vous demander de l''aide pour récupérer les tablettes atal''ai. Mais mon grand âge rend cette demande nécessaire cependant.$B$BS''il vous plaît, aidez-moi, $N. Je veux me retirer de la Ligue des Explorateurs en ayant accompli sa dernière demande.', 0),
(1486, 'frFR', 'Je suis très intéressé à l''idée d''examiner la peau des créatures perverties qui ont envahi ces cavernes. Avez-vous eu la chance d''en trouver, $C ?', 0),
(1498, 'frFR', 'Avez-vous ces écailles, $N ? Si vous ne pouvez pas supporter les attaques des lézards-tonnerre, vous ne bénéficierez pas de mon instruction.', 0),
(1501, 'frFR', 'Avez-vous la Tablette de Verga, $N ? Sinon, je ne souhaite plus vous parler jusqu''à ce que vous l''ayez.', 0),
(1503, 'frFR', 'Avez-vous mes barres d''acier ?', 0),
(1504, 'frFR', 'Le marcheur du Vide est une puissante créature. Je me souviens du temps où j''étais à votre place, $N. Les années passant, mon propre marcheur du Vide a commencé à être moins ardent dans ses combats contre moi. Mais je soupçonne que c''est simplement parce qu''il espère ainsi que je baisserai ma garde.$B$BN’oubliez jamais cela, $N.', 0),
(1511, 'frFR', 'Oui ? Qu''est-ce que c''est ?', 0),
(1512, 'frFR', 'Vous voilà de retour. Êtes-vous prêt à combattre une succube ?', 0),
(1513, 'frFR', 'Lorsque mon regard se pose sur une succube, mon cœur commence à s''élancer… Mais en même temps, je sens mon esprit reculer et refluer comme la marée.$B$BSoyez prudent, mon ami.', 0),
(1514, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(1515, 'frFR', 'Arrrghhhh…', 0),
(1519, 'frFR', 'La terre est patiente et attendra que vous soyez prêt car elle sait qu''avec le temps tout s''érode et tout renaît. C''est le cycle des choses. Les montagnes deviennent des déserts. Les rivières deviennent des canyons. La Terre est le plus opiniâtre et le plus sage des éléments.$B$BVous devez apprendre la patience et l''endurance par-dessus tout. La terre vous appelle à présent, car elle pense que vous êtes prêt. Si vous réussissez, considérez ce rite comme une renaissance. Après, vous ne pourrez plus jamais retourner à l''ignorance.', 0),
(1521, 'frFR', 'Salutations, $N. Vous ne seriez pas revenu si vous n''aviez pas accompli votre quête. Laissez-moi être la première à vous accueillir sur la première des quatre voies qui guideront à jamais vos voyages.$B$BSi vous avez la pierre que la terre vous a donnée, je vous donnerai le totem qu''elle vous a promis. Sinon,  je vous plains. Car on éprouve une grande fierté à se consacrer pleinement aux éléments.', 0),
(1524, 'frFR', 'Salutations, $N. Vous vous trouvez à l''Autel de la flamme dormante. Seuls ceux qui connaissent suffisamment les arts du $C peuvent apprendre les secrets de cet endroit et le pouvoir qu''il renferme. Je suis désolé que vous ayez fait tout ce chemin pour être éconduit à l''arrivée. Le voyage pour venir jusqu’ici est loin d''être sûr, mais je suis le gardien de l''autel et je ne permets pas à n''importe qui de s''en approcher.', 0),
(1525, 'frFR', 'J''aurai suffisamment d''ingrédients pour confectionner un sapta de feu si vous m''apportez une bourse de réactifs et du goudron de feu. Les fanatiques de la Lame ardente utilisent de bons ingrédients, qu’ils portent généralement dans une bourse. Une bourse contient suffisamment de réactifs pour ce que nous avons à faire.$B$BLes saptas sont toujours composés d''ingrédients associés à leurs éléments respectifs. Cela facilitera notre travail, car les démonistes ont de nombreuses affinités avec le feu.', 0),
(1526, 'frFR', 'Le brasero mesure à peu près un tiers de votre hauteur, et semble normal, si ce n''est les inscriptions le long de ses parois métalliques lisses. Le métal ne montre aucun signe d''usure dû au temps, et la coupe semble fraîche au toucher.', 0),
(1527, 'frFR', 'Oui, $N ? Qu''avez-vous là ?', 0),
(1534, 'frFR', 'Avez-vous trouvé l''eau, $N ? La légende dit que les ruines étaient protégées par d''imposantes créatures qui se souciaient peu des visiteurs, mais il s''agit peut-être de fables destinées à effrayer les ennemis des elfes de la nuit.$B$BCependant, faites attention.', 0),
(1535, 'frFR', 'Je suis presque prête à vous envoyer accomplir vos autres quêtes. Avez-vous rempli l''outre ?$B$BJe sais à quel point les hurans ont une attitude protectrice à l’excès ! Même un humble ruisseau est une immense source de prospérité pour eux. Ils font la fête dès que la moindre averse tombe sur les Tarides. L''eau est sacrée à leurs yeux, car elle est très rare. Comprenez-vous ?', 0),
(1536, 'frFR', 'La pureté intacte de ce puits, en pleine ville, me rappelle des histoires que l''on m''a racontées lorsque j''étais jeune, $N. Même dans les temps de douleur et de chagrin, on trouve toujours une lueur d''espoir, un petit symbole auquel se raccrocher. Le peuple des orcs considère Thrall de cette façon. Il a survécu contre vents et marées et s''est élevé pour diriger notre peuple, pour l’aider à trouver sa force et à suivre son exemple.$B$BJe suis sûr que tous les orcs ont souffert autant qu''il a souffert, mais il est le plus fort de tous les orcs.', 0),
(1578, 'frFR', 'Je n''ai pas le temps pour la parlotte. Vous avez quelque chose à me dire ?', 0),
(1581, 'frFR', 'Salutations, $N. Avez-vous ces élixirs pour moi ?', 0),
(1598, 'frFR', 'Cela n’aurait pas été judicieux de voler le livre moi-même. Quelle chance qu’un pigeon ait fait le sale boulot à ma place !', 0),
(1599, 'frFR', 'Ces charmes de plume portés par les novices sont liés à une sorte de pouvoir magique. Ce sera intéressant de les étudier. Je ne me serais pas attendu à cela de la part des trolls.', 0),
(1618, 'frFR', 'J''espère que vous apportez des bonnes nouvelles de Forgefer. Car je ne sais plus quoi faire !', 0),
(1644, 'frFR', 'J''espère que mon John a plus de chance à Forgefer. Il déteste tellement ces voyages là-bas, car il nous laisse seuls, les enfants et moi. Mais il sait qu''il doit le faire. Il est d''une telle gentillesse.$B$BCertaines années ont été meilleures que d''autres, mais celle-ci est de loin la plus dure. C''est presque comme si quelque chose dans l''air annonçait un grand bouleversement. Mais qui peut savoir ?', 0),
(1648, 'frFR', 'Pourquoi, avec ce flot de marchands dans le coin et partout dans Azeroth, ne trouve-t-on pas de quoi fabriquer des vêtements pour les enfants de notre orphelinat ? Cela serait noble de votre part si vous m''aidiez à trouver des pièces de lin afin que ma femme puisse confectionner des habits pour ces enfants. Merci, $N !$B$BAvec un peu de chance, je serai rapidement de retour à la maison.', 0),
(1654, 'frFR', 'Les objets de la liste sont très difficiles à se procurer, mais je vous assure que l''arme que je vais vous fabriquer en vaut la peine.$B$BCela sera mon chef-d''œuvre, mais ce sera bien peu de chose en comparaison de ce que vous, vous avez fait pour moi.', 0),
(1683, 'frFR', 'Avez-vous la corne, $N ? Est-ce que notre Puits de lune est débarrassé de Vorlus ?', 0),
(1686, 'frFR', 'Avez-vous battu l''Ombre d''Elura, $N ? Avez-vous le minerai perdu ?', 0),
(1688, 'frFR', 'Même le plus âgé et le plus sage peut être déstabilisé par la jeunesse et la beauté, $N. C''est une chose dont vous devez vous souvenir tout au long de votre vie.', 0),
(1689, 'frFR', 'Je ne peux pas vous montrer comment contrôler un marcheur du Vide si vous n''en avez pas invoqué et maîtrisé un d’abord.', 0),
(1700, 'frFR', 'Bonjour et bienvenue. Que puis-je faire pour vous ?', 0),
(1704, 'frFR', 'Bonjour, ou bonsoir. Je ne sais même plus qu''elle heure il est. Vous avez quelque chose pour moi ?', 0),
(1705, 'frFR', '$N, avez-vous le Sang et le Roc ardents ? J''en ai besoin pour terminer l''armure.', 0),
(1708, 'frFR', 'Bonjour, bonjour, $N ! Avez-vous le corail torride ? Je n''en peux plus d''attendre !', 0),
(1710, 'frFR', 'Avez-vous les coquilles, $N ? Elles sont très résistantes et peuvent être transformées en laque que j''appliquerai sur les mailles de ma nouvelle cotte.', 0),
(1712, 'frFR', 'Avez-vous les objets, $N ? Les apporter prouvera que vous avez la force de combattre un Cyclonien.', 0),
(1713, 'frFR', '$N, je dois avoir le Cœur de tourbillon !', 0),
(1714, 'frFR', 'Le chaudron bouillonne. Ces vapeurs attirent...', 0),
(1738, 'frFR', 'Avez-vous réussi, $N ?', 0),
(1739, 'frFR', 'Parfois je me demande si Surena n''était pas une succube déguisée, envoyée pour pervertir et fausser mon esprit. . . Ha ! Je la surestime, sans doute.', 0),
(1740, 'frFR', 'Cela m''a pris des années pour réunir les morceaux de l''orbe de Zargain, mais cela m''a été très utile, je suis certain que l''orbe de Soran''ruk vous servira aussi.', 0),
(1784, 'frFR', 'Vous êtes de retour ! Je suis content de vous voir, $N. Mes blessures sont guéries et je suis prêt à repartir pour le lac du Lit d''Helm dès que j''aurai convaincu ma femme que je vais bien.', 0),
(1787, 'frFR', 'Est-ce que Henze est sauf, $N ? Avez-vous réussi ?$B$BEntre vos talents au combat et le pouvoir de la Lumière, j''imagine que la Veillée des héros est débarrassée de la menace des Défias, mais ça, c''est au roi et à ses conseillers qu’il faut le dire.', 0),
(1795, 'frFR', 'Chaque $C devrait avoir un chasseur corrompu à ses ordres. Bien qu''il soit difficile d''en soumettre un, les pouvoirs qu’il confère à son maître en valent largement la peine.', 0),
(1796, 'frFR', 'Où en êtes-vous dans votre recherche de robes, $N ? Vous les avez créées vous-même ? Ces touches personnelles rendent l''imprégnation de la magie beaucoup plus douce, je trouve. Cela vous donne un grand sens de la prouesse. Mais je sais que si vous choisissez la méthode la plus rapide et que vous la faites faire - il faut louer une telle. . . ambition.', 0),
(1799, 'frFR', 'De toute évidence, vous n''êtes pas un mage, je me demande si je peux vous faire confiance. Je peux sentir le pouvoir des Arcanes en vous, mais vous avez l''air d''avoir éliminé l''odeur infecte de la corruption qui accompagne généralement les membres de votre espèce.$B$BOui, un  $C. . . un $C est venu requérir mon aide.$B$BBien, que puis-je faire pour vous, $N ?', 0),
(1802, 'frFR', 'Est-ce que les rumeurs étaient vraies, $N ?', 0),
(1803, 'frFR', 'Vous allez peut-être poursuivre des chimères, $N, mais il y a toujours une part de vérité dans les rumeurs.', 0),
(1804, 'frFR', 'Ça fait longtemps que vous êtes parti. Avez-vous trouvé le tome et les bâtonnets ?', 0),
(1805, 'frFR', 'Oui, $N ? En quoi puis-je vous être utile ?', 0),
(1821, 'frFR', 'Avez-vous l''héritage, $N ?', 0),
(1824, 'frFR', 'Vous avez les antennes ? Si oui, donnez-les-moi vite, parce que les antennes mobiles ne le restent pas éternellement…', 0),
(1838, 'frFR', 'Avez-vous les articles notés sur mon rouleau, $N ?', 0),
(1842, 'frFR', 'Avez-vous les sabots, $N ? Leur magie est forte.', 0),
(1844, 'frFR', 'Avez-vous la corne ? La matriarche est-elle libérée de sa peine ?', 0),
(1846, 'frFR', 'J''attends ces tibias, $N. Cela fera une belle structure pour vos jambières.', 0),
(1858, 'frFR', 'Cela ne vous agace pas d''avoir ce que vous désirez à portée de la main, mais de n''avoir aucun moyen de l''obtenir ?', 0),
(1861, 'frFR', 'Avez-vous l''échantillon, $N ? Le flux de magie dans Hurlevent et Elwynn a été modifié et je dois savoir s''il suinte dans l''eau.', 0),
(1878, 'frFR', 'Vous revoici, $N ? Si vous avez cinq outres de Bat-le-désert de plus, alors j''ai un paquet qui porte votre nom !', 0),
(1880, 'frFR', 'Avez-vous trouvé mon Bidulotron ? Je dois le récupérer avant que sa provision d''énergie ne soit déchargée !', 0),
(1882, 'frFR', 'Avez-vous les gueules-de-loup ? Cette variété de fleurs est très sensible aux énergies magiques. L''étude des gueules-de-loup poussant près des Maleterres pourra nous indiquer si la peste est entrée dans les Clairières de Tirisfal.', 0),
(1886, 'frFR', 'Un succès à m''annoncer ?', 0),
(1898, 'frFR', 'Salut. Quelque chose que je peux faire pour vous ?', 0),
(1899, 'frFR', 'Vous avez réussi, $N ?', 0),
(1918, 'frFR', 'Ouais, qu''est-ce que vous voulez ?', 0),
(1920, 'frFR', 'Avez-vous capturé les créatures, $N ? Elles doivent être étudiées pour déterminer la cause de leur présence.', 0),
(1921, 'frFR', 'Bonjour, $N. Jennea m''a dit que vous viendriez. Avez-vous quelque chose pour moi ?', 0),
(1938, 'frFR', 'Avez-vous le livre, $N ? Ses secrets ne sont pas à la portée des non-initiés et tenter d''en sonder les profondeurs peut mener à la perte et à la ruine.', 0),
(1940, 'frFR', 'Ah ! Oui ! Les mages du Sanctuaire du Sorcier m''ont dit que vous viendriez. Avez-vous apporté la soie ?', 0),
(1944, 'frFR', 'Quel plaisir de vous voir de retour en bonne santé, $N ! Vous avez mon échantillon d''eau ? J''ai hâte d''étudier ses propriétés.', 0),
(1945, 'frFR', 'Bonjour, $N. Deino m''a dit que vous viendriez et que vous m''apporteriez des cheveux des sœurs rieuses. Les avez-vous ?', 0),
(1948, 'frFR', 'Bonjour, $N ! Avez-vous ce que je vous ai demandé ?', 0),
(1951, 'frFR', 'Je vous salue, $N. Avez-vous trouvé le livre « Les Rituels du pouvoir » ?', 0),
(1954, 'frFR', 'Avez-vous trouvé un orbe infernal, $N ?', 0),
(1956, 'frFR', 'Vous revenez d''Uldaman, $N ? Vous avez vaincu la Sentinelle d''obsidienne ?', 0),
(1960, 'frFR', 'Avez-vous fait votre enquête sur la perturbation, $N ? Avez-vous capturé les créatures ?', 0),
(1961, 'frFR', 'Anastasia m''avait dit que vous viendriez me voir et je suis prêt à confectionner vos robes. Avez-vous les gemmes et le lin ?', 0),
(1963, 'frFR', 'C''est un imbécile qui croit qu''une charge à la hache est plus efficace qu''un couteau dans la nuit.', 0),
(1998, 'frFR', 'Je vous fais parfaitement confiance pour rendre ce service au Seigneur Varimathras.', 0),
(1999, 'frFR', 'Avez-vous localisé les documents, $N ?', 0),
(2078, 'frFR', 'Où est mon Premier Officier, $N ? T''auras droit aux fers et aux requins si tu t’dépêches pas !', 0),
(2199, 'frFR', 'Vous avez mes Barres d''argent ? Je vous raconterai en détail l''histoire du Collier. . . Quand j''aurai ces Barres ! Vous allez bien donner un coup de main à un gnome, non ?', 0),
(2201, 'frFR', 'L''image de Talvash apparaît dans l''eau de la coupe de divination.$B$B"Et bien, vous êtes encore en vie ! Vous les avez ? Vous avez sauvé ma réputation ? Ne me dites pas que vous avez gâché une charge de la fiole simplement pour bavarder ! Ce n''est pas donné, et je suis déjà plus que fauché !"', 0),
(2203, 'frFR', 'Avez-vous utilisé les Récipients thaumaturgiques pour pomper le sang de dragon gardien des terres brûlées dont j''ai besoin ? Oui, je sais que c''est une opération dangereuse. . . Mais l’élaboration de mon breuvage fortifiant dépend de votre succès. Risque et récompense, mon ami. Risque et récompense. . .', 0),
(2204, 'frFR', 'Vous n''avez même pas fait un brin de toilette avant de rentrer, hein ? Vous arrivez directement, en traînant avec vous les odeurs fétides d''Uldaman. . . Espérons au moins que votre visite n''est pas seulement odoriférante. . .$B$BVous avez la Source d''énergie pour le Collier ?', 0),
(2205, 'frFR', 'Comment puis-je vous être utile, $C ?', 0),
(2239, 'frFR', 'Z''avez bien aimé la puanteur du gnome lépreux ? J''demande ça parce que z''avez comme un sourire un peu bizarre.$B$BQuelles nouvelles vous nous rapportez d''Onin ?', 0),
(2241, 'frFR', 'Oh, n''est-ce pas merveilleux ? Vous avez apporté des fleurs pour vos propres funérailles.', 0),
(2242, 'frFR', 'Avez-vous pu obtenir des informations de Sethir l''Ancien, $N ?', 0),
(2278, 'frFR', 'La voix du Gardien paraît résonner au plus profond de vous-même.$B$B"Vous devez d''abord passer une épreuve d''assimilation des données des Disques de Norgannon ; ensuite, il vous sera permis d''en emporter une version portable. Commencez donc par lire attentivement les informations qui se trouvent dans ce reposoir. "', 0),
(2282, 'frFR', 'Au fait, avais-je oublié de mentionner les orcs ?$B$BJ''ai cru comprendre qu''il y en avait qui traînaient près de la scierie.', 0),
(2283, 'frFR', 'Vous avez le Collier ? Vous n''aurez pas un sous si vous ne nous le rapportez pas !', 0),
(2338, 'frFR', 'Vous y avez réfléchi, n''est-ce pas ? Vous seriez une personne avisée si vous acceptiez ce marché, $C. . . Chacun obtiendra ce qu''il veut, même la société de Récupération Droffers et fils, alors qu''ils ne savent pas bien ce qu''ils cherchent. . .', 0),
(2339, 'frFR', 'Il va falloir retourner dans les profondeurs d''Uldaman si vous n''avez pas les Gemmes et la Source d''énergie nécessaires pour permettre la canalisation magique dans le Collier.$B$BVous pourrez récupérer les Gemmes pour les livrer aux triples crétins d''Orgrimmar mais la Source d''énergie sera pour moi, puisque c''est ça qui permet au Collier de fonctionner. .', 0),
(2340, 'frFR', 'Tiens, mais qui voilà ! Ça vous aura pris un moment pour revenir. . . Je ne vous paierai que lorsque le lot sera complet ! Et faites-moi confiance, on vérifiera tout ! On vérifiera deux fois, et trois fois s''il le faut !', 0),
(2359, 'frFR', 'Des nouvelles de l''Agent Kearnen ?', 0),
(2381, 'frFR', 'Enfin, au moins, vous avez conservé tous vos membres. . . Et le trésor ?', 0),
(2383, 'frFR', 'Qu''est-ce que vous avez là ? Un parchemin ? Vous n''êtes pas un savant, j''espère ?', 0),
(2418, 'frFR', 'Avez-vous les Pierres de puissance, $N ? Mon robot-rongeur a besoin d''une alimentation électrique. . .', 0),
(2440, 'frFR', 'Bonjour, $C ! Vous venez ici pour suivre une formation d''alchimiste ou pour autre chose ?', 0),
(2478, 'frFR', 'Qu''avez-vous à m''annoncer, $N ?', 0),
(2479, 'frFR', 'Qu''est-ce que c''est que ça ?', 0),
(2499, 'frFR', 'Avez-vous déjà localisé Froncechêne, $R ?', 0),
(2501, 'frFR', 'Avez-vous utilisé les récipients thaumaturgiques pour pomper le sang de dragon gardien des terres brûlées dont j''ai besoin ? Oui, je sais que c''est une opération dangereuse. . . Mais l’élaboration de mon breuvage fortifiant dépend de votre succès. Risque et récompense, mon ami. Risque et récompense. . .', 0),
(2520, 'frFR', 'Avez-vous déposé le sacrifice dans la fontaine, $N ?', 0),
(2521, 'frFR', 'J''ai consacré ma vie à la recherche de sphères de draenéthyste sans défaut. Le travail de toute une vie, $N !', 0),
(2522, 'frFR', 'Avez-vous trouvé une autre sphère de draenéthyste sans défaut ?', 0),
(2523, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(2561, 'frFR', '$N, faites preuve de prudence en vous approchant de ma forme physique : l''enchantement qui la contrôle est très puissant.', 0),
(2601, 'frFR', 'Est-ce que vous revenez avec les organes demandés ?', 0),
(2602, 'frFR', 'Est-ce que vous revenez avec les organes demandés ?', 0),
(2603, 'frFR', 'Ne me faites pas perdre mon temps, $N. Nous n''avons rien à nous dire, à moins que vous n''ayez récupéré ce que je vous ai demandé.', 0),
(2604, 'frFR', 'Ne me faites pas perdre mon temps, $N. Nous n''avons rien à nous dire, à moins que vous n''ayez récupéré ce que je vous ai demandé.', 0),
(2609, 'frFR', 'Si vous voulez guérir de votre itis, vous allez devoir essayer avec plus d''ardeur, $N. Où sont les réactifs pour le remède ?', 0),
(2623, 'frFR', 'J''attends les ordres.', 0),
(2741, 'frFR', 'Le Super-Oeuf-O-Matic est la dernière des inventions de Curgle Cranklehop. C''est une machinerie très impressionnante.$B$BLe Super-Oeuf-O-Matic bafouille quelque chose lorsque vous vous approchez du panneau de commande.', 0),
(2744, 'frFR', 'Que faites-vous là ?', 0),
(2747, 'frFR', 'J''ai rarement vu des œufs récupérés en Féralas dans un état satisfaisant. Ces œufs comptent parmi les plus rares…', 0),
(2748, 'frFR', 'Un œuf de premier choix est un œuf qui, dans des conditions idéales, va éclore libre des effets néfastes des incantations des ogres Gordunni.', 0),
(2749, 'frFR', 'Les œufs ordinaires d''hippogryphes éclosent une fois sur deux. Nous faisons de notre mieux pour les élever et avec une petite chance, ils écloront.', 0),
(2750, 'frFR', 'Ces œufs-là ne peuvent pas être sauvés : ils n''écloront jamais.', 0),
(2751, 'frFR', 'Du bronze, $N ! Plus de bronze !', 0),
(2754, 'frFR', 'Montrez-moi le fer que vous travaillez, $N !', 0),
(2756, 'frFR', 'Aturk, comme le temps, n''attend personne ! Dépêchez-vous !', 0),
(2757, 'frFR', 'Vous êtes d''une race rare, l''ami. Laissez-moi voir cet insigne.', 0),
(2758, 'frFR', 'Serez-vous le prochain protégé de Galvan ?', 0),
(2759, 'frFR', 'Vous êtes d''une race rare, l''ami. Laissez-moi voir cet insigne.', 0),
(2761, 'frFR', 'Après un tel labeur, vos muscles sont noués et vous avez des courbatures partout !', 0),
(2762, 'frFR', 'Après un tel labeur, vos muscles sont noués et vous avez des courbatures partout !', 0),
(2763, 'frFR', 'Après un tel labeur, vos muscles sont noués et vous avez des courbatures partout !', 0),
(2768, 'frFR', 'Avez-vous trouvé le sergent Bly ? Avez-vous récupéré mon bâtonnet divino-matic ?', 0),
(2771, 'frFR', 'Avez-vous terminé de fabriquer les objets, $N ?', 0),
(2772, 'frFR', 'Avez-vous terminé de fabriquer les objets, $N ?', 0),
(2773, 'frFR', 'Avez-vous terminé de fabriquer les objets, $N ?', 0),
(2782, 'frFR', 'Bien, maintenant, qu''est-ce que ceci ?', 0),
(2784, 'frFR', 'Écoutez ce que j''ai à dire.', 0),
(2801, 'frFR', 'Écoutez ce que j''ai à dire, $N.', 0),
(2841, 'frFR', 'Je ne vois aucun plan. Les avez-vous cachés quelque part sur vous ou bien êtes-vous juste là pour m''énerver ?', 0),
(2846, 'frFR', 'Avez-vous la tiare, $N ? Est-ce que Velratha a compris ce qu''il en coûtait de s''en prendre à moi ?', 0),
(2847, 'frFR', 'Comme je vous le disais, vous allez travailler pour moi pendant que je vous apprendrai à réaliser l''armure en cuir sauvage. Parce que les sauvageonnes sont puissantes et chaotiques, l’armure bénéficie d’une amélioration puissante, mais aléatoire. Ce savoir, toutefois, n''est pas facile à acquérir.$B$BLe coût initial est de dix pièces de cuir épais.$B$BUne fois cette première étape réglée, nous verrons comment obtenir les patrons.', 0),
(2848, 'frFR', 'Avez-vous les six renforts d''armure épais et la sauvageonne que je réclame ?$B$BLa confection des renforts d''armure n’est pas un travail fastidieux. Considérez-le comme un exercice de perfectionnement avant d’attaquer la création plus difficile d''une armure en cuir sauvage.$B$BVous voyez, il y a une raison si je vous demande de faire cela pour moi. . .', 0),
(2849, 'frFR', 'Avez-vous les deux cuirasses et les gants en écailles de tortue que je vous ai demandés ? Et n''oubliez pas la sauvageonne !$B$BNous savons que les formes les plus simples servent de base à la réalisation d’objets plus complexes. Bien que différents, les cuirasses en écailles de tortue vous préparent à la confection d''un gilet en cuir sauvage.$B$BLes gants ? Ils sont pour mon usage personnel. N''oubliez pas : vous travaillez pour moi !', 0),
(2850, 'frFR', 'J''ai besoin de ces tuniques et bandeaux ainsi que de la sauvageonne avant de partager avec vous mes connaissances sur le casque en cuir sauvage.$B$BLes couvre-chefs sont appréciés des aventuriers, que cela soit un simple bandeau ou un casque fermé. Les bases de la création sont les mêmes, quelle que soit l''apparence du casque.', 0),
(2851, 'frFR', 'La commande de pantalons, de bottes et de sauvageonnes doit m''être livrée avant que vous ne receviez le patron, $N. Avez-vous terminé ?$B$BDès la première paire que nous confectionnons, nous comprenons que les bottes parfaites sont un savant équilibre entre fonction et confort. Nous pouvons créer des bottes qui permettent au porteur d''ignorer la fatigue lorsqu''il les porte, contrairement à des bottes de moins bonne qualité.', 0),
(2852, 'frFR', 'Avez-vous fini les brassards et les casques en écailles de tortue ? Et n''oubliez pas les sauvageonnes !$B$BPour le moment, vous commencez à peine à réaliser la puissance potentielle des armures en cuir sauvage. Une telle qualité est inestimable. La seule limite est la quantité de matières premières disponibles, et non la qualité du produit fini !', 0),
(2853, 'frFR', 'Salutations, $N... Je vois que vous travaillez le cuir comme je le fais. Venez-vous apprendre ou avez-vous besoin d''autre chose ?', 0),
(2854, 'frFR', 'Que cela soit bien clair, pendant que vous apprenez l''art de l''armure en cuir sauvage, vous êtes mon élève. Parce que les sauvageonnes sont puissantes et chaotiques, elles confèrent une amélioration puissante, mais aléatoire, aux armures résistantes que vous fabriquez.$B$BLe coût initial de la formation est de dix peaux épaisses.$B$BRapportez-les et nous verrons ce qu’il faut pour obtenir les patrons.', 0),
(2855, 'frFR', 'Avez-vous les six renforts d''armure épais et la sauvageonne dont j''ai besoin ?$B$BLa confection des renforts d''armure est une leçon d''endurance et de précision. Cet apprentissage développe des talents qui seront utiles lors de la confection d''armures en cuir sauvage.$B$BChaque leçon a une raison d’être, $N. Il est important de les étudier une à une.', 0),
(2856, 'frFR', 'Avez-vous les deux cuirasses et les gants en écailles de tortue ? Et n''oubliez pas la sauvageonne !$B$BNous savons que les formes les plus simples servent de base à la réalisation d’objets plus complexes. Bien que différents, les cuirasses en écailles de tortue préparent à la confection d''un gilet en cuir sauvage.$B$BAu fur et à mesure que vous progresserez, les techniques que je vous enseignerai se transformeront en art.', 0),
(2857, 'frFR', 'J''ai besoin de ces tuniques et bandeaux ainsi que de la sauvageonne avant de partager avec vous mes connaissances sur le casque en cuir sauvage.$B$BLes couvre-chefs sont appréciés des aventuriers, que cela soit un simple bandeau ou un casque fermé. Les bases de la création sont les mêmes, quelle que soit l''apparence du casque.', 0),
(2858, 'frFR', 'Les pantalons, les bottes et les sauvageonnes doivent m''être livrés avant d’apprendre le patron, $N. Avez-vous terminé ce que je vous ai demandé ?$B$BDepuis la première paire que nous avons confectionnée, nous avons compris que des bottes parfaites étaient un savant équilibre entre fonction et confort. Nous pouvons créer des bottes qui, contrairement à d''autres de moins bonne qualité, permettent au porteur d''ignorer la fatigue lorsqu''il les porte.', 0),
(2859, 'frFR', 'Vous avez déjà fini les brassards et les casques en écailles de tortue ? N''oubliez pas les sauvageonnes dont j''ai besoin.$B$BVous commencez maintenant à réaliser la puissance potentielle de l''armure en cuir sauvage. Une telle qualité est inestimable. La seule limite est la quantité de matières premières disponibles, et non la qualité du produit fini !', 0),
(2862, 'frFR', 'Nous les avons repoussés et ils continuent d''attaquer ! Il doit y avoir quelque chose ou quelqu''un qui les rend fous… Vous êtes là, $N ? Avez-vous les crinières ?', 0),
(2873, 'frFR', 'Avez-vous retrouvé mon rhum, $N ?', 0),
(2878, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(2922, 'frFR', 'Avez-vous trouvé Techbot ? Avez-vous pu récupérer sa mémoire principale ?', 0),
(2924, 'frFR', 'Vous avez les cerveaux mécaniques ?', 0),
(2934, 'frFR', 'Avez-vous la glande à venin, $N ? J''ai hâte d''effectuer les expérimentations avec ce venin frais. J''ai une foule d''adorables petits cobayes qui attendent mes injections !', 0),
(2946, 'frFR', 'Le socle, d''apparence familière, se dresse sur le sable brûlant. Sa présence ici ne peut être fortuite. . .', 0),
(2948, 'frFR', 'Avez-vous les matériaux dont j''ai besoin ? Je ne vous les demanderais pas si je ne manquais pas si cruellement de ressources.', 0),
(2949, 'frFR', 'Vous pensiez que nous trouverions un moyen de l''emporter sur ces sales petits gnomes ? Je suis sûr qu''ils l''ont volé, cet anneau, pour commencer ! Enfin, ces affreux petits. . . hem, oui ? Il vous fallait quelque chose ?', 0),
(2950, 'frFR', 'Avez-vous les matériaux que j''ai demandés ? Je ne peux améliorer cet anneau sans eux.', 0),
(2953, 'frFR', 'Le Décapeur 5200 est vide et attend un objet à nettoyer ainsi que trois pièces d''argent pour démarrer.', 0),
(2954, 'frFR', 'Le but du Gardien des pierres doit être connu avant de continuer. . .', 0),
(2966, 'frFR', 'Le socle, d''apparence familière, se dresse sur le sable brûlant. Sa présence ici ne peut être fortuite. . .', 0),
(2967, 'frFR', 'Alors, $N, avez-vous pu utiliser les disques ou revenez-vous bredouille ?', 0),
(2970, 'frFR', 'Kindal a besoin de temps pour se préparer, mais nos victimes se comptent maintenant par douzaines. Le clan du Totem sinistre est conscient de notre présence et nous recherche sans relâche. . .$B$BIls feraient n''importe quoi pour brandir nos têtes au bout d''une pique. Faites attention, après ce que vous avez fait, ils ne vous feront pas de cadeaux non plus.', 0),
(2973, 'frFR', 'Quand elles sont provoquées, les Fées fléchetteuses peuvent être de dangereuses bestioles ; faites très attention et ne vous fiez pas à leur apparence, $C. Soyez encore plus vigilant quant aux elfes de la nuit qui peuplent l''endroit. Ces infects individus rôdent souvent dans les forêts.$B$BRevenez me voir quand vous aurez collecté suffisamment d''ailes et je vous récompenserai largement !', 0),
(2976, 'frFR', 'Que voulez-vous, $C ? J''ai beaucoup à faire aujourd''hui.', 0),
(2989, 'frFR', 'Vite, $N ! Si les trolls Vilebranch retiennent Bec-tranchant, qui sait ce qu''ils lui feront subir !', 0),
(2991, 'frFR', 'Avez-vous le Médaillon de Nekrum, $N ? Il contient des pouvoirs que je suis avide de mettre à l''épreuve.', 0),
(3002, 'frFR', 'Que m''apportez-vous là, $N ?', 0),
(3042, 'frFR', 'Avez-vous l''agent, $N ?', 0),
(3065, 'frFR', 'Encore du renfort ! Cela me convient.$B$BVous aurez sûrement du mal à soulever une bonne arme comme une hache, mais une lance c''est déjà mieux que rien.$B$BBienvenue dans la Vallée des épreuves, $N.', 0),
(3083, 'frFR', 'Bienvenue dans la Vallée des épreuves, $N. Vous ne seriez pas ici si vous n''aviez eu ma tablette, je serai donc direct :$B$BJe suis Rwag, responsable de l''entraînement des bandits, voleurs et détrousseurs, ici dans la vallée. La Main surveillera de près vos progrès et m''a chargé de les superviser. Vous aurez une certaine liberté, mais je vous conseille de travailler dur et d''être prêt lorsqu''ils auront besoin de vos talents.', 0),
(3085, 'frFR', 'Vous êtes ici. . . bravo, c''est chouette ! Les esprits m''ont dit que vous passeriez voir Ken''jai tôt ou tard. Bienvenue dans la Vallée des épreuves. Vous n''y resterez pas longtemps, mais tant que vous y êtes, profitez-en un maximum.', 0),
(3086, 'frFR', 'On veut déjà faire plaisir à Mai''ah, $N. C''est bien. Si vous respectez Mai''ah, Mai''ah vous le rendra. Mais parlons peu, parlons bien, vous êtes là pour apprendre la magie, pas pour m''entendre radoter.$B$BY a qu''un truc que Mai''ah peut pas vous apprendre sur la magie, $N, c''est comment stopper la corruption.', 0),
(3087, 'frFR', 'Ah, vous voilà enfin. Parfait. Jen''shan vous attendait.$B$BBeaucoup pensent que c''est une voie facile, mais Jen''shan vous dit que non. Maîtriser les bêtes de Durotar et au-delà demande autant de talent que de maîtriser les arcanes ou de parler aux ancêtres.$B$BTirer à l''arc ou au fusil n''est p''têt'' pas aussi périlleux pour vous que de lancer un sort, mais c''est pour sûr aussi efficace contre votre ennemi.', 0),
(3088, 'frFR', 'Chut, pas si fort. Je ne fais pas confiance à Nartok, là-bas. Ceux qui se cachent encore plus profond que moi dans une grotte ne doivent pas être pris à la légère.$B$BVous n''avez pas eu trop de problèmes pour me trouver ?', 0),
(3090, 'frFR', 'Enfin, vous voilà. . . Et discrètement en plus. Bien.$B$BNotre monde est plein de fous, $N. Même le puissant Thrall n''est pas sans faille. Il néglige les moyens qui nous seraient nécessaires pour faire cette terre nôtre ! Nous ne sommes plus de ceux qui se laissaient manipuler et utiliser par les créatures du Néant. Nous sommes un peuple à part. Nous sommes fiers. . . . Et nous sommes forts.', 0),
(3091, 'frFR', 'Vous voici enfin, $C. Je n''ai pas menti dans ma lettre, $N. Nous sommes une race à part, un peu comme les druides ou les chamans de notre tribu. Votre importance est tout aussi grande. Nous sommes ceux sur qui l''on compte pour défendre nos frontières, chasser le centaure et partir à la guerre.', 0),
(3092, 'frFR', 'Bienvenue au Camp Narache, $N. J''ai entendu beaucoup de bien à votre propos. Votre lignée est puissante et de nombreux anciens pensent que vos dons sont remarquables. Mais de cela nous allons nous assurer.$B$BVous aller passer un peu de temps dans les plaines de Mulgore : vous devrez en connaître les moindres recoins. Plus tard vous voyagerez en des terres inconnues pour apprendre de nouvelles techniques. Vous devez vous y préparer.', 0),
(3093, 'frFR', 'Aussi vite que l''éclair, vous voici devant moi. Votre hâte me réjouit. Car elle signifie que vous saisissez l''importance de notre rencontre et de votre venue. Je ne suis pas un guide, mais je connais les éléments et je peux parler aux esprits de notre peuple. Je vous apprendrai à faire de même.', 0),
(3095, 'frFR', 'Ah, vous voici. Bien. On m''a informé que quelques autres étaient parvenus à échapper à la "mort" et devaient arriver en ville. Peut-être que tant de résistance servira à l''avenir.$B$BVous pouvez remercier Dame Sylvanas pour votre liberté. . . Liberté de corps et d''esprit. La Peste et ses effets vous torturent encore, mais vous pouvez aller et venir librement, selon vos désirs.', 0),
(3097, 'frFR', 'Ah, donc malgré le feu, la peste, les émeutes et même pire, mes "fidèles" se présentent toujours plus nombreux à ma porte. Eh bien, je vous souhaite la bienvenue, $C. Accordez-moi un moment pour vous expliquer une chose ou deux avant que vous ne choisissiez votre voie : le Feu Sacré ne vous concerne plus, les esprits de vos ascendants ne sont que des fables et les créatures du Néant ne vous veulent pas.$B$BJusqu''ici vous suivez ?', 0),
(3098, 'frFR', 'Je savais que vous viendriez à moi, $N. Non parce que vous manquez de volonté pour suivre votre propre chemin, mais parce que nous sommes des esprits semblables. Nous avons tous deux ressenti la douleur. Nous avons souffert. Et désormais nous réclamons ce qui nous revient de droit : cette terre, nos vies, nos destinées. Mais il vous reste encore beaucoup à apprendre.', 0),
(3101, 'frFR', 'Enfin ! Nous nous rencontrons, de frère à frère. Bienvenue à Northshire. Vous y séjournerez le temps d''apprendre nos techniques, mais sachez que Hurlevent n''est pas très loin et que tôt ou tard vos pas vous y mèneront. En attendant, usez de patience... Chevalier de la Main d''Argent.', 0),
(3102, 'frFR', 'Vous voici, en un seul morceau et sans vous faire remarquer. Parfait. Je n''aime pas trop me faire remarquer dans le coin. . . Je suis plutôt discret. Vous comprenez.$B$BDéjà eu quelques ennuis ? Jamais ? c''est parfait. Cela changera bien assez tôt.', 0),
(3104, 'frFR', 'Bonjour, $N. Je suis Kheldon. Que puis-je faire pour vous ?', 0),
(3106, 'frFR', 'Fait sacrément froid, pas vrai ? C''est comme si la neige elle partait jamais, $N.$B$BZ''avez déjà remarqué, mais y a plus de gnomes chez nous. C''est parce qu''il sont partis et ont fait sauter leurs maisons. Ne le dites pas à tout le monde, mais on ne peut pas trop leur en vouloir : je pense que moi aussi j''en serais venu aux explosifs si Forgefer était infestée de Sombrefer ou autres.', 0),
(3107, 'frFR', 'Donc vous voici ! Pile au bon moment. Il y a beaucoup à faire dans la Vallée des Frigères et au-delà. Je vais avoir besoin de votre aide au moins autant que vous aurez besoin de la mienne !$B$BVous êtes un chevalier de la Main d''Argent désormais, préparez-vous à jouer votre rôle.', 0),
(3109, 'frFR', 'Vous voilà ! Génial !$B$BNotre activité marche bien en ce moment alors je suis content de pouvoir compter un autre membre du clan Forgefer dans nos rangs. Trop d''entre nous à mon goût se tournent vers l''arcane et le divin. J''ai rien contre eux ou leurs croyances, mais y a rien de tel qu''une lame froide entre vos mains ou qu''un coin d''ombre où se dissimuler, voyez c''que j''veux dire ?', 0),
(3110, 'frFR', 'Ah ! Vous êtes ici, $N ! Formidable !$B$BJe désespérais de votre arrivée, j''avais presque perdu foi en vous. . . Ha ha, perdre la foi ? C''est une blague. . . Bah, c''est pas grave. Vous n''êtes pas venu pour entendre mes mauvaises blagues.', 0),
(3113, 'frFR', 'Ravi de voir que vous avez reçu ma note et que vous êtes ici. Désolé pour l''imposture avec la note de vos supérieurs. . . N''y voyez aucun mal. Les gens comme nous doivent être solidaires avec les nôtres.$B$BBeaucoup pensent que ce n''est pas une bonne chose que d''avoir nos deux espèces dans la même ville, mais je pense que ça peut marcher. Pas vrai ?', 0),
(3115, 'frFR', 'Formidable ! Vous avez bien reçu mon mémorandum.$B$BIgnorez les idiots qui vous entourent, $N. Le Feu Sacré ?! L''épée et le bouclier ?! Ce ne sont pas des voies pour des gens ouverts d''esprit tels que nous. Regardez ce que la magie "normale" a fait de notre patrie. Et à cause de ces maudits bricoleurs, notre race a bien failli s''éteindre. Nous devons désormais compter sur les nains : or, ceux-là préfèrent passer leur temps à s''allier aux humains plutôt qu''à nous aider à reconstruire notre maison. Nous sommes des citoyens de seconde zone. Avez-vous seulement vu comment ils nous regardent ?', 0),
(3116, 'frFR', 'Vous êtes ici. Bravo.$B$BBeaucoup de choses se sont passées au cours de ses dernières années, $N : la création de Teldrassil, la corruption de nombreuse créatures de la forêt ici et ailleurs, la découverte de terres que nous pensions perdues comme Féralas... Tellement de choses, en si peu de temps. Mais ce ne sont qu''une partie des raisons qui nous amènent ici, la raison principale étant de protéger notre espèce contre les périls à venir.', 0),
(3117, 'frFR', 'Vous voici et pile au bon moment, $N. Bienvenue à Sombrevallon.$B$BJe constate que vous avez eu mon message.$B$BComme je vous l''ai déjà dit, je suis là pour former à la voie du $C ; à dresser les bêtes qui vous aideront dans la bataille ; à tirer à l''arc avec précision ; à respecter nos terres et celles alentours.', 0),
(3118, 'frFR', 'Bonjour, $N. Vous m''avez trouvé, c''est bien. Je pensais que vous aviez pu vous perdre.$B$BPas grand-chose de neuf dans Sombrevallon depuis mon dernier message, mais ce sera à vous de collecter les nouvelles. Si vous le voulez, vous pouvez parler aux autres gens autour d''Aldrassil.', 0),
(3119, 'frFR', 'C''est bien, vous avez fait vite, $N. Bienvenue.$B$BComme vous avez dû l''entendre, tout Teldrassil ne vit que par les voyageurs qui y passent. Même des membres de l''Alliance ont été admis dans les branches de Teldrassil afin d''y rencontrer d''autres Kaldorei qui se préparent à de nouvelles aventures.', 0),
(3126, 'frFR', 'Avez-vous réussi à capturer les Marcheurs des bois errants ?', 0),
(3127, 'frFR', 'Avez-vous pu capturer des géants des montagnes ?', 0),
(3141, 'frFR', 'Ne m''interrompez pas, $R.', 0),
(3321, 'frFR', 'Nous finalisons aujourd''hui la célébration de votre engagement envers l''Ordre.', 0),
(3363, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(3367, 'frFR', 'Je… je ne vais pas y arriver…', 0),
(3374, 'frFR', 'Nous y voilà, $N. À une autre croisée de chemins. Le temps est à présent venu de faire un nouveau choix. Quel est-il, mortel ?', 0),
(3375, 'frFR', 'Pour faire une autre Fiole de divination, j''ai besoin d''une potion de mana, d''un morceau de charbon, et d''un peu de nectar sucré.$B$BEt de beaucoup, beaucoup de patience apparemment.', 0),
(3377, 'frFR', 'Permettez-moi de terminer mon histoire.', 0),
(3378, 'frFR', 'Qu''est-ce qui vous amène au Temple de la Lune, $N ?', 0),
(3385, 'frFR', 'Le Maître d''artisanat est toujours en vie ?', 0),
(3441, 'frFR', 'Permettez-moi de finir, mo… $R.', 0),
(3444, 'frFR', 'Cabestan n''est pas très loin, $N. Le voyage ne devrait pas vous prendre trop longtemps.', 0),
(3463, 'frFR', 'Alors, $N, êtes-vous perdu ?', 0),
(3505, 'frFR', 'Le titre du livre est gravé en lettres d''or sur la couverture en cuir noir : "Livre d''Invocation kaldorei". En l''ouvrant, vous constatez que c''est un très vieux livre mais qu''il est en parfait état.$B$BVous supposez qu''il est écrit dans une langue ancienne. . . peut-être du Kaldorei ?$B$BVotre instinct vous dicte de revenir ici une fois que vous aurez fini de châtier les elfes de sang pour leur trahison.', 0),
(3506, 'frFR', 'Comment avance l''élimination des traîtres elfes de sang, $N ? Avez-vous progressé ?$B$BJ''espère que vous avez la force de lui faire plier les genoux ! Elle ne mérite rien d''autre qu''une mort douloureuse pour tout ce qu''elle a fait !', 0),
(3510, 'frFR', '<Le seigneur Arkkoroc se penche pour vous examiner. >$B$BOù sont-elles ?', 0),
(3520, 'frFR', 'Avez-vous trouvé l''Essence d''Esprits de Hurleurs, $N ?', 0),
(3522, 'frFR', 'Oh. . . $N, je suis si heureux que vous soyez de retour.', 0),
(3526, 'frFR', 'Je peux sentir les futures recrues à un kilomètre à la ronde, mieux que je ne sens la poudre explosive. Êtes-vous là pour apprendre à maîtriser l''art de l''explosion ?', 0),
(3527, 'frFR', 'Avez-vous les tablettes de la Prophétie de Mosh''aru, $N ?$B$BQuand j''aurai ces tablettes, je pourrai les étudier et apprendre comment retenir l''Essence d''Hakkar !', 0),
(3528, 'frFR', 'Avez-vous vaincu l''avatar d''Hakkar, $N ? Son essence a-t-elle redonné pouvoir à l''œuf que je vous ai donné ?', 0),
(3561, 'frFR', 'Comment puis-je vous aider, $N ?', 0),
(3564, 'frFR', 'Avez-vous déjà vu Andron ? Il quitte rarement Fossoyeuse, alors je ne pense pas qu''il sera très dur de le trouver.', 0),
(3568, 'frFR', 'Vous savez où cela va nous mener, n''est-ce pas, $N ? Elle ne peut pas survivre. . .  Regardez-la. Le mieux pour elle maintenant, c''est de nous aider à trouver un remède pour combattre la peste. Cette eau qu''elle a bue pourrait nous donner des indices. Elle va mourir de toute façon : autant que sa mort serve noblement ceux de notre peuple. Vous n''êtes pas d''accord ?', 0),
(3602, 'frFR', 'Le mal ne dort jamais, imbécile. Vous aurez le temps de vous reposer quand vous serez mort. Maintenant, apportez-moi ces cristaux.', 0),
(3621, 'frFR', 'Loramus, hein ? Il y a bien des années que je n''avais pas entendu ce nom.', 0),
(3625, 'frFR', 'Interrompre le processus de fabrication pourrait aboutir à une arme imparfaite. Patience, $N.', 0),
(3629, 'frFR', 'Je peux sentir les futures recrues à un kilomètre à la ronde, mieux que je ne sens la poudre explosive. Êtes-vous là pour apprendre à maîtriser l''art de l''explosion ?', 0),
(3632, 'frFR', 'Oui, oui, que puis-je faire pour vous aujourd''hui ? J''ai vraiment du temps libre maintenant que ma seule activité est de regarder notre ville bien-aimée se noyer dans un nuage de mort.', 0),
(3633, 'frFR', 'Je peux sentir les futures recrues à un kilomètre à la ronde, mieux que je ne sens la poudre explosive. Êtes-vous là pour apprendre à maîtriser l''art de l''explosion ?', 0),
(3635, 'frFR', 'Salut à vous ! Si c''est parce que l''un de nos robots guidés a démoli un mur de votre domicile que vous venez, je vous envoie tout de suite mon avocat. Sinon, que puis-je faire pour vous ?', 0),
(3637, 'frFR', 'Salut à vous ! Si c''est parce que l''un de nos robots guidés a démoli un mur de votre domicile que vous venez, je vous envoie tout de suite mon avocat. Sinon, que puis-je faire pour vous ?', 0),
(3638, 'frFR', 'Si vous avez signé le document et que vous êtes d''attaque, il n''y a rien à faire de plus. C''est un chemin que l''on ne peut faire que dans un seul sens. Si vous êtes prêt, sautez donc à bord !', 0),
(3640, 'frFR', 'Si vous avez signé le document et que vous êtes prêt à me le remettre, alors nous y sommes.$B$BLes secrets que je partagerai avec vous sont d''une telle importance que signer le Vœu du secret est capital. J''en ai signé un, comme l''ont fait mon frère et ma sœur, tous deux Ingénieurs gnomes. Vous rejoignez une bien belle famille, Ingénieur $N !', 0),
(3642, 'frFR', 'Si vous avez signé le document et que vous êtes disponible, c''est le moment.$B$BMême si je suis violemment en désaccord à propos de Gnomeregan, particulièrement avec ce fou de maître-artisan Overspark, le Voeu de secret dépasse tout le reste ! Vous devez consentir à emprunter un chemin que l''on ne peut suivre que dans un seul sens et rester sur ce chemin toute votre vie.', 0),
(3644, 'frFR', 'Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d''or.', 0),
(3645, 'frFR', 'Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d''or.', 0),
(3646, 'frFR', 'Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d''or.', 0),
(3647, 'frFR', 'Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d''or.', 0),
(3702, 'frFR', 'Permettez-moi de finir l''histoire de Thaurissan.', 0),
(3785, 'frFR', 'Oui, $N ? Avez-vous cultivé de la Fibre d''aurore pour les recherches capitales de l''archidruide ? Les travaux qu''il effectue pour le Cercle cénarien sont primordiaux, et votre participation ne sera pas oubliée !', 0),
(3786, 'frFR', 'Oui, $N ? Avez-vous cultivé des Fibres d''aurore pour les recherches capitales de l''archidruide ? Les mystérieuses propriétés du cratère d''Un''Goro s''éclaircissent de jour en jour, grâce à votre aide.', 0),
(3792, 'frFR', 'Je vous salue à nouveau, $N. Mes recherches progressent plutôt bien, mais si vous aviez cinq Fibres d''aurore supplémentaires, je serais heureux de vous en débarrasser. Mais “heureux” n''est qu''une figure de style. Plus j''en ai autour de moi, et plus je me sens mal à l''aise. Mes recherches nécessitent cependant que je me hâte et que j''en finisse.', 0),
(3803, 'frFR', 'L''archidruide cherche davantage de Fibres d''aurore pour que le Cercle cénarien puisse poursuivre ses recherches. Nous les prenons par lot de dix. Nous récompenserons votre cueillette par des objets qui pourront être utiles. Lorsque vous en aurez dix, faites-le-moi savoir et je vous récompenserai en conséquence.', 0),
(3804, 'frFR', 'L''archidruide cherche davantage de Fibre d''aurores pour que le Cercle cénarien puisse poursuivre ses recherches sur le cratère d''Un''Goro. Nous récompenserons votre cueillette par des objets qui pourront être utiles. Lorsque vous en aurez dix, faites-le-moi savoir et je vous récompenserai en conséquence.', 0),
(3822, 'frFR', 'Avez-vous trouvé Sha''ni ? Va-t-elle bien ?', 0),
(3823, 'frFR', 'Il n''y a pas assez de sang sur votre uniforme, soldat, loin de là !', 0),
(3825, 'frFR', 'Alors, avez-vous dépeint la situation ?', 0),
(3842, 'frFR', 'Plus je reste ici et plus la tentation est forte de participer à ces courses, $N. Vraiment ahurissant…$B$BAvez-vous trouvé les élixirs ? Une fois que je pourrai dire si l''œuf va bien ou non, je vous le rendrai pour qu''il s''attache à vous jusqu''à ce qu''il soit prêt à éclore.$B$BFaites-le-moi savoir.', 0),
(3843, 'frFR', 'Salut, $N. En quoi puis-je vous être utile ?', 0),
(3904, 'frFR', 'Avez-vous mes vendanges, $N ?', 0),
(3906, 'frFR', 'Une dissonance perturbe toujours les éléments, $N.', 0),
(3922, 'frFR', 'Avez-vous les Rondelles de métal, $N ? J''ai examiné le Samophlange et ne peux plus attendre de le tripatouiller.', 0),
(3982, 'frFR', 'Défendez-vous, imbécile !', 0),
(4024, 'frFR', 'Le géant a-t-il été abattu ?', 0),
(4041, 'frFR', 'Apportez-moi de l''Evoroot, et je vous ferai de l''élixir de Videre sans problème.$B$BJe connais toutes sortes de choses à propos des herbes et de l''alchimie… Tenez, par exemple, laissez-moi vous raconter la fois où j''ai transformé le fromage que j''étais sur le point de manger au déjeuner en or... Hé... Où allez-vous ?', 0),
(4061, 'frFR', 'Ne prenez pas cette tâche à la légère, $N !', 0),
(4062, 'frFR', 'Qu''avez-vous donc là, $N ?', 0),
(4063, 'frFR', 'Etait-ce bien lui ? Etait-il vraiment en vie ?', 0),
(4103, 'frFR', 'Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d''esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu''à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien$B$B$BEn échange de ces fragments, je vous donnerai du Baume cénarien que j''ai déjà préparé.', 0),
(4104, 'frFR', 'Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l''utiliser pour libérer les plantes corrompues que vous rencontrerez.$B$BSi vous avez collecté du Vitriol contaminé, je vous l''échange contre du Baume végétal cénarien que j''ai déjà préparé.', 0),
(4105, 'frFR', 'Grâce à une balise cénarienne, les herboristes expérimentés peuvent distinguer l''insidieuse gangrimpante, un parasite malfaisant produit par la corruption de Gangrebois. Mon travail ici m''a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le baume végétal cénarien.$B$BLorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les brins de gangrimpante si vous avez la balise cénarienne. En échange je vous donnerai du baume cénarien que j''ai déjà préparé.', 0),
(4106, 'frFR', 'Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparamment inutiles en pâte épaisse qui sert d''agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d''avoir toujours une balise sur vous !$B$BLorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j''ai en réserve.', 0),
(4107, 'frFR', 'Le pouvoir d''un objet magique désenchanté est éprouvé par l''essence qu''il crée. J''ai conçu un moyen de transformer l''essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n''avez pas besoin de Balise cénarienne dans ce cas. N''importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l''affaire.$B$BJe n''ai besoin que d''une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L''essence est très puissante. Il en faut peu pour faire beaucoup !', 0),
(4108, 'frFR', 'Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d''esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu''à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien$B$B$BEn échange de ces fragments, je vous donnerai du Baume cénarien que j''ai déjà préparé.', 0),
(4109, 'frFR', 'Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l''utiliser pour libérer les plantes corrompues que vous rencontrerez.$B$BSi vous avez collecté du Vitriol contaminé, je vous l''échange contre du Baume végétal cénarien que j''ai déjà préparé.', 0),
(4110, 'frFR', 'Grâce à une balise cénarienne, les herboristes expérimentés peuvent distinguer l''insidieuse gangrimpante, un parasite malfaisant produit par la corruption de Gangrebois. Mon travail ici m''a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le baume végétal cénarien.$B$BLorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les brins de gangrimpante si vous avez la balise cénarienne. En échange je vous donnerai du baume cénarien que j''ai déjà préparé.', 0),
(4111, 'frFR', 'Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparamment inutiles en pâte épaisse qui sert d''agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d''avoir toujours une balise sur vous !$B$BLorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j''ai en réserve.', 0),
(4112, 'frFR', 'Le pouvoir d''un objet magique désenchanté est éprouvé par l''essence qu''il crée. J''ai conçu un moyen de transformer l''essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n''avez pas besoin de Balise cénarienne dans ce cas. N''importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l''affaire.$B$BJe n''ai besoin que d''une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L''essence est très puissante. Il en faut peu pour faire beaucoup !', 0),
(4113, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4114, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4115, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4116, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4117, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4118, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4119, 'frFR', 'Vous avez découvert la version malade et souffreteuse d''une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal.', 0),
(4121, 'frFR', 'Je vais m''occuper de ce traître véreux, $N.', 0),
(4123, 'frFR', 'Avez-vous le Cœur de la montagne ? Il n''a pas de prix pour moi !', 0),
(4126, 'frFR', 'Avez-vous la recette, $N ? Je ne peux pas supporter l''idée de savoir les nains Sombrefer sirotant la boisson de ma famille !', 0),
(4134, 'frFR', 'Avez-vous la recette de la Thunderbrew, $N ?', 0),
(4144, 'frFR', 'Voici ce que nous allons faire, $N. Procurez-vous des pousses de Pétales-de-sang. De jeunes plantes, pas encore parvenues au stade adulte, vous comprenez ? Puis apportez-les ici. Alors je verrai ce dont la brume atal''ai est capable.$B$BVous pourriez penser que c''est le désir de vengeance qui me guide, mais… vous auriez raison…$B$BEn vérité, je connais le chemin pour nous sortir d''ici, mais tant que Larion n''admet pas que j''ai raison, je ne bouge pas !$B$BC''est assez : partez et trouvez des pousses de Pétales-de-sang afin que nous nous amusions un peu !', 0),
(4148, 'frFR', 'Pour faire fonctionner la baguette, nous avons besoin d''un spécimen de ses futures victimes. Rendez-vous dans le cratère et rapportez une pousse de Pétale-de-sang. Je pourrai alors régler l’appareil pour qu''il prenne soin des petits camarades de Muigin…$B$BS''il n''était pas si obstiné, nous serions déjà sur le chemin du retour… En attendant, je ne peux que lui montrer que ses gamineries ne me perturbent aucunement…', 0),
(4181, 'frFR', 'Je peux sentir les recrues potentielles comme je le fais d’une poudre explosive de première qualité : à des kilomètres ! Êtes-vous venu pour étudier les arcanes de l''explosion ?', 0),
(4183, 'frFR', 'Salutations, $N. Nous sommes-nous déjà rencontrés ? J''ai l''impression de vous connaître.', 0),
(4184, 'frFR', 'Qu''est-ce qui vous amène au Donjon de Hurlevent ?', 0),
(4185, 'frFR', '<Bolvar vous regarde avec une vive attention. >', 0),
(4186, 'frFR', 'Des nouvelles de Bolvar ?', 0),
(4201, 'frFR', 'Avez-vous les ingrédients ? La brèche de mon cœur menace de m''engloutir tout entière !', 0),
(4221, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4222, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4224, 'frFR', 'Avez-vous parlé à John ?', 0),
(4264, 'frFR', '<Le maréchal Windsor regarde la note que vous tenez à la main. >$B$BMais qu''avez-vous donc là, $N ?', 0),
(4282, 'frFR', 'Ce grand subterfuge sera bientôt terminé.', 0),
(4293, 'frFR', 'J''aurai besoin d''au moins cinq échantillons corrompus pour notre groupe de surveillance, $N. Continuez à rassembler des échantillons de gelée de Gangrebois jusqu''à ce que vous en ayez suffisamment. C''est Dame Sylvanas qui l''a décrété. . .', 0),
(4294, 'frFR', 'Oui, $N ? Comment se déroule votre quête ?', 0),
(4295, 'frFR', 'Oh, de la bière ! Je tuerais pour une bonne bière de Sombrefer, $N ! Vite, je deviens sobre ! Je le sais car la sobriété trouble ma vision… et cela vous fait ressembler à celui que j''ai massacré la semaine dernière !', 0),
(4296, 'frFR', 'Avez-vous trouvé les écritures des Sept, $N ? Avez-vous percé les mystères de leur tablette ?', 0),
(4297, 'frFR', 'Avez-vous trouvé la viande, $N ? Votre petit œuf est sur le point d''éclore, vous savez ? S''il ne mange pas de la bonne viande à son premier repas, il peut ne pas passer la semaine, et je n''aimerais pas du tout que cela arrive.$B$BJe ne peux pas vous mentir plus longtemps, $N. La jalousie m''étreint du fait que vous ayez trouvé cet œuf. Ne me faites pas regretter de vous aider ainsi.', 0),
(4342, 'frFR', 'Permettez-moi de terminer mon histoire.', 0),
(4343, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4381, 'frFR', 'Le Pilon vous permet de combiner les cristaux de puissance verts avec les jaunes.$B$BSi on se réfère au manuel de J.D., cette combinaison sert à vous soigner, vous et vos alliés.', 0),
(4382, 'frFR', 'Le Pilon vous permet de combiner les cristaux de puissance verts avec les bleus.$B$BSi on se réfère au manuel de J.D., cette combinaison sert à augmenter l''Esprit.', 0),
(4383, 'frFR', 'Le Pilon vous permet de combiner les cristaux de puissance verts avec les rouges.$B$BSi on se réfère au manuel de J.D., cette combinaison sert à augmenter la protection contre les dégâts physiques.', 0),
(4384, 'frFR', 'Le Pilon vous permet de combiner les cristaux de puissance rouges avec les bleus.$B$BSi on se réfère au manuel de J.D., cette combinaison sert à réduire la Défense de l''adversaire.', 0),
(4385, 'frFR', 'Le Pilon vous permet de combiner les cristaux de puissance rouges avec les jaunes.$B$BSi on se réfère au manuel de J.D., cette combinaison peut être utilisée pour créer une grande explosion qui inflige des dégâts à vos ennemis.', 0),
(4386, 'frFR', 'Le Pilon vous permet de combiner les cristaux de puissance bleus avec les jaunes.$B$BSi on se réfère au manuel de J.D., cette combinaison sert à créer un bouclier qui inflige des dégâts aux ennemis.', 0),
(4401, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4402, 'frFR', 'Avez-vous terminé de collecter des Pommes de cactus ?', 0),
(4403, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4441, 'frFR', 'L''eau libérera l''Esprit d''un ancien et lui permettra de retrouver la paix.', 0),
(4443, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4444, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4445, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4446, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4447, 'frFR', 'Vous avez découvert la version malade et souffreteuse d''une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal.', 0),
(4448, 'frFR', 'Vous avez découvert la version malade et souffreteuse d''une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal.', 0),
(4450, 'frFR', 'Oui, oui ? Que puis-je faire pour vous, $N ? Je suis très occupé et j''ai beaucoup de commandes en cours. Dépêchez-vous. Je suis désolé de précipiter les choses mais si je veux terminer mon travail, je n''ai pas le choix.', 0),
(4461, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4462, 'frFR', 'Vous avez découvert la version malade et souffreteuse d''une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal.', 0),
(4463, 'frFR', 'Présentez les composants, mortel.$B$BJ''exige également trente pièces d''or en paiement de cette création.', 0),
(4464, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4465, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4466, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4467, 'frFR', 'Vous avez découvert une version maladive et souffreteuse de ce qui s''avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal.', 0),
(4481, 'frFR', 'Chaque chose a son prix en ce monde. Le prix de l''article précis que vous cherchez est de trente pièces d''or.$B$BNaturellement, je garderai la majorité des composants que vous avez ramassés. Mais pas d''inquiétude, vous aurez votre bijou.', 0),
(4483, 'frFR', 'Si c''est de la résistance que vous désirez, c''est trente pièces d''or que je demande.', 0),
(4484, 'frFR', 'Ne me faites pas perdre mon temps, $N. Donnez-moi ce que je demande. Trente pièces d''or et les composants.', 0),
(4501, 'frFR', 'A dire vrai, je n''étais pas inquiété par ces créatures étranges. . . Jusqu''à ce que je croise une inscription sur une pierre.$B$BATTENTION AUX PTERREURDACTYLES$B$BQui a bien pu l''écrire ? En tous cas, c''est bien trop effrayant pour ne pas y prendre garde !', 0),
(4502, 'frFR', 'On raconte que le volcan dans Un''Goro est en activité ? Je suis certain que je pourrais en apprendre plus en étudiant des échantillons de cendres du volcan, $N.', 0),
(4506, 'frFR', 'Ne me dites pas que vous ne pouvez pas y retourner ! Allez !', 0),
(4507, 'frFR', 'Il est impératif de récupérer le cerveau de la reine pour l''étudier. D''après ce que nous savons, il est fort possible que ces silithides soient contrôlés par une intelligence maléfique. Je tremble en pensant à la chose qui peut contrôler des créatures aussi sournoises que les silithides, $N.', 0),
(4508, 'frFR', 'Ils sont fous, $N ! Ils sont incapables de comprendre qu''ils sont confrontés à un danger encore plus grand. La haine féroce qu''ils entretiennent à l''égard de la Horde provoquera notre perte à tous. Je ne sais pas quoi faire de plus pour leur faire prendre conscience de l''imminence de la menace silithide. Il faudrait qu''ils la constatent par eux-mêmes !$B$BJe suis désolée, vous m''apportiez des nouvelles ?', 0),
(4509, 'frFR', 'Ils sont fous, $N ! Ils sont incapables de comprendre qu''ils sont confrontés à un danger encore plus grand. La haine féroce qu''ils entretiennent à l''égard de l''Alliance, provoquera notre perte à tous. Je ne sais pas quoi faire de plus pour leur faire prendre conscience de l''imminence de la menace silithide. Il faudrait qu''ils le constatent par eux-mêmes !$B$BJe suis désolé, vous m''apportiez des nouvelles ?', 0),
(4511, 'frFR', 'Zog zog ! Que puis-je faire pour vous aider aujourd''hui, $C ?', 0),
(4512, 'frFR', 'Certaines des expériences que j''ai menées sont fascinantes. Avec un peu plus de temps, je comprendrais la nature de ces créatures et quelle est leur influence sur le développement de la vie sur Azeroth. . . S''il y a un rapport quelconque.$B$BUne de mes théories, peu appréciée, implique que les Gelées et les Limons soient liés à la création de ce monde. . . Un peu comme s''ils étaient secrétés par lui.$B$BMais je ne pourrais le confirmer ou l''infirmer qu''en étudiant d''autres échantillons.', 0),
(4513, 'frFR', 'Tant de choses à prendre en compte. Mais qu''est-ce que ça signifie ? Et comment cela affecte-t-il la vie des peuples d''Azeroth ?', 0),
(4542, 'frFR', 'Que voulez-vous, $C ? Un message urgent - pour moi ?', 0),
(4561, 'frFR', 'Vous prenez un échantillon de gelée du Cratère d''Un''Goro et le placez dans les différents tubes et vases à bec qui sont sur la table. La gelée se met à bouillir et change de couleur. Lorsque la réaction prend fin, vous apercevez dans la petite boîte de Pétri, vos échantillons de Gelée d''Un''Goro purifiés et d''autres restes.', 0),
(4603, 'frFR', 'Le Décapeur 5200 est vide et attend un objet à nettoyer ainsi que trois pièces d''argent pour démarrer !', 0),
(4604, 'frFR', 'Le Décapeur 5200 est vide et attend un objet à nettoyer ainsi que trois pièces d''argent pour démarrer !', 0),
(4642, 'frFR', 'Comment se passe l''expérience, $N ? Je vais continuer à étudier les échantillons que vous m''avez rapportés ; je commence à comprendre pourquoi ces créatures intéressent Dame Sylvanas. Si elles sont issues des Dieux très anciens, qui sait quels bénéfices on pourrait en retirer.', 0),
(4661, 'frFR', 'Vous prenez un échantillon de gelée de Gangrebois et le placez dans les différents tubes et vases à bec qui sont sur la table. La gelée se met à bouillir et change de couleur. Lorsque la réaction prend fin, vous apercevez dans la petite boîte de pétri, vos échantillons de Gelée de Gangrebois altérés et d''autres restes.', 0),
(4681, 'frFR', 'Une fois que vous aurez inspecté les restes de la créature qui se trouve dans l''eau à l''ouest, je pourrai faire mon rapport au Temple de la Lune à Darnassus. Nous comprendrons peut-être mieux pourquoi ces créatures décident de mettre fin à leur vie en venant s''échouer sur les rivages de Sombrivage.', 0),
(4722, 'frFR', 'Bonjour $N. Vous avez découvert de nouvelles créatures échouées sur le rivage ?', 0),
(4726, 'frFR', 'Vous avez l''Essence de Rejeton, $N ? Je suis impatient de l''étudier.$B$BEn plus. . . mon client n''est pas le type de personne que l''on contrarie.', 0),
(4727, 'frFR', 'Re-bonjour, $N. Avez-vous trouvé d''autres créatures échouées dont l’existence devrait être communiquée au Temple de la lune ?', 0),
(4728, 'frFR', 'Salutations à nouveau, $N ! Qu''est-ce qui vous amène à Auberdine ? Vous venez nous faire part d''une nouvelle découverte ?', 0),
(4730, 'frFR', 'Bonjour à nouveau, $N ! Vous venez nous faire part d''une nouvelle découverte ?', 0),
(4732, 'frFR', 'Salutations à nouveau $N ; avez-vous découvert d''autres choses dont vous souhaiteriez parler au Temple de la Lune ?', 0),
(4734, 'frFR', '$N, avez-vous testé l''Oeufilloscope ?', 0),
(4735, 'frFR', 'Avez-vous les oeufs, $N ? Mon client a entendu dire que vous les collectiez pour moi et il est impatient de pouvoir les tenir dans ses mains !', 0),
(4741, 'frFR', 'Ne me dites pas que vous avez trop peur ! Allez-y !', 0),
(4762, 'frFR', 'La pollution de la Bondissante annonce une catastrophe à Sombrivage. L''échantillon que vous avez va nous aider à mettre en place un plan. . . un plan d''attaque, qui commence à se préciser.', 0),
(4764, 'frFR', 'Avez-vous le fermoir, $N ? Mon client vous paiera généreusement pour l''avoir.', 0),
(4765, 'frFR', 'On m''a dit qu''un messager viendrait et qu''il aurait un cadeau du pic Blackrock.$B$BEst-ce que c''est vous ?', 0),
(4768, 'frFR', 'Avez-vous trouvé la tablette, $N ? Je suis impatiente de me plonger dans ses secrets.', 0),
(4781, 'frFR', 'Des barres d''or, oui. . . Oui. Apportez-m''en une et je verrai si je peux vous préparer un fil. Pendant ce temps, je vous suggère de vous entraîner pour progresser. Votre épreuve la plus difficile est encore devant vous. Et croyez-moi. . . Vous regretterez de ne pas vous être entraîné plus que ça.', 0),
(4783, 'frFR', 'Désolace n''est pas une région tranquille : des nagas, des géants, des satyres, la Légion ardente. . . Toutes ces créatures et le conflit qui oppose les différents clans de centaures rendent cette région peu sûre, si vous ne faites pas attention.$B$BComme je l''ai déjà dit, cette épreuve ne testera pas que votre force et votre ruse, mais aussi votre patience. Soyez prudent, $N.', 0),
(4784, 'frFR', 'Bientôt, $N. Je vous le promets. Cette robe vous ira à merveille et vous confèrera un avantage certain sur vos adversaires.', 0),
(4788, 'frFR', 'Avez-vous été au pic, $N ? Avez-vous les cinquième et sixième tablettes ?', 0),
(4801, 'frFR', 'Au Berceau-de-l''Hiver, vous combattrez de grands félins appelés "sabres-de-givre". Ces bêtes sont incroyablement rapides et vicieuses. Si vous voulez gagner la vitesse des sabres-de-givre, apportez-moi l''Eko que vous trouverez sur eux.$B$BSouvenez-vous, il vous faut la cache de Mau''ari dans votre inventaire si vous voulez chasser l''E''ko.', 0),
(4802, 'frFR', 'Au Berceau-de-l''Hiver, vous combattrez des créatures perdues connues sous le nom de furbolgs Tombe-hiver. Sous l''égide de leur maître, ils ont gagné une force incroyable. Si vous voulez acquérir la puissance des Tombe-hiver, apportez-moi l''E''ko que vous leur prendrez.$B$BSouvenez-vous, il vous faut la cache de Mau''ari dans votre inventaire si vous voulez chasser l''E''ko.', 0),
(4803, 'frFR', 'Au Berceau-de-l''Hiver, vous trouverez de grands ours à la peau très épaisse. Ces ours aux crocs acérés sont bien protégés et peuvent supporter beaucoup. Si vous souhaitez gagner la résistance au feu, apportez-moi l''E''ko que vous trouverez auprès des Crocs acérés.$B$BSouvenez-vous, il vous faut la cache de Mau''ari dans votre inventaire si vous voulez chasser l''E''ko.', 0),
(4804, 'frFR', 'Au Berceau-de-l''Hiver, vous combattrez de grandes créatures ailées nommées des Noroît. Ces bêtes peuvent se servir de la magie de glace. Si vous voulez devenir résistant à la glace, apportez-moi l''E''ko que vous leur prendrez.$B$BSouvenez-vous, il vous faut la cache de Mau''ari dans votre inventaire si vous voulez chasser l''E''ko.', 0),
(4805, 'frFR', 'Au Berceau-de-l''Hiver, vous combattrez de grandes créatures nommées yétis Chardon de glace. Ces bêtes sont lentes mais capables d''éviter de nombreux coups grace à l''épaisseur de leur fourrure. Si vous voulez gagner le pouvoir d''esquiver les attaques, apportez-moi l''E''ko que vous leur prendrez.$B$BSouvenez-vous, il vous faut la cache de Mau''ari dans votre inventaire si vous voulez chasser l''E''ko.', 0),
(4806, 'frFR', 'Au Berceau-de-l''Hiver, vous affronterez des grands géants des glaces, les Cognegivre. Ils sont la force et la puissance incarnées. Si vous voulez vous imprégner de la force des Cognegivre, rapportez-moi les E''kos que vous trouverez sur eux.$B$BSouvenez-vous, le charme de Mau''ari doit être dans votre inventaire pour chasser les E''kos.', 0),
(4807, 'frFR', 'Au Berceau-de-l''Hiver, vous combattrez des créatures qui semblent posséder des pouvoirs magiques innés. Ces Indomptables sont dotés de grands pouvoirs magiques. Si vous voulez voir votre intelligence augmenter, apportez-moi l''E''ko que vous trouverez sur l''un de ces chouettards.$B$BSouvenez-vous, il vous faut la cache de Mau''ari dans votre inventaire si vous voulez chasser l''E''ko.', 0),
(4809, 'frFR', 'Avez-vous les cornes de Noroît, $N ?', 0),
(4810, 'frFR', '$N ! Avez-vous parlé à Felnok ? Vous avez les composants dont j''ai besoin ?', 0),
(4822, 'frFR', 'J''aimerais bien qu''ils fassent d''autres parfums de glace que la fraise. Mais j''ai de la chance, la glace à la fraise est ma préférée !', 0),
(4841, 'frFR', 'Allons, $N, je sais que vous n''avez pas tué votre part encore. Pourchassez-les, et je vous récompenserai à la mesure de ma gratitude.', 0),
(4842, 'frFR', 'L''eau des fontaines semble posséder d''anciennes vertus. . . Je ne sais pas exactement de quoi il s''agit. . .', 0),
(4866, 'frFR', '<John le Loqueteux vous pince. >', 0),
(4867, 'frFR', 'Ah ! Vous avez mon mojo ?', 0),
(4882, 'frFR', 'Au rapport pour une nouvelle mission ?', 0),
(4883, 'frFR', 'Comment puis-je vous aider, $N ?', 0),
(4903, 'frFR', '<Le chef de guerre Goretooth salue. >', 0),
(4941, 'frFR', 'Vous ne voyez pas qu''il ne faut pas m''interrompre ?', 0),
(4976, 'frFR', 'Comment avancent vos recherches sur Tabetha et l''orbe, $N ?$B$BTabetha fut très utile lorsque survinrent les problèmes des arcanes. Je suis certain qu''elle n''aura aucun problème pour vous aider, si vous la trouvez.', 0),
(4983, 'frFR', 'Où est le gobelin ?', 0),
(4984, 'frFR', 'Les loups pestiférés doivent être éliminés, $N. La maladie qu''ils ont contractée n''a pas de remède. J''ai essayé. . . J''ai essayé jusqu''à ce que je succombe à la peste.', 0),
(4985, 'frFR', 'Je vous ai entendu approcher, $N. J''ai perdu la vue, mais je suis encore capable de sentir les choses qui m''entourent. Avez-vous mis fin aux souffrances des grizzlys malades ?', 0),
(5041, 'frFR', 'Comment se passe votre recherche de fournitures, $N ? Je suis sûr que vous avez maîtrisé les hurans facilement.', 0),
(5044, 'frFR', 'Les chamans et les géomanciens des tribus huranes <grogne> invoquent la force d''Agammagan pour les aider au combat et dans leurs rituels, $N.$B$BSi vous voulez la bénédiction d''un surcroît de pouvoir d''Agammagan dans vos sorts, apportez-moi 4 Joyaux de sang et Mutiledent vous aidera.', 0),
(5046, 'frFR', 'Tous ceux qui <grogne> se battent ont besoin de protection. Leurs os doivent être solides. Leur peau résistante.<grogne> Ma tribu le sait bien, et pour renforcer les protections naturelles de nos plumes et de nos dards <grogne> nous faisons appel à la protection d''Agammagan avant de partir pour la guerre.$B$BApportez-moi 4 Joyaux de sang <grogne> et je vous obtiendrai cette même protection.', 0),
(5047, 'frFR', 'Ouais ?', 0),
(5059, 'frFR', 'La porte des toilettes a commencé à se briser dans son pourtour comme si on avait essayé encore et encore de la forcer. Actuellement, elle est solidement verrouillée de l''extérieur.$B$BQuand vous secouez la porte, vous entendez un gémissement guttural ! La créature qui est à l''intérieur, quelle qu''elle soit, n''a pas l''air amicale.', 0),
(5060, 'frFR', 'Un meuble très solide est en face de vous, hermétiquement clos par une serrure intégrée. Le devant du meuble est très rayé et abîmé. Cela pourrait venir de nombreuses et violentes tentatives pour percer les secrets que le meuble dissimule.$B$BSi vous voulez ouvrir ce meuble, il vous faudra trouver la clé.', 0),
(5061, 'frFR', 'Votre retour à Darnassus m''a été annoncé, cependant je vais avoir besoin d''une preuve comme quoi vous avez étudié à Reflet-de-Lune avant de pouvoir vous enseigner votre forme aquatique.$B$BAvez-vous le Pendentif du lion de mer ?', 0),
(5082, 'frFR', 'J''apprécie votre aide !', 0),
(5088, 'frFR', 'Avez-vous tué ce serpent vicieux d''Arikara, $N ?', 0),
(5089, 'frFR', 'Qu''avez-vous là, $N ?', 0),
(5097, 'frFR', 'Une fois les tours repérées, elles deviendront nos cibles prioritaires dans l''attaque d''Andorhal. Je suppose que lorsque nous aurons neutralisé les tours, la menace principale d''Andorhal émergera. À ce moment, nous déclencherons une attaque directe pour contrôler la cité !$B$BVous revenez victorieux, n''est-ce pas ? N''oubliez pas la torche-balise : il faut maintenir notre matériel sous contrôle.', 0),
(5122, 'frFR', 'Le pouvoir de cette chapelle me donne la force de résister à la corruption qui envahit mon coeur. Si je la quitte, je deviendrai un Chevalier de la mort. Mais il existe un médaillon de la foi qui me donnera la force dont j''ai besoin pour partir.$B$BS''il vous plaît, $N, trouvez le médaillon. Il est gardé par Malor le Zélé, un membre fou de la Croisade écarlate qui réside aux tréfonds du Bastion écarlate à l''ouest de Stratholme.', 0),
(5123, 'frFR', 'Et alors, qu''est-ce que c''est, $N ?', 0),
(5124, 'frFR', 'Le temps, c''est de l''argent, $N, et j''ai très peu de l''un comme de l''autre.', 0),
(5127, 'frFR', 'Ne tentez pas…', 0),
(5141, 'frFR', 'Si vous êtes prêt à prendre la décision définitive de devenir un Artisan du cuir d''écaille de dragon, je peux vous prendre comme apprenti. Apportez-moi juste les choses que je vous ai demandées, et je commencerai votre éducation.', 0),
(5143, 'frFR', 'La nature est une force qu''il faut apaiser avant d''espérer apprendre comment modeler sa volonté pour la faire entrer dans vos habits de cuir. Apportez-moi une offrande pour cette force, et je ferai en sorte qu''on vous entende.', 0),
(5144, 'frFR', 'La confection de ce genre d''armure de cuir requiert de la patience et de l''engagement. Une fois que vous avez décidé de partager la destinée des élémentaires, il n''y a pas un moyen de revenir en arrière et de leur tourner le dos. Montrez-moi que vous êtes digne de notre cause, et commençons sans tarder.', 0),
(5145, 'frFR', 'Si vous êtes prêt à prendre la décision définitive de devenir un Artisan du cuir d''écaille de dragon, je peux vous prendre comme apprenti. Apportez-moi juste les choses que je vous ai demandées, et je commencerai votre éducation.', 0),
(5148, 'frFR', 'La nature est une force qu''il faut apaiser avant d''espérer apprendre comment modeler sa volonté pour la faire entrer dans vos habits de cuir. Apportez-moi une offrande pour cette force, et je ferai en sorte qu''on vous entende.', 0),
(5150, 'frFR', 'Dadanga vous regarde alors que vous l''approchez. Elle semble espérer quelque chose…$B$BElle a probablement faim !$B$BIl y a certainement quelque chose qui pousse dans le cratère et qui ferait un parfait en-cas pour un herbivore de grande taille. Dadanga est une grande fille : quoi que vous lui apportiez, il faudra que ce soit en grosse quantité !', 0),
(5154, 'frFR', 'Avez-vous trouvé le livre, $N ?', 0),
(5160, 'frFR', 'C''est bon de vous voir, $N.', 0),
(5166, 'frFR', 'C''est un choix très sage, $N.', 0),
(5168, 'frFR', 'Avez-vous les reliques, $N ?', 0),
(5181, 'frFR', 'Avez-vous trouvé le crâne et l''épée, $N ?', 0),
(5204, 'frFR', 'Vous observez le corps, et le doute n''est pas permis, il s''agit là de la dépouille du chevalier de la Main d''Argent, Trey Lightforge. Pendant un instant, vous pensez à Arko''narin et vous vous demandez si quelqu''un a eu plus d''importance pour vous qu''il n''en a eu pour l''elfe de la nuit prisonnière que vous avez récemment aidée à s''échapper du Fort des ombres.$B$BAprès un moment passé à rassembler vos pensées, vous vous rendez compte que vous ne pouvez ramener les restes du paladin à Jessir sans avoir tué d''abord son tortionnaire.', 0),
(5214, 'frFR', 'Je n''en peux plus, $N ! Il faut que vous m''aidiez ! Je meurs !', 0),
(5218, 'frFR', 'Le chaudron de la peste du Fléau est devant vous, répandant d''énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d''accès anodin.$B$BPuisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste.', 0),
(5220, 'frFR', 'Nous savons que chaque chaudron emploie un mélange de composants différent pour produire sa toxine pestilentielle ; c''est pourquoi il nous faut créer un réactif différent pour chaque chaudron. Votre échantillon de Larmes de Dalson nous servira à déterminer le composant spécifique de ce chaudron.', 0),
(5221, 'frFR', 'Le chaudron de la peste du Fléau est devant vous, répandant d''énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d''accès anodin.$B$BPuisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste.', 0),
(5223, 'frFR', 'Une fois que nous aurons analysé l''échantillon prélevé dans le chaudron du Repaire putride, nous aurons une troisième occasion de lancer un contre-agent dévastateur à la face du Fléau.', 0),
(5224, 'frFR', 'Le chaudron de la peste du Fléau est devant vous, répandant d''énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d''accès anodin.$B$BPuisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste.', 0),
(5227, 'frFR', 'Le chaudron de la peste du Fléau est devant vous, répandant d''énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d''accès anodin.$B$BPuisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste.', 0),
(5232, 'frFR', 'Nous savons que chaque chaudron emploie un mélange de composants différent pour produire sa toxine pestilentielle ; c''est pourquoi il nous faut créer un réactif différent pour chaque chaudron. Votre échantillon de Larmes de Dalson nous servira à déterminer le composant spécifique de ce chaudron.', 0),
(5234, 'frFR', 'Une fois que nous aurons analysé l''échantillon prélevé dans le chaudron du Repaire putride, nous aurons une troisième occasion de lancer un contre-agent dévastateur à la face du Fléau.', 0),
(5242, 'frFR', 'Avec un peu de chance, sans Fel''dan, le Conseil des ombres perdra son efficacité et cessera le combat. Ils se battront les uns contre les autres pour le pouvoir et commenceront à ourdir des plans pour l''avenir. Une occasion parfaite de les attaquer, eux et leurs esclaves démons.', 0),
(5246, 'frFR', 'C''est seulement en lisant les pages de nos textes sacrés que je serai en mesure de discerner si oui ou non je peux vous aider. . .', 0),
(5247, 'frFR', 'La relique doit être remise entre les mains du plus digne de confiance. Elle ne doit pas être dérobée à nouveau…', 0),
(5248, 'frFR', 'Mauuudit… Pour tooouuuujours…', 0),
(5252, 'frFR', 'Voilà longtemps que vous êtes parti, $N. Comment cela s''est-il passé ?', 0),
(5253, 'frFR', 'Oui, $N ?', 0),
(5262, 'frFR', 'Qu''avez-vous là, $N ?', 0),
(5282, 'frFR', 'La compassion est ce qui nous différencie de l''animal, $N. Ne l''oubliez pas…', 0),
(5283, 'frFR', 'Ah, rien de tel qu''un bon bronzage de forge. Vous voyez les meilleurs bronzage aux marques du tablier.', 0),
(5284, 'frFR', '<Ironus est en train de mettre des pièces d''or en petites piles bien nettes. >', 0),
(5301, 'frFR', 'Je frapperai l''acier jusqu''à mon tout dernier souffle.', 0),
(5302, 'frFR', 'À la gloire de la Horde !', 0),
(5305, 'frFR', 'Son tablier ! Où est-il ?', 0),
(5361, 'frFR', 'Quelles nouvelles apportez-vous, $C !  Ah, un message de mon frère, dites-vous ? Eh bien, donnez-moi ce rapport !', 0),
(5382, 'frFR', 'Le Boucher doit être arrêté !', 0),
(5384, 'frFR', 'Soyez prudent, Kirtonos est un combattant aguerri.', 0),
(5385, 'frFR', 'Comment cela s''est-il passé à Jaedenar, $N ?', 0),
(5386, 'frFR', 'Mon sabot me démange et j''ai l''eau à la bouche quand je pense à du Ventre-Rouge frit… Vous en avez sur vous ?', 0),
(5402, 'frFR', 'Une Pierre du Fléau des serviteurs est l''insigne du rang et de la classe du Fléau. Elles se trouvent parfois sur les plus faibles de leurs troupes positionnées dans les Maleterres, bien que le terme "faible" mérite d''être replacé dans son contexte.Les membres du Fléau, où qu''ils soient, ne devraient jamais être sous-estimés.$B$BL''Aube d''argent offre à présent une marque de valeur pour 20 de ces insignes - un échange que je serai heureuse d''effectuer si vous avez amassé suffisamment de pierres du Fléau.', 0),
(5403, 'frFR', 'Une pierre de Fléau des envahisseurs est l''insigne des troupes d''élite du Fléau. On les trouve parfois sur les soldats les plus aguerris stationnés dans les Maleterres. Abattre une telle créature est sans conteste un défi, mais un défi bien agréable pour ceux qui ont accepté notre brevet pour combattre le mal.$B$BL''Aube d''argent offre actuellement une marque de valeur en échange de dix de ces insignes. Apportez-les-moi, et je ferai en sorte que vous receviez votre juste récompense.', 0),
(5404, 'frFR', 'Une Pierre du Fléau des Corrupteurs est l''insigne des Seigneurs du Fléau. Tout être puissant occupant une position d''autorité au sein du Fléau en possède une. Détruire l''une de ces créatures malfaisantes ferait sans doute avancer la cause de l''Aube d''argent, et toutes les bonnes causes !$B$BAu nom de l''Aube d''argent, je vous remettrai une marque de valeur en échange de l''un de ces insignes. Soyez prudent dans votre quête, $N - on ne plaisante pas avec des êtres d''une telle puissance.', 0),
(5406, 'frFR', 'Une Pierre du Fléau des Corrupteurs est l''insigne des Seigneurs du Fléau. Tout être puissant occupant une position d''autorité au sein du Fléau en possède une. Détruire l''une de ces créatures malfaisantes ferait sans doute avancer la cause de l''Aube d''argent, et toutes les bonnes causes !$B$BAu nom de l''Aube d''argent, je vous remettrai une marque de valeur en échange de l''un de ces insignes. Soyez prudent dans votre quête, $N - on ne plaisante pas avec des êtres d''une telle puissance.', 0),
(5407, 'frFR', 'Une pierre de Fléau des envahisseurs est l''insigne des troupes d''élite du Fléau. On les trouve parfois sur les soldats les plus aguerris stationnés dans les Maleterres. Abattre une telle créature est sans conteste un défi, mais un défi bien agréable pour ceux qui ont accepté notre brevet pour combattre le mal.$B$BL''Aube d''argent offre actuellement une marque de valeur en échange de dix de ces insignes. Apportez-les-moi, et je ferai en sorte que vous receviez votre juste récompense.', 0),
(5408, 'frFR', 'Une Pierre du Fléau des serviteurs est l''insigne du rang et de la classe du Fléau. Elles se trouvent parfois sur les plus faibles de leurs troupes positionnées dans les Maleterres, bien que le terme "faible" mérite d''être replacé dans son contexte.Les membres du Fléau, où qu''ils soient, ne devraient jamais être sous-estimés.$B$BL''Aube d''argent offre à présent une marque de valeur pour 20 de ces insignes - un échange que je serai heureux d''effectuer si vous avez amassé suffisamment de pierres du Fléau.', 0),
(5421, 'frFR', 'Je récompense ceux qui me facilitent la vie… J''aime en faire le moins possible, mon ami !$B$BSous les quais de Proie-de-l''Ombre, j''ai placé de nombreux casiers à crustacés. Si vous avez la gentillesse de faire mon travail à ma place et de relever les casiers, je vous récompenserai en vous donnant quelque chose que vous voulez... Voyez où je veux en venir, l''ami ? Je vous donnerai un beau Ventre-Rouge pour 5 crustacés rapportés !', 0),
(5461, 'frFR', 'Un souvenir de mémoire est une prise rare, $N.', 0),
(5462, 'frFR', 'Ne posez pas de questions si vous ne voulez pas de réponses.', 0),
(5463, 'frFR', 'La région qui entoure le Don de Menethil est exceptionnellement froide.', 0),
(5464, 'frFR', '<Leonid frissonne. >', 0),
(5465, 'frFR', 'Avez-vous fait l''impossible ?', 0),
(5466, 'frFR', 'Vous portez le poids de dix mille âmes torturées, $N.', 0),
(5502, 'frFR', 'C''est un plaisir de vous revoir, $N. Avez-vous pu accomplir les tâches pour lesquelles vous vous êtes porté volontaire pendant la Semaine des Enfants ?', 0),
(5508, 'frFR', 'Une Pierre du Fléau des Corrupteurs est l''insigne des Seigneurs du Fléau. Tout être puissant occupant une position d''autorité au sein du Fléau en possède une. Détruire l''une de ces créatures malfaisantes ferait sans doute avancer la cause de l''Aube d''argent, et toutes les bonnes causes !$B$BAu nom de l''Aube d''argent, je vous remettrai une marque de valeur en échange de l''un de ces insignes. Soyez prudent dans votre quête, $N - on ne plaisante pas avec des êtres d''une telle puissance.', 0),
(5509, 'frFR', 'Une pierre de Fléau des envahisseurs est l''insigne des troupes d''élite du Fléau. On les trouve parfois sur les soldats les plus aguerris stationnés dans les Maleterres. Abattre une telle créature est sans conteste un défi, mais un défi bien agréable pour ceux qui ont accepté notre brevet pour combattre le mal.$B$BL''Aube d''argent offre actuellement une marque de valeur en échange de dix de ces insignes. Apportez-les-moi, et je ferai en sorte que vous receviez votre juste récompense.', 0),
(5510, 'frFR', 'Une Pierre du Fléau des serviteurs est l''insigne du rang et de la classe du Fléau. Elles se trouvent parfois sur le plus faible de leurs troupes positionnées dans les Maleterres, bien que le terme "faible" mérite d''être replacé dans son contexte.Les membres du Fléau, où qu''ils soient, ne devraient jamais être sous-estimés.$B$BL''Aube d''argent offre à présent une marque de valeur pour 20 de ces insignes - un échange que je serai heureux d''effectuer si vous avez amassé suffisamment de pierres du Fléau.', 0),
(5517, 'frFR', 'Salutations, puissant $C ! Avez-vous les marques de valeur demandées ? Lorsque vous me les aurez remises, je vous donnerai votre Mantelet de l’aube Chromatique.', 0),
(5519, 'frFR', 'Besoin d’une autre tenue, hein ? Bon, je ne vais nulle part, de toute façon. Amenez-moi les mêmes éléments que l’autre fois, et je vous en ferai une autre.', 0),
(5522, 'frFR', 'Vous êtes celui qui sème le trouble au pic Blackrock, n''est-ce pas ? Avez-vous ce que je vous ai demandé ?', 0),
(5524, 'frFR', 'Salutations, puissant $C ! Avez-vous les marques de valeur demandées ? Lorsque vous me les aurez remises, je vous donnerai votre mantelet de l’Aube chromatique.', 0),
(5525, 'frFR', 'C’est la Clé des menottes gordok – en tous cas, c’est comme ça que l’appellent ces patapoufs. Je ne sais pas qui l’a. Ils le peuvent tous, j’imagine. Les gardes, sans doute…$B$BMais qu’est-ce que je raconte ? Vous l’avez déjà, n’est-ce pas ? Vous l’avez sur vous ?', 0),
(5526, 'frFR', 'Maitenant que le Reliquaire de Pureté Scellé est en votre possession, il est non seulement possible de neutraliser un facteur de corruption, mais aussi de l’étudier, avec toute la prudence requise. Peut-être parviendrons-nous à découvrir de nouveaux moyens de combattre la corruption qui menace sans cesse Azeroth.$B$BJe sais c’est ce qu’aurait voulu Milli…', 0),
(5531, 'frFR', 'Salut, $N ! J''ai appris que vous aviez des oeufs de dragon ? Eh bien, voyons cela !', 0),
(5534, 'frFR', 'Eh bien, $N ? Où est la rune ? Vous êtes un bon employé, n''est-ce-pas ? Vous êtes là pour aider ?$B$BNe me laissez pas douter de l''opportunité de vous payer ce dont nous étions convenus. Comment ? Oh, nous n''avions aucun accord ? Oh, parfait… alors prenez votre temps. Sachez simplement que la somme sera plus légère si vous prenez beaucoup de temps.', 0),
(5536, 'frFR', 'Comment se déroule votre combat contre les satyres, $C ?$B$BSont-ils aussi forts que vous le pensiez ? Plus forts ? Ou peut-être ne sont-ils pas à la mesure de votre propre force.', 0),
(5537, 'frFR', 'Aussi morbide que cela paraisse, il nous faudra un stock suffisant de fragments de squelettes pour faire la couche extérieure de la clé. Ils n''appellent pas ça Clé squelette pour rien, vous savez.', 0),
(5650, 'frFR', 'Nos pouvoirs nous rendent très utiles dans de nombreuses situations, $N. Vous verrez, notre capacité à panser les blessures et à augmenter la capacité de nos compagnons à recevoir des coups sont les talents les plus appréciés auxquels nous avons accès. Que cela ne vous dissuade pas de poursuivre votre apprentissage vers d''autres voies $C, vous pouvez avoir du talent dans de nombreuses disciplines. Mais... si vous voulez détruire vos ennemis grâce à la magie, alors peut-être que les Arcanes vous intéresseront.', 0),
(5724, 'frFR', 'Avez-vous pu trouver quelque chose, $N ? Pourquoi l''un des membres de son clan devait-il mourir sans raison apparente ? Un indice serait utile.', 0),
(5726, 'frFR', 'Avez-vous l''insigne, $N ?$B$BCe serait un outil vital pour que vous infiltriez ce que je crois être la plus grande menace contre la Horde, et pour que nous trouvions enfin la paix sur notre nouvelle terre.$B$BVous découvrirez combien la toile tissée par les orcs et les hommes peut être complexe quand ils sont motivés par la cupidité et le pouvoir. Les complots, la corruption, tout cela vous apparaîtra clairement. Vous vous trouverez au coeur d''une guerre dont vous ne soupçonniez pas même l''existence.', 0),
(5742, 'frFR', 'Je vous en prie, asseyez-vous et écoutez mon histoire.', 0),
(5801, 'frFR', 'Avez-vous terminé la tige de la Clé squelette ? Je suis désolé que vous ayez dû supporter le coût du moule, mais nous devons tous faire notre part dans la lutte contre le Fléau. Quand vous m''aurez donné la clé inachevée, vous serez prêt pour le dernier élément nécessaire à sa finalisation.$B$BÇa ne sera pas facile du tout, mais le travail que vous avez accompli jusqu''à présent pour préparer l''assaut sur Andorhal va commencer à payer maintenant. Vous verrez.', 0),
(5802, 'frFR', 'Avez-vous terminé la tige de la Clé squelette ? Je suis désolé que vous ayez dû supporter le coût du moule, mais nous devons tous faire notre part dans la lutte contre le Fléau. Quand vous m''aurez donné la clé inachevée, vous serez prêt pour le dernier élément nécessaire à sa finalisation.$B$BÇa ne sera pas facile du tout, mais le travail que vous avez accompli jusqu''à présent pour préparer l''assaut sur Andorhal va commencer à payer maintenant. Vous verrez.', 0),
(5841, 'frFR', 'Bonjour ! Quel plaisir de vous rencontrer !$B$BJe vois que vous avez un bon spécial. Donnez-le-moi et je vous donnerai quelque chose en échange.', 0),
(5845, 'frFR', 'Ma foi vous guidera, $N. La Lumière ne connaît pas de frontières.', 0),
(5847, 'frFR', 'Salutations ! C''est un plaisir de vous rencontrer !$B$BJe vois que vous avez un bon spécial. Donnez-le-moi et je vous offrirai quelque chose en échange.', 0),
(5848, 'frFR', 'La peinture, $N. Avez-vous la peinture ?', 0),
(5861, 'frFR', 'Je savais que ce jour arriverait.', 0),
(5862, 'frFR', 'Êtes-vous les renforts de la Main de Tyr ?', 0),
(5882, 'frFR', 'Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d''esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu''à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien$B$B$BEn échange de ces fragments, je vous donnerai du Baume que j''ai déjà préparé.', 0),
(5883, 'frFR', 'Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l''utiliser pour libérer les plantes corrompues que vous rencontrerez.$B$BSi vous avez collecté du Vitriol contaminé, je vous l''échange contre du Baume végétal cénarien que j''ai déjà préparé.', 0),
(5884, 'frFR', 'Une Balise cénarienne permet aux herboristes expérimentés de repérer les créatures corrompues de Gangrebois. Mon travail ici m''a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le Baume végétal cénarien.$B$BLorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les créatures corrompues si vous avez la Balise cénarienne. En échange je vous donnerai du Baume cénarien que j''ai déjà préparé.', 0),
(5885, 'frFR', 'Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparemment inutiles en pâte épaisse qui sert d''agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d''avoir toujours une balise sur vous !$B$BLorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j''ai en réserve.', 0),
(5886, 'frFR', 'Le pouvoir d''un objet magique désenchanté est éprouvé par l''essence qu''il crée. J''ai conçu un moyen de transformer l''essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n''avez pas besoin de Balise cénarienne dans ce cas. N''importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l''affaire.$B$BJe n''ai besoin que d''une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L''essence est très puissante. Il en faut peu pour faire beaucoup !', 0),
(5887, 'frFR', 'Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d''esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu''à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien$B$B$BEn échange de ces fragments, je vous donnerai du Baume cénarien que j''ai déjà préparé.', 0),
(5888, 'frFR', 'Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l''utiliser pour libérer les plantes corrompues que vous rencontrerez.$B$BSi vous avez collecté du Vitriol contaminé, je vous l''échange contre du Baume végétal cénarien que j''ai déjà préparé.', 0),
(5889, 'frFR', 'Une Balise cénarienne permet aux herboristes expérimentés de repérer les créatures corrompues de Gangrebois. Mon travail ici m''a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le Baume végétal cénarien.$B$BLorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les créatures corrompues si vous avez la Balise cénarienne. En échange je vous donnerai du Baume cénarien que j''ai déjà préparé.', 0),
(5890, 'frFR', 'Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparemment inutiles en pâte épaisse qui sert d''agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d''avoir toujours une balise sur vous !$B$BLorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j''ai en réserve.', 0),
(5891, 'frFR', 'Le pouvoir d''un objet magique désenchanté est éprouvé par l''essence qu''il crée. J''ai conçu un moyen de transformer l''essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n''avez pas besoin de Balise cénarienne dans ce cas. N''importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l''affaire.$B$BJe n''ai besoin que d''une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L''essence est très puissante. Il en faut peu pour faire beaucoup !', 0),
(5892, 'frFR', 'Avez-vous les fournitures, $N ? Nous n''en aurons jamais trop !', 0),
(5901, 'frFR', 'Avez-vous les Termites, $N ? Je suis certain que ce n''est pas un problème pour une personne aussi intelligente que vous.$B$BUne fois que nous en aurons assez, $C, nous nous assurerons que plus personne ne pourra utiliser cette scierie !', 0),
(5903, 'frFR', 'Avez-vous trouvé des termitières, $N ? On m''a dit qu''elles étaient présentes dans tout Pestebois.', 0),
(5944, 'frFR', '<Tirion reprend son calme.>', 0),
(6021, 'frFR', 'Avez-vous trouvé la cache, $N ? Avez-vous résolu le problème Zaeldarr ?', 0),
(6022, 'frFR', 'Vous pleurez ? Si c''est trop ''fastidieux'' pour vous, ''héros,'' je vous conseille de retourner voir la Dame noire et de lui dire de quel horrible traitement vous faites l''objet à ma ferme.$B$BMaintenant hors de ma vue !', 0),
(6026, 'frFR', 'Croyez-en le vieux Smokey, $N. La récompense en vaudra la peine. Ces gens de l''Aube d''argent ne lambinent pas quand c''est le moment de payer.', 0),
(6032, 'frFR', 'Avez-vous apporté l''étoffe lunaire, $N ?', 0),
(6042, 'frFR', 'Cela aurait pu être pire. J''aurais pu vous envoyer ramasser du guano de chauve-souris.$B$B<Nathanos vous fixe. >$B$BHem. . . Hé ! Attendez une minute. Où allez-vous ?', 0),
(6061, 'frFR', 'Exercez vos compétences, $N. Domptez un trotteur des plaines adulte.', 0),
(6062, 'frFR', 'Bonne chance, jeune $C.', 0),
(6063, 'frFR', 'Vous apprendrez, $N, et deviendrez un jour un grand $C.', 0),
(6082, 'frFR', 'Avez-vous été capable de dompter le scorpide ?', 0),
(6083, 'frFR', 'Vous devez vous entraîner pour acquérir les compétences nécessaires pour contrôler votre familier efficacement. Avez-vous dompté un clampant de l''écume ?', 0),
(6084, 'frFR', 'Que diriez-vous d''un léopard des neiges, $N ?', 0),
(6085, 'frFR', 'Avez-vous dompté un ours Griffeglace ?', 0),
(6087, 'frFR', 'Avez-vous trouvé un traqueur des prairies ?', 0),
(6088, 'frFR', 'Vous allez bientôt être prêt, $N.', 0),
(6102, 'frFR', 'Je suis fier de votre talent, $N. Avez-vous achevé la dernière tâche que je vous ai confiée ?', 0),
(6122, 'frFR', 'Vous êtes la personne envoyée par le Cercle cénarien de Reflet-de-Lune ? C''est merveilleux ! Nous avons un problème avec ces pauvres daims, et nous acceptons toute l''aide possible.$B$BAvez-vous un échantillon de l''eau dont Dendrite Starblaze m''a parlé ? Il m''a dit que vous en aviez récupérée et que nous pourrions travailler ensemble sur un remède. . .', 0),
(6123, 'frFR', 'Avez-vous les réactifs dont j''ai besoin pour préparer le remède ? Les daims ne vont pas se rétablir par eux-mêmes, vous devez vous dépêcher si nous voulons les sauver !', 0),
(6127, 'frFR', 'Vous êtes la personne envoyée par le Cercle cénarien de Reflet-de-Lune, non ? C''est une chance pour nous ! Nous sommes dans l''impasse avec les gazelles malades qui se trouvent dans les Tarides du nord ; nous acceptons toute l''aide possible.$B$BAvez-vous l''échantillon d''eau dont Dendrite Starblaze a parlé ? Il m''a dit que vous en aviez récupéré un et que nous pourrions travailler ensemble sur un remède. . .', 0),
(6128, 'frFR', 'Avez-vous les réactifs dont j''ai besoin pour faire le baume ? Les gazelles ne vont pas se rétablir par elles-même, vous devez faire plus d''efforts pour les sauver !', 0),
(6133, 'frFR', 'Ne me faites pas attendre, $C.', 0),
(6134, 'frFR', 'Où est mon Fantôm-o-plasme, $N ?', 0),
(6135, 'frFR', 'Je ne vous conseille pas d''accepter ce défi sans aide, $C.', 0),
(6145, 'frFR', 'Si vous réussissez maintenant, alors vous aurez presque gagné mon respect, $C.', 0),
(6146, 'frFR', 'C''est inacceptable, soldat !', 0),
(6162, 'frFR', 'Avez-vous la tête de la bête, $N ? Elle payera pour ses crimes. Que cela soit dû à la corruption ou à la colère de vivre dans cette forêt lugubre, cela ne m''intéresse pas. Aucun furbolg ne vivra longtemps s''il commet ce genre de crime contre ma famille !', 0),
(6163, 'frFR', 'Après avoir été libéré par Sylvanas, j''ai chassé cette bête en vain pendant des mois. Elle a fui et s''est réfugiée à Stratholme. Saleté. . .', 0),
(6164, 'frFR', 'Avez-vous mon livre de compte ? Je suis pressé de reprendre le travail !', 0),
(6284, 'frFR', 'Besseleth est un prédateur sans pitié. . . Je m''inquiète pour ceux qui voyagent sur le sentier des Tisseuses pendant la nuit. C''est là qu''elle et ses enfants s''attaquent aux innocents voyageurs. Je suis tombé moi-même sur ses crocs qui mesurent plus de cinquante centimètres, mais heureusement j''ai réussi à la repousser et à me mettre à l''abri. Je donnerais n''importe quoi pour que ce monstre soit abattu.', 0),
(6361, 'frFR', 'Êtes-vous ici pour un cavalier céleste ? Vous avez quelque chose à transporter ?', 0),
(6362, 'frFR', 'La poussière sur vous épaules semble provenir des Tarides. Avez-vous discuté avec mon ami Jahan ?', 0),
(6363, 'frFR', 'Bienvenue, $C. Que puis-je faire pour vous ?', 0),
(6381, 'frFR', 'Ces graines que vous plantez sont puissantes, résistantes à la corruption, et elles font un solide point de départ pour le renouveau de la vie. Elles grandiront, et grandiront, prévenant tout d''abord la corruption, tout en soignant la terre écorchée, et un jour, elles feront à nouveau des Serres-Rocheuses une forêt luxuriante.$B$BAvez-vous planté toutes les Graines de Gaea ?', 0),
(6389, 'frFR', 'L''avez-vous fait, $N ? Avez-vous lâché les Termites ? La Lumière nous vienne en aide si la Croisade écarlate est capable de tenir la scierie et Âtreval. Ils n''auront aucun des deux. Ils basent leur propagande sur les morts de la dernière guerre. Il faut les éliminer comme des rats enragés.', 0),
(6390, 'frFR', 'L''avez-vous fait, $N ? Avez-vous lâché les termites dans la scierie ?$B$BIl était déjà assez éprouvant que les membres de ma famille perdent leur travail et leur vie, mais voir l''endroit où j''ai grandi tomber aux mains de ces prétendus dévots. . . Beurk !', 0),
(6394, 'frFR', 'Avez-vous pénétré dans le convent de la Lame ardente, $N ? Avez-vous trouvé ma pioche ?', 0),
(6403, 'frFR', 'J''étais. . . j''étais impuissant.', 0),
(6441, 'frFR', 'J''espère que vous allez récupérer rapidement ces cornes, $N. Je repars à Cabestan bientôt !', 0),
(6462, 'frFR', 'Avez-vous trouvé les charmes, $N ? Tant que ces furbolgs les détiennent, mon sang bouillonne de rage !', 0),
(6501, 'frFR', 'Je sens une aura mauvaise émaner de vous, $N. Que transportez-vous qui puisse émettre une telle aura ?', 0),
(6502, 'frFR', 'Le flux du temps ne s''arrête pas et ne ralentit pas, $N. Alors que ma vie est éternelle, la vôtre ne l''est pas. Ne gâchez pas le temps qui vous est imparti. . .', 0),
(6503, 'frFR', 'J''attends votre rapport sur le nombre d''estafettes tuées, $N.', 0),
(6504, 'frFR', 'J''espère que vous trouverez les pages rapidement, $N ! Il faut vraiment que je me remette au travail !', 0),
(6521, 'frFR', 'Avez-vous trouvé l''Ambassadeur, $N ? Est-il mort ?$B$BNous ne pouvons pas permettre au Fléau de prendre pied dans Kalimdor. Il y a assez de menaces comme cela à nos frontières sans devoir en plus les combattre sur deux fronts en même temps.$B$BLa seule chose positive qui ressort de ce que vous m''avez dit, c''est qu''il semble que la vieille bique n''a pas l''air d''avoir été corrompue. Elle doit savoir que le Fléau peut procurer de grands pouvoirs, mais que les Tarides ne lui auraient jamais vraiment appartenu si elle avait accepté le marché avec le Fléau.', 0),
(6522, 'frFR', 'De quoi voulez-vous discuter, $N ? Vous devez penser que c''est important pour me harceler de la sorte.', 0),
(6545, 'frFR', 'Donc vous êtes ici avec mes ordres ? C''est toujours un plaisir de voir une nouvelle recrue avec une nature exubérante et qui persévère.$B$BVous devez apprendre vite si vous voulez rester ici. La menace que représentent les nagas grandit, $N. Je me suis occupé de la défense lors de plusieurs attaques contre cet avant-poste depuis que je suis ici.$B$BMais si vous voulez vous y atteler, parlez à quelqu''un d''autre à l''avant-poste.', 0),
(6546, 'frFR', 'Il y a beaucoup de dangers sur ce chemin, $N. Vous avez intérêt à ne pas l''oublier quand vous traverserez ces terres. La menace que représente l''Alliance est très proche.$B$BNous avons des ennemis sur tous les fronts. Les satyres sont une force redoutable et très répandue dans l''est d’Orneval. De plus, j''ai découvert que les nagas ont envahi une grande partie des terres d''Azshara.$B$BIl est réconfortant de voir que nos effectifs augmentent. Il faut se préparer à ce qui nous attend, $N.', 0),
(6547, 'frFR', 'Gardez l''oeil ouvert, $N. Les elfes se cachent souvent dans les ombres...$B$BNous devons toujours être à l''affût. Nous avons travaillé dur pour gagner cette terre, et les elfes cherchent à nous la voler.$B$BJ''imagine que vous m''avez apporté mes prochains ordres provenant de Kadrak ?', 0),
(6548, 'frFR', 'Les avez-vous tués ?', 0),
(6561, 'frFR', 'Que la Terre-mère soit avec vous, $N.$B$BMaintenir la paix entre la terre et les gens qu''elle porte doit être notre but. Elle a un grand projet pour la nature, et nous y avons tous un rôle à jouer.', 0),
(6563, 'frFR', 'Comment se passe votre recherche des cristaux, $N ? Avez-vous la preuve que les nagas les moissonnent ? J''espère que nous connaîtrons un jour la raison pour laquelle ils récupèrent ces choses.', 0),
(6564, 'frFR', 'Oui, $N ? De quoi avez-vous besoin ? J''ai encore tellement à apprendre sur les cristaux que les nagas collectent.', 0),
(6565, 'frFR', 'L''avez-vous trouvé, $N ? Lorgus doit être arrêté !', 0),
(6566, 'frFR', 'Patience, $N. Écoutez-moi !', 0),
(6568, 'frFR', 'Il n''est pas fréquent de voir une personne de la Horde dans cette partie de Lordaeron. Qu''avez-vous pour Myranda ?', 0),
(6581, 'frFR', 'En provenance directe de Cabestan, des lames du clan Warsong ! Ouais, je les ai ici.$B$BMais qu''avez-vous en contrepartie pour moi ? Vous ne pouvez pas les emporter comme ça, vous savez ! Mon temps coûte cher !$B$BCe dont j''ai besoin, c''est d''une bonne arme à feu pour mes voyages. Une fille doit se protéger savez-vous ? Il y en a une que j''aime particulièrement, et je suis sûre qu''un ingénieur n''aura aucun problème à la fabriquer.$B$BVoilà, si vous m''apportez un Tromblon mortel, je vous donnerai la cargaison de lames. Alors, marché conclu ?', 0),
(6582, 'frFR', '<Brandeguerre siffle. >', 0),
(6583, 'frFR', 'Ne revenez pas avant d''avoir baigné dans le sang de nos ennemis et bu leurs souffrances.', 0),
(6584, 'frFR', 'Ironiquement, le temps nous est compté.', 0),
(6585, 'frFR', 'Changements. . . Je les sens se produire en vous. Passez ce test et alors il ne restera plus que la cérémonie.', 0),
(6601, 'frFR', 'Ne paniquez pas, $N !', 0),
(6602, 'frFR', 'On ne doit pas traiter à la légère Drakkisath, $N. Il est responsable de la mort de milliers de personnes.', 0),
(6610, 'frFR', 'Mes besoins vont avoir raison de moi ! Vite, $N ; avant que je n''entame mes propres réserves.', 0),
(6621, 'frFR', 'Avez-vous vaincu le Chef Murgut, $N ? Avez-vous récupéré son totem Vile-sylve ?', 0),
(6627, 'frFR', 'La vie est pleine d''interrogations, $C. Vous ne pourrez jamais trouver des réponses à toutes, mais avec un peu de temps et de travail, vous gagnerez un peu en connaissances.', 0),
(6628, 'frFR', 'Je pense qu''il n''y a qu''une seule règle que vous ayez à connaître si vous voulez survivre dans ce monde : plus vous en saurez, plus vous en verrez.$B$BSi vous étudiez, si vous observez, alors vous allez commencer à voir des choses qu''aucun autre ne verra, $N.', 0),
(6629, 'frFR', 'Avez-vous tué Grundig Noir-nuage et sa troupe de brutes personnelles ?', 0),
(6642, 'frFR', 'Le sombre fer, bien qu''il soit répandu dans les Profondeurs, est toujours considéré comme un produit de valeur pour la Confrérie. Les armes sacrées de Ragnaros nécessitent du sombre fer.$B$BPour chaque 10 morceaux de Minerai de sombre fer que vous offrirez, une faveur vous gagnerez.', 0),
(6643, 'frFR', 'Malheur à ceux qui défient le destin au Cœur du Magma ! La mort frappe rapidement ! Le châtiment est sans pitié.$B$BDe nombreux membres de la Confrérie ont disparu en recherchant des Noyaux de feu.$B$BDonnez 1 Noyau de feu et vous obtiendrez une faveur de la part de la Confrérie.', 0),
(6644, 'frFR', 'La Confrérie du Thorium comprend vos difficultés, $N. C''est pour cela que Lokthos a reçu les pleins pouvoirs pour négocier.$B$BDonnez 1 Noyau de lave et vous recevrez une faveur de la part de la Confrérie.', 0),
(6645, 'frFR', 'Beaucoup de recettes sacrées exigent du cuir des familiers personnels de Ragnaros.$B$BDonnez 2 Cuirs du Magma, provenant du corps des Chiens du Magma, et vous recevrez une faveur de la Confrérie.', 0),
(6646, 'frFR', 'Les larmes du Seigneur du feu sont vraiment très rares.$B$BOffrez 1 Sang de la montagne et une faveur vous sera accordée par la Confrérie.', 0),
(6681, 'frFR', 'Avez-vous rencontré Milton ?$B$B<Fahrad rit. >', 0),
(6701, 'frFR', 'Nous sommes en guerre avec le Syndicat depuis des années. Ils compensent par leur nombre leur manque de compétences. Nous n''arrivons pas à les tuer assez rapidement pour que cela ait un impact notable sur leur population !$B$BNous avons découvert que le meilleur moyen de gérer leur nombre est de voler leurs Emblèmes. Chaque membre qui la perd est ''puni'' en interne.$B$BDétroussez-les et rapportez les Emblèmes à moi ou aux autres Gardes.$B$BCommencez à Durnholde, au sud d''ici.', 0),
(6741, 'frFR', 'J''ai besoin de plus de Morceaux d''armure, $N ! Vous en avez ?', 0),
(6781, 'frFR', '$N, nous avons besoin de davantage de Morceaux d’armure pour équiper nos troupes !', 0),
(6801, 'frFR', 'Je viens de Thunder Bluff, $N. Cairne en personne m’a diligenté afin que j’assiste le clan Frostwolf en ces temps difficiles.$B$BMais ne perdons pas plus de temps. Vous devez abattre nos ennemis et me rapporter un peu de leur sang. Une fois que le sang aura été collecté, le rituel d’invocation pourra commencer.$B$BLa victoire sera certaine lorsque le Seigneur élémentaire sera lâché sur l’armée des Stormpike.', 0),
(6804, 'frFR', 'Avez-vous les Bracelets ?', 0),
(6805, 'frFR', 'La lâcheté n''est pas un sentiment et une attitude que nous apprécions, $C. Allez en Silithus et montrez-nous votre bravoure.', 0),
(6821, 'frFR', 'Avez-vous l''Œil, $C ? Avez-vous la force et le courage pour entrer dans le pic Blackrock ?', 0),
(6824, 'frFR', 'Avez-vous vaincu Lucifron et les autres, $N ? Avez-vous récupéré les Mains de nos ennemis ?', 0),
(6825, 'frFR', 'Nous devons préparer la nouvelle flotte des Chevaucheurs de guerre, $N ! Mes Chevaucheurs sont prêts pour combattre au centre du champ de bataille, mais d’abord nous devons les mettre en appétit et les préparer à l’assaut.$B$BIl me faut suffisamment de chair de soldats Stormpike pour nourrir la flotte ! Des centaines de kilos de viande ! Je suis sûr que vous pouvez vous occuper de ça, n’est-ce pas ?', 0),
(6826, 'frFR', 'Vous avez bien travaillé, $N, mais nous ne faisons que commencer !$B$BMes Chevaucheurs de guerre doivent goûter à la chair de leurs cibles. Cela permettra d’obtenir comme qui dirait une frappe chirurgicale contre nos ennemis !$B$BMa flotte est la seconde plus puissante de toute notre force aérienne. Ce sont eux qui frapperont les plus puissants de nos adversaires. Pour cela, je le répète, il nous faut de la chair des Lieutenants de l''Alliances.$B$BFaites vite !', 0),
(6827, 'frFR', 'J’ai subi un emprisonnement inhumain dans ce trou à rats. Vous pouvez me croire quand je vous dis que je n’aspire qu’à la vengeance !$B$BNous devons agir avec prudence, néanmoins.$B$BD’abord, mes Chevaucheurs de guerre ont besoin de cibles, de cibles prioritaires. Je me dois de les nourrir avec la chair des commandants de l''Alliance. Malheureusement, ces petits couards sont retranchés loin derrière leurs lignes. Vous avez du pain sur la planche, on peut le dire !', 0),
(6881, 'frFR', 'Le clan Frostwolf est protégé par un poison constitué d''énergie élémentaire. Leurs chamans ont développé des pouvoirs qui nous détruiront jusqu''au dernier, si on laisse les choses suivre leur cours.$B$BLa menace est maintenant trop importante pour le Cercle. Ivus doit être appelé à l''aide.$B$BLes soldats Frostwolf portent des charmes élémentaires, appelés Cristaux de tempête. Nous pouvons utiliser ces charmes pour invoquer Ivus. Partez maintenant et récupérez ces cristaux, $N !', 0),
(6941, 'frFR', 'Les troupes d''élite de la Horde en faction sur la ligne de front doivent être engagées ! Je vous demande de tailler dans cette bande de sauvages et d''en faire chuter les effectifs. Revenez me voir avec les Médailles de leurs Lieutenants et de leurs Légionnaires. Lorsque un nombre suffisant de cette racaille aura étouffé dans son propre sang, je ferai déployer la force aérienne.', 0),
(6942, 'frFR', 'Mes gryphons sont en place pour donner l''assaut frontal, mais ils ne peuvent pas le faire tant que les rangs ennemis n''auront pas été réduits préalablement.$B$BLes guerriers de la Horde chargés de tenir la ligne de front portent des Médailles qu''ils arborent fièrement sur leurs poitrines. Arrachez ces Médailles à leurs cadavres et rapportez-les-moi.$B$BUne fois que les effectifs ennemis de la ligne de front auront été suffisamment réduits, je ferai donner la force aérienne !', 0),
(6943, 'frFR', 'Leur moral est au plus bas. Depuis l''échec cuisant de notre dernière attaque aérienne contre la Horde, ils refusent de voler ! C''est à vous maintenant de remonter leur moral.$B$BRetournez sur le champ de bataille et frappez le coeur du commandement de la Horde. Abattez leurs commandants et leurs gardiens. Revenez me voir quand vous aurez récupéré autant de Médailles que peut en contenir votre sac ! Je vous promets que lorsque mes gryphons verront ce butin et qu''ils sentiront l''odeur de leur sang sur les Médailles, ils seront prêts à reprendre le combat. Partez maintenant !', 0),
(6985, 'frFR', 'Êtes-vous entré dans la mine de Gouffrefer, $N?  Avez-vous pillé les fournitures ?', 0),
(7001, 'frFR', 'Sans votre aide, les chevaucheurs de loups Frostwolf n''auraient pas de montures à chevaucher. Vous nous avez rendu un grand service !', 0),
(7002, 'frFR', 'Certains de nos soldats sont occupés à capturer des loups pour le maître des écuries. D’autres doivent nous fournir les accessoires nécessaires à la monte. Je parle des harnais, bien sûr.$B$BVous devez vous procurer les matières premières sur les béliers de la région. Oui, ceux-là même que les Stormpike utilisent comme montures !$B$BTuez-les et ramenez-moi leurs peaux. Lorsque vous en aurez assez, nous fabriquerons des harnais, et les Chevaucheurs de loups Frostwolf entreront dans la bataille !', 0),
(7026, 'frFR', 'La brigade Stormpike ne peut pas charger à cru ! Il nous faut des harnais pour nos montures. Après tout, nous ne sommes pas des sauvages.$B$BNous pourrions tuer les béliers qui s''aventurent près de notre base pour fabriquer ces harnais, mais ce serait idiot : nous en avons besoin comme montures.$B$BVous devez attaquer la base ennemie, tuer leurs loups de monte et prendre leur peaux. Ramenez-les-moi, et nous en ferons des harnais pour la cavalerie. Allez !', 0),
(7027, 'frFR', 'Sans votre aide, les monteurs de béliers Stormpike n''auraient pas de montures à chevaucher. Vous nous avez rendu un grand service !', 0),
(7029, 'frFR', 'Si vous êtes capable de soigner la plante, elle sera de nouveau à même de grandir. Nous devons faire notre possible en ce sens, $N...', 0),
(7041, 'frFR', 'Si vous êtes capable de soigner la plante, elle sera de nouveau à même de grandir. Nous devons faire notre possible en ce sens, $N...', 0),
(7061, 'frFR', 'Je vous souhaite la bienvenue à Mulgore et dans notre humble communauté de Thunder Bluff, ami. Je prends toujours le temps de m''intéresser à ceux qui se sentent concernés par le royaume, son peuple et ses traditions. Est-ce pour cette raison que vous venez me voir ?', 0),
(7067, 'frFR', 'Qu''avez-vous décidé, $N ? Pouvez-vous m''aider ? Oserez-vous mettre le pied sur le sol sacré, pour m''aider à fonder une grande tribu de centaures ?', 0),
(7070, 'frFR', 'Avez-vous déjà effectué le voyage ? Je réalise que cela doit être relativement dangereux, mais si réussissiez, le jeu en vaudrait la chandelle.', 0),
(7161, 'frFR', 'Allez, $N, on se réveille ! Ce n’est pas un rêve. Vous êtes vraiment au beau milieu d’une bataille !', 0),
(7168, 'frFR', 'La plupart des gens ne vivent pas assez longtemps pour s’élever au-dessus de leur propre médiocrité. Vous avez montré que vous êtes un soldat exemplaire, $C. L’heure est venue.$B$BPrésentez votre insigne.', 0),
(7169, 'frFR', 'Toute la base parle de vos exploits sur le Champ sanglant ! Vous avez porté des coups sévères à l’ennemi – et à son moral ! Pour cela, vous avez mérité de progresser au sein des Stormpike.$B$BPrésentez votre insigne.', 0),
(7170, 'frFR', 'Je m’interroge, $N. Lorsque vous regardez dans les yeux de l’ennemi, y voyez-vous la peur ? Se cachent-ils plutôt que de vous faire face ? Ils doivent bien se rendre compte qu’ils sont vaincus !$B$BVous avez mérité que la Garde vous traite avec révérence. Présentez votre insigne !', 0),
(7171, 'frFR', 'Devant moi se tient un héros de l’Alliance.$B$B<Le Lieutenant Haggerdin salue.>$B$BRares sont ceux qui ont obtenu un tel grade parmi les Stormpike. J’ai vu l’ennemi tomber devant vous. J’ai vu leur résolution s’effondrer devant votre présence. Lorsque vous entrez dans la mêlée, vous devenez un point de ralliement pour nos forces !$B$BPrésentez votre insigne.', 0),
(7172, 'frFR', 'Laissez-les entendre votre voix, commandant $N ! Ils connaîtront la peur. Montrez-leur le pouvoir des Stormpike !$B$BPrésentez votre insigne.', 0),
(7341, 'frFR', 'Bonjour, $R. Je suis Kolark, $C de primes de Thunderbluff. J’ai beaucoup voyagé de par le monde et j’ai beaucoup vu.$B$BAu cours de mes voyages dans les mers du Sud, j’ai découvert ces merveilleuses flèches à pointes de thorium. Hélas, j’ai des flèches à ne plus savoir quoi en faire, mais j’ai épuisé ma provision d’obus. Aucun tauren qui se respecte ne se ferait prendre à se servir d’un arc – trop fragile. Ces flèches ne me servent à rien !$B$BJe vous propose un marché : vous m’apportez des obus en thorium, et je vous donne un nombre égal de flèches à pointes de thorium. Entendu ?', 0),
(7342, 'frFR', 'Vous y croyez, vous ? Les gars qui ont fait le dernier chargement de munitions de Kharanos ont cochonné le boulot ! Tout ce que nous avons comme munitions, ce sont ces saletés de flèches bonnes à rien ! Qu’est-ce que je suis censé faire avec 500 000 flèches à pointes de thorium, vous pouvez me le dire ?$B$BJe vais vous dire. Si vous pouvez m’amener des obus en thorium, je vous file ces flèches à pointe de thorium, et tout de suite ! Entendu ?', 0),
(7385, 'frFR', 'Vous avez la possibilité d’offrir des quantités de sang prises à l’ennemi plus importantes. Je serais content d’accepter des offrandes de quelques litres, $N.', 0),
(7386, 'frFR', 'Parfois, vous serez bloqué dans la bataille pendant des jours ou des semaines. Profitez de ces longues périodes d’activité pour ramasser des grappes de cristaux de tempête Frostwolf.$B$BLe Cercle accepte de telles offrandes, $N.', 0),
(7429, 'frFR', 'C’est la Clé des menottes gordok – en tous cas, c’est comme ça que l’appellent ces patapoufs. Je ne sais pas qui l’a. Ils le peuvent tous, j’imagine. Les gardes, sans doute…$B$BMais qu’est-ce que je raconte ? Vous l’avez déjà, n’est-ce pas ? Vous l’avez sur vous ?', 0),
(7461, 'frFR', 'Prenez garde, aventurier. Le prince est… persuasif.', 0),
(7463, 'frFR', 'Oui ? Je vous connais ?', 0),
(7484, 'frFR', 'Encore vous ? Que voulez-vous, cette fois ?', 0),
(7498, 'frFR', 'Vous avez récupéré un livre !', 0),
(7499, 'frFR', 'Vous avez récupéré un livre !', 0),
(7500, 'frFR', 'Vous avez récupéré un livre !', 0),
(7501, 'frFR', 'Vous avez récupéré un livre !', 0),
(7502, 'frFR', 'Vous avez récupéré un livre !', 0),
(7503, 'frFR', 'Vous avez récupéré un livre !', 0),
(7504, 'frFR', 'Vous avez récupéré un livre !', 0),
(7505, 'frFR', 'Vous avez récupéré un livre !', 0),
(7506, 'frFR', 'Vous avez récupéré un livre !', 0),
(7507, 'frFR', 'Ah, une de nos plus grandes compilations. Celle-ci manquait depuis une éternité.', 0),
(7508, 'frFR', 'Excellent, commençons tout de suite…', 0),
(7509, 'frFR', 'Peut-être qu’un jour, un autre portera la lame prismatique.', 0),
(7563, 'frFR', 'Avez-vous vu les êtres-chouettes enragés, $N ? La magie de ces créatures est puissante, et elle se concentre dans le sang qui court dans leurs veines torturées.', 0),
(7564, 'frFR', 'Vous avez quelque chose pour moi ? Ce n’est pas une grosse araignée bien juteuse, par hasard ? Ou peut-être un cafard ? J’espère qu’il est encore vivant… J’aime bien les mâcher quand ils sont encore vivants…', 0),
(7581, 'frFR', 'Il faut impérativement utiliser le sang des satyres Follengeance.', 0),
(7582, 'frFR', 'Les Hederine ne vous donneront pas volontairement leurs précieuses gemmes, $N.', 0),
(7583, 'frFR', 'Hrm ? Hé bien ?', 0),
(7602, 'frFR', 'Ne le dites à personne, mais Niby est un peu simplet.', 0),
(7603, 'frFR', 'Vous vous êtes perdu ?', 0),
(7624, 'frFR', 'Le goût du coeur d’Ulathek est déjà sur mes lèvres. La chair d’un traître est si douce…', 0),
(7625, 'frFR', 'Avez-vous été à Jaedenar, $N ? Le seigneur Banehollow vous a-t-il donné de la Poussière d’étoiles ?', 0),
(7626, 'frFR', 'Vous avez ces élixirs, $N ? Mor’zul m’a dit que vous aviez besoin d’une Cloche de Dethmoora, et il faut beaucoup de puissance de l''ombre pour en fabriquer !', 0),
(7627, 'frFR', 'La Roue de la Marche noire n’est pas facile à fabriquer, et nécessite beaucoup de matériel. Avez-vous tout ce qu’il me faut ?', 0),
(7628, 'frFR', 'Avez-vous ces écailles de dragon, $N ? Je ne commencerai à travailler sur la chandelle que lorsque je les aurai… Sans cela, je risque de faire sauter tout le camp !', 0),
(7629, 'frFR', 'Avez-vous été à la Scholomance, $N ? Le diablotin a-t-il imprégné le parchemin avec la Poussière d’étoiles ?', 0),
(7630, 'frFR', 'Avez-vous l’arcanite, $N ? Dès que je l’aurai, je fabriquerai un nouveau bocal pour le diablotin J’eevee.', 0),
(7634, 'frFR', 'Bienvenue, jeune $C.', 0),
(7635, 'frFR', 'Je suis certain que vous n’aurez guère de mal à trouver et à tuer un dragon noir, $N. Ne me faites pas perdre mon temps en vains bavardages.', 0),
(7636, 'frFR', 'Ne vous laissez pas tromper par leurs déguisements !', 0),
(7637, 'frFR', 'Je vous salue, noble $C ! J’ai garni mon encensoir de l’encens le plus frais et je l’ai béni par trois fois. Votre donation nous permettra non seulement de fabriquer un nouvel encensoir, mais aussi de compléter nos réserves de nourriture pour les nécessiteux de Forgefer.', 0),
(7639, 'frFR', 'Bon retour parmi nous, $N. Avez-vous acheté l''encensoir d''exorcisme ?', 0),
(7640, 'frFR', 'C’est bon de vous revoir, $N. Votre tâche à Val-Terreur est-elle accomplie ?', 0),
(7643, 'frFR', 'L’Ancien esprit équin vous regarde. Il a l’air interrogateur, comme s’il attendait quelque chose de vous.', 0),
(7644, 'frFR', '$N, vous êtes de retour ! Vous avez pu vous dépêtrer de Merideth Carlson et de Tendris Crochebois ? Honnêtement, il y a des moments où je ne sais pas trop lequel des deux est le pire…', 0),
(7645, 'frFR', 'J’ai prouvé que vous aviez tort, n’est-ce pas ? J’ai prouvé que vous aviez tous tort ! J’AVAIS RAISON DEPUIS LE DEBUT !', 0),
(7646, 'frFR', 'Vous êtes presque au bout de la route, $N. Il ne vous reste plus qu’à sacrifier ces derniers biens matériels, et vous serez à l’aube de grandes choses. Je le sens dans toutes les fibres de mon être !', 0),
(7648, 'frFR', 'Vous progressez bien, $N. Une fois que vous aurez achevé votre caparaçon, nous vous confierons de nouvelles tâches.', 0),
(7649, 'frFR', 'Vous avez récupéré un livre !', 0),
(7650, 'frFR', 'Vous avez récupéré un livre !', 0),
(7651, 'frFR', 'Vous avez récupéré un livre !', 0),
(7667, 'frFR', 'Vous demander une aide matérielle me met mal à l’aise, mais mon Clairvoyant, l’objet que j’espère parvenir à terminer, ne peut pas fonctionner sans diamants. Je ne vous en voudrais pas si vous refusiez de m’aider.', 0),
(7702, 'frFR', 'Ne vous laissez pas tromper par mes drôles de lunettes, $N. C''est moi le cerveau ici.', 0),
(7703, 'frFR', 'Ha, vous l’avez pas trouvé, patron ? Peut-être que les histoires des vieux, c’est des menteries… c’est dur de croire qu’un vilain elfe peut voler des trucs au roi des Gordok !', 0),
(7729, 'frFR', 'Nous devons vous peser avec et sans vêtements pour être sûrs.', 0),
(7730, 'frFR', 'Comment se passe votre chasse, $N?  Êtes-vous ici pour me faire part de votre succès ?', 0),
(7735, 'frFR', 'Qu’y a-t-il, $N ? Vous avez quelque chose de spécial pour moi ?', 0),
(7736, 'frFR', 'Assez perdu de temps à bavarder, $R. Il est temps de nous concentrer sur le réapprovisionnement de nos réserves de flux embrasé qui s''amenuisent.$B$BVoici ce que je veux que vous me rapportiez :$B$B*Ecailles d''incendosaure.$B$B*Sang-royal.$B$B*Charbon.$B$BJe prendrai tout ce que vous me donnerez !$B$BEt vous le ferez vite si vous voulez bien vous entendre avec la Confrérie.', 0),
(7738, 'frFR', 'Qu’y a-t-il, $N ? Vous avez quelque chose de spécial pour moi ?', 0),
(7783, 'frFR', 'J’aurais voulu être là pour voir son expression lorsque vous avez placé le coup mortel, $N.', 0),
(7785, 'frFR', 'Le libérerez-vous de sa prison éternelle ?', 0),
(7786, 'frFR', 'S''il le faut, mettez le monde à genou !', 0),
(7787, 'frFR', '<Demitrian tremble en votre présence. >', 0),
(7795, 'frFR', '$N, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d''un type de tissu : l''étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?$B$BSi vous acceptez, apportez-moi toute l''étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.', 0),
(7800, 'frFR', '$N, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d''un type de tissu : l''étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?$B$BSi vous acceptez, apportez-moi toute l''étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.', 0),
(7803, 'frFR', 'Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.$B$BJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.', 0),
(7805, 'frFR', '$N, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d''un type de tissu : l''étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?$B$BSi vous acceptez, apportez-moi toute l''étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.', 0),
(7807, 'frFR', 'Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tous les exilés de Gnomeregan pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.$B$BSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.', 0),
(7808, 'frFR', 'Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.$B$BJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.', 0),
(7811, 'frFR', '$N, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d''un type de tissu : l''étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?$B$BSi vous acceptez, apportez-moi toute l''étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.', 0),
(7818, 'frFR', '$N, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d''un type de tissu : l''étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?$B$BSi vous acceptez, apportez-moi toute l''étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.', 0),
(7819, 'frFR', 'Je vous salue une nouvelle fois, $N ! Nous avons sans cesse besoin d''étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur de Fossoyeuse soient reconnus à leur juste valeur.$B$BLorsque vous serez prêt à me les remettre, je les accepterai volontiers.', 0),
(7820, 'frFR', 'Nous acceptons les dons de laine. En fait, un don de soixante morceaux de laine vous vaudrait la reconnaissance de tout Thunder Bluff pour votre générosité. Nos réserves en sont au point où il nous manque seulement ces soixante morceaux de laine, le reste nous sera fourni par d’autres.$B$BSi vous avez soixante morceaux de laine et que vous êtes prêt à les donner, je peux les prendre dès maintenant.', 0),
(7821, 'frFR', 'Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.$B$BJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.', 0),
(7823, 'frFR', '$N, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d''un type de tissu : l''étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?$B$BSi vous acceptez, apportez-moi toute l''étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.', 0),
(7824, 'frFR', '$N, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d''un type de tissu : l''étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?$B$BSi vous acceptez, apportez-moi toute l''étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.', 0),
(7827, 'frFR', 'Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.$B$BJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.', 0),
(7831, 'frFR', 'Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue à Orgrimmar !$B$BSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.', 0),
(7834, 'frFR', 'Nos réserves de soie sont très basses – comme celles de toutes nos étoffes, en fait. Heureusement, vous n’êtes pas le seul à nous en fournir. En mettant bout à bout toutes les contributions, nous devrions atteindre nos objectifs, à condition que vous nous remettiez soixante morceaux de soie.$B$BJe dois ajouter qu’un don de cette ampleur augmenterait certainement votre statut dans notre communauté ! Si vous avez soixante morceaux de soie et si vous êtes prêt à les donner, je peux les prendre immédiatement.', 0),
(7835, 'frFR', 'Nous arrivons à court de tisse-mage, et votre aide serait la bienvenue pour reconstituer nos réserves ! En comptant sur toute la communauté pour le reste, il vous suffirait de donner 60 morceaux de tisse-mage pour que nos objectifs soient atteints. Bien sûr, je vous promets qu’une telle générosité ne passerait pas inaperçue auprès des trolls Darkspear !$B$BSi vous avez les soixante morceaux de tisse-mage sur vous, et si vous êtes prêt à les donner, je suis en mesure de les récupérer dès maintenant.', 0),
(7836, 'frFR', '$N, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d''un type de tissu : l''étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?$B$BSi vous acceptez, apportez-moi toute l''étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons.', 0),
(7838, 'frFR', 'Salut, l''terrien ! Ramenez-moi 12 bijoux du Maître de l''arène et vous serez le Grand maître de l''arène des Gurubashi ! Arrrr !', 0),
(7842, 'frFR', 'Le dernier message va leur faire salement peur. Ou alors, il va les mettre très, très en colère.', 0),
(7881, 'frFR', 'Nous autres forains de la foire de Sombrelune marchons beaucoup.  Nous marchons d''un site à l''autre... en fait, vous ne nous verrez jamais assis !  Pas étonnant que nous usions autant de bottes !  Nous avons besoin de bottes qui soient à la fois robustes et élégantes, et les bottes en cuir estampé correspondent bien à cette description.$B$BVous !  Vous êtes un artisan du cuir : faites-moi des bottes en cuir estampé et je vous donnerai un bon de la foire de Sombrelune pour votre peine.', 0),
(7884, 'frFR', 'Yebb travaille à de nouvelles attractions pour son zoo, y compris un enclos marécageux pour un garçon élevé par des crocilisques, et peut-être un murloc. Il nous faudra de belles jambières étanches si nous ne voulons pas être trempés pendant le montage et le démontage. Je crois que des jambières en écailles de tortue conviendraient le mieux.$B$B$N, pouvez-vous nous faire ces jambières ? Si oui, vous recevrez un gros paquet de bons de la foire de Sombrelune en récompense...', 0),
(7885, 'frFR', 'Vous ne le savez peut-être pas, mais faire fonctionner une foire ambulante est très coûteux !  Tout s''use si vite que c''est un miracle si nous faisons des bénéfices.$B$BEn raison de tous ces coûts cachés, nous sommes toujours à la recherche de moyens d''entretenir notre matériel à moindres frais.  Nos tentes, par exemple, se déchirent souvent, mais les renforts d''armure en cuir sont parfaits pour les raccommoder.  Pouvez-vous m''apporter des renforts d''armure ?  Cela nous ferait faire de sacrées économies !  Si vous pouvez faire ça pour moi, je vous donnerai une poignée de bons de la foire de Sombrelune...', 0),
(7889, 'frFR', 'Être la femme la plus forte du monde demande beaucoup de travail ! Mon ensemble de poids commence à être trop léger et pour rester en forme il m''en faut plus !$B$BCroyez-vous que vous pourriez me procurer des cailloux ? Si oui, je vous donnerai un bon de la foire de Sombrelune.', 0),
(7890, 'frFR', 'Pour mon entraînement, j''aime fixer un bâton entre des silex à aiguiser lourds puis soulever le bâton au-dessus de ma tête. Ce n''est pas facile, mais on ne devient pas la femme la plus forte du monde en restant assise !$B$BPouvez-vous m''aider ? Il me faut plus de silex à aiguiser, apportez-m''en et je vous donnerai des bons de la foire de Sombrelune.', 0),
(7891, 'frFR', 'Je travaille à un nouveau costume pour quand j''aurai mon propre stand de femme la plus forte du monde !  En ce moment, je cherche des bracelets.  Ils ne doivent pas être trop grands parce que les gens veulent voir mes muscles, mais je veux quand même qu''il y ait de la couleur, vous comprenez ?$B$BPourquoi pas des bracelets en fer émeraude, $N ? Pouvez-vous me faire des bracelets en fer émeraude ?  Si oui, j''aurai un beau paquet de bons de la foire de Sombrelune pour vous.', 0),
(7892, 'frFR', 'Pour mon numéro de femme la plus forte du monde, j''ai prévu de demander des objets au public et de les écraser avec une grande masse noire !$B$BPouvez-vous me faire une grande masse noire, $N ?', 0),
(7893, 'frFR', '$N, dans ma quête pour devenir la femme la plus forte du monde, j''ai parcouru le monde et appris les secrets de musculation de lointains maîtres des poids, de gourous de la force et de manuels anciens.  Je connais maintenant des exercices interdits qui tueraient les faibles et estropieraient les non-initiés !$B$BCes prouesses de force et de conditionnement requièrent un entraînement à l''aide des pierres à aiguiser les plus denses.  $N, pouvez-vous trouver ou fabriquer ces pierres et me les apporter ? Je vous donnerai des bons en échange…', 0),
(7894, 'frFR', 'Yebb travaille à une nouvelle attraction pour l''Etonnante Ménagerie qui stupéfiera et ravira les visiteurs !  Mais cela demandera beaucoup de travail et beaucoup de matériel...$B$BY compris des Modulateurs de cuivre.  Il nous faut beaucoup de modulateurs pour les parties mécaniques de l''attraction.  Apportez-moi des Modulateurs de cuivre et je vous donnerai un bon de la foire de Sombrelune en échange.', 0),
(7896, 'frFR', 'Quand j''aurai enfin mon stand, je voudrai m''offrir de la publicité !  Quel meilleur moyen y aurait-il pour cela que des feux d''artifice ?$B$BOui, certains pensent sûrement que l''odeur d''un chaudron bouillonnant rempli des têtse de vos ennemis serait une meilleure idée pour attirer les foules, mais... nous ne sommes pas seuls ici.  Il faudra donc que ce soit des feux d''artifice !$B$BApportez-moi des feux d''artifice verts, $N, et j''aurai plein de bons de la foire de Sombrelune pour vous.', 0),
(7897, 'frFR', 'La principale raison pour laquelle je ne peux pas ouvrir mon stand, c''est que... rien n''est en état de marche !  Il me faut des trousses de réparation mécanique pour réparer tout ça !$B$BPouvez-vous m''apporter ces trousses, $N ?  En échange, je vous donnerai... des trousses de bons de la foire de Sombrelune.  Qu''en dites-vous ?', 0),
(7898, 'frFR', 'Yebb Nebblegear, comme moi, travaille à une nouvelle attraction. D''après Nebb, elle est tellement stupéfiante qu''elle attirera des gens du monde entier... et elle nous rendra tous très, très riches !$B$BIl dit qu''il lui faut des rouages en thorium pour sa construction et il veut que je me les procure pour lui. Qu''en pensez-vous, $N ? Savez-vous où je pourrais en trouver ? Si vous êtes ingénieur, pourriez-vous en fabriquer ? Voulez-vous en échanger contre des bons de la foire de Sombrelune ?', 0),
(7899, 'frFR', 'Pour attirer beaucoup de monde, il faut avant tout appâter les gens avec des gadgets et des bibelots ! Pouvez-vous m''aider ?$B$BJ''ai besoin de petites pattes en fourrure pour en faire des lots.  Vous pouvez les trouver sur les félins des Tarides ou de Sombrivage....$B$BApportez-moi des pattes et je vous les échangerai contre un bon de la foire de Sombrelune.', 0),
(7901, 'frFR', 'C''est vraiment incroyable, ce à quoi les gens peuvent trouver de la valeur !  Prenez par exemple un bâton en bois avec une Queue fournie soyeuse attachée après.  Vous et moi savons qu''une choses pareille n''a pas grande valeur... mais si vous donnez à cette camelote un chouette nom du genre de "Queue sauvage" et la mettez dans une belle boîte, les gens croiront que ça a de la valeur.  La pacotille devient un trésor !$B$BCherchez pour moi des Queues fournies soyeuses sur les loups de Désolace et des Terres ingrates, et je vous donnerai des bons de la foire de Sombrelune.', 0),
(7902, 'frFR', 'L''imagination est une chose incroyable. Grâce à elle, la moindre colline peut sembler être la plus haute montagne.  L''ombre la plus inoffensive peut paraître sortie d''une terrible cauchemar !$B$BIci, à la foire de Sombrelune, nous laissons libre court à l''imagination de nos visiteurs !  Mais pour les aider à laisser s''épanouir leur imagination... nous devons parfois faire preuve de ruse.$B$BIl me faut des plumes vibrantes pour une de mes attractions.  Vous pouvez les prendre sur les oiseaux des régions les plus dangereuses d''Azeroth.  Apportez-moi les plumes et vous recevrez beaucoup de bons !', 0),
(7903, 'frFR', 'Vous arrive-t-il parfois d''errer dans une grotte, tard la nuit, à la recherche d''aventures ?  Oui ?  Vraiment ?  Alors vous avez sûrement vu les yeux menaçants des chauves-souris qui vous fixent d''en haut, attendant que vous baissiez votre garde pour sucer votre sang !$B$BC''est effrayant, vous ne trouvez pas ?  Bien sûr !  Évidemment les yeux des chauves-souris sont effrayants !$B$BVoulez-vous me rapporter des yeux de chauve-souris maléfique, $N?  Il me les faut pour... quelque chose que je suis en train de mettre au point.  Quelque chose d''effrayant.$B$BVous pouvez les trouver sur les chauves-souris des Maleterres de l''est.', 0),
(7927, 'frFR', 'Je vois que vous avez réussi à réunir une suite de Portails ! Félicitations !', 0),
(7930, 'frFR', 'Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !', 0),
(7931, 'frFR', 'Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !', 0),
(7932, 'frFR', 'Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !', 0),
(7933, 'frFR', 'Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !', 0),
(7934, 'frFR', 'Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !', 0),
(7935, 'frFR', 'Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance !', 0),
(7937, 'frFR', 'Cette meule de foin ressemble à celle de votre vision.', 0),
(7938, 'frFR', 'Ce coffre ressemble à celui de votre vision.', 0),
(7939, 'frFR', '$N, je vous remercie de toute l’aide que vous m’avez apporté. Sincèrement, je ne vous remercierai jamais assez.$B$BEt même si j’en ai moins besoin maintenant, si vous me fournissez d’autres pierres à aiguiser denses, il se pourrait que je vous donne d’autres bons de la foire de Sombrelune.', 0),
(7940, 'frFR', 'Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance ! !', 0),
(7941, 'frFR', 'Je dois vous remercier pour votre aide, $N. J''ai bien assez de réserves, en grande partie grâce à vous. Si vous voulez m''amener davantage de renforts d''armure, je vous les échangerai volontiers contre des bons de la foire de Sombrelune.', 0),
(7942, 'frFR', '$N, vous m’avez bien rendu service en m’amenant tout cela sans jamais vous lasser. Vous avez toute ma gratitude.$B$BNous avons moins besoin de rouages en thorium qu’à une certaine époque, mais si vous m’en amenez d’autres, je vous les échangerai contre des bons de la foire de Sombrelune.', 0),
(7943, 'frFR', '$N, l’attraction que je suis en train de créer sera la chose la plus effrayante qu’on ait vue depuis la chute de Gnomeregan ! Et c’est largement grâce à tout ce que vous m’avez apporté. Merci, merci mille fois !$B$BJe n’ai plus besoin de grand-chose mais… si vous m’apportez encore des yeux de chauve-souris maléfiques pris sur les chauve-souris des Maleterres de l’est… je pourrais avoir d’autres bons de la foire de Sombrelune pour vous.', 0),
(7944, 'frFR', 'Ce coffre ressemble à celui de votre vision.', 0),
(7945, 'frFR', 'Cette sourche ressemble à celle de votre vision.', 0),
(7946, 'frFR', 'Je suis si content que Jubjub ait été retrouvée. Elle aime tellement la bière Sombrefer que lorsque je n’en ai plus… elle s’enfuit pour en chercher !$B$BMaintenant que Jubjub est revenue, je veux stocker toute la bière que je peux trouver ! Je ne veux pas que Jubjub s’enfuie à nouveau !$B$BVous avez de la bière Sombrefer ? Si c’est le cas, je vous l’échange l’un des œufs de ma grenouille Jubjub contre une chope.', 0),
(8042, 'frFR', 'C’est bon de vous voir en bonne santé, $N. Les combats glorieux que vous avez menés affectent tous les êtres vivants de cette planète. Hakkar doit rester à jamais dans les confins de Zul’Gurub, sinon le monde succomberait sous les assauts de son insatiable faim.$B$BDonnez-moi votre talisman, et j’amplifierai sa force. Utilisez la Force de Mugamba pour punir nos ennemis !', 0),
(8046, 'frFR', 'J’ai peut-être été trop hâtif dans mon jugement, $C. Il semblerait que votre foi aveugle dans cette Lumière ait un peu de mérite, après tout.$B$BDonnez-moi votre marque et j’amplifierai son pouvoir.', 0),
(8047, 'frFR', 'Je dois avouer que je ne croyais pas que vous auriez la détermination pour mener cette cause à bien, $C. Zandalar vous considère maintenant comme un allié de valeur. Bien joué,$B$BDonnez-moi votre marque et j’amplifierai une nouvelle fois  son pouvoir.', 0),
(8048, 'frFR', 'Le roi a reconnu votre existence, $C. Vous êtes la première étrangère à être accepté par Rastakhan comme une  véritable alliée  de Zandalar.$B$BVous serez grandement récompensée  de vos efforts. Présentez votre marque et je lui apporterai l’amplification finale.', 0),
(8050, 'frFR', 'Bienvenue, $C. L’énergie pulse dans l’Œil de Zuldazar. Vous êtes prêt pour la prochaine étape. Confiez-moi le talisman et je réaliserai l’imprégnation.', 0),
(8053, 'frFR', 'Vous êtes de retour ? Avez-vous le Parangon de puissance ou êtes-vous en train de me faire perdre mon temps ?$B$BJ’espère que ce n’est pas le cas, incroyant.', 0),
(8054, 'frFR', 'Votre présence signifie-t-elle la victoire ? Avez-vous le Parangon ? Êtes-vous inondé du sang de vos ennemis ?', 0),
(8055, 'frFR', 'Avez-vous le Parangon ? Il contient du mojo. Il nous le faut. Vous nous aiderez.', 0),
(8056, 'frFR', 'Avez-vous le Parangon de puissance de Zul’Gurub dont j’ai besoin ? Ces brassards méritent que vous vous donniez un peu mal, vous savez !', 0),
(8058, 'frFR', 'Avez-vous ramené le Parangon de puissance ? Avez-vous exercé la vengeance au nom des Zandalar ?', 0),
(8059, 'frFR', 'Revenez-vous avec le Parangon de puissance ? En triomphant des séides diaboliques d’Hakkar, vous ferez vos preuves à nos yeux et vous montrerez votre volonté d’apprendre les voies des démoniaques.', 0),
(8060, 'frFR', '$N, vous êtes déjà de retour ? Avez-vous récupéré le Parangon de puissance dont j’ai besoin ?', 0),
(8061, 'frFR', 'De retour de Zul’Gurub, pas vrai ? Avez-vous repris le Parangon de puissance aux séides d’Hakkar ?', 0),
(8062, 'frFR', 'Traquez les habitants de Zul’Gurub qui possèdent des Parangons de puissance, $N. Ils sont votre proie. Ils possèdent quelque chose dont nous avons tous les deux besoin.', 0),
(8064, 'frFR', 'Avez-vous le Parangon de puissance de Zul’Gurub dont j’ai besoin ? Si vous l''avez, je vous donnerai la ceinture de l’haruspice.', 0),
(8066, 'frFR', 'Frappez les séides déments d’Hakkar à Zul’Gurub, $N. Ce sont eux qui ont les Parangons de puissance. Montrez-leur – montrez-nous – que vous ferez un excellent prédateur.', 0),
(8067, 'frFR', 'Vos opérations dans Zul’Gurub ont-elles été couronnées de succès, $N ? Ce n’est que lorsque vous m’aurez apporté ce que je cherche – et que vous aurez fait vos preuves aux yeux de la tribu – que vous receverez un mantelet sans équivalent parmi les Zandalar.', 0),
(8068, 'frFR', 'Comment s’est passée votre expédition à Zul’Gurub ? Avez-vous rendu fous vos ennemis grâce à la puissance de l’illusion ? Illusion ou pas, leur mort – et la confiscation de leurs Parangons de puissance – nous aidera à contrecarrer l’ascension d’Hakkar.', 0),
(8069, 'frFR', 'Apportez-vous le Parangon de puissance dont nous avons besoin ? Je sais que ce ne sera pas facile… Mais il y a bien longtemps, j’ai prophétisé qu’un étranger viendrait nous aider dans notre combat contre Hakkar. Faites en sorte que ce soit vous !', 0),
(8070, 'frFR', 'Le Parangon de puissance… l''avez-vous ? Lorsque vous nous l''aurez ramené, nous pourrons nous servir de la puissance latente qu’il contient. Il sera doux de faire enfin payer les sbires du Dieu sanglant…', 0),
(8071, 'frFR', 'Avez-vous le Parangon de puissance de Zul’Gurub ?', 0),
(8072, 'frFR', 'Vous êtes de retour. Avez-vous le Parangon de puissance dont j’ai besoin ?$B$BLa légende de Khar''vaxal le Fêlé nous rappelle qu’aucun ennemi, si puissant soit-il, n’est invincible. Le chaos finit par mettre tout le monde à genoux, c’est une certitude… et peut-être est-ce aussi le cas des éléments les moins chaotiques du chaos.', 0),
(8074, 'frFR', 'Il me faut le Parangon de puissance. Nous le viderons de leur pouvoir et nous nous en servirons pour combattre le mal qui vient de Zul’Gurub. Alors, vous l''avez ?', 0),
(8075, 'frFR', 'Les Parangons de puissance sont une source capitale de pouvoir magique, le même genre de pouvoir qui permet de fabriquer le haubert d’augure. Ramenez-moi ce dont j’ai besoin, et je pourrai vous remettre un vêtement que tout augure de Zandalar serait fier de posséder.', 0),
(8076, 'frFR', 'Avez-vous récupéré le Parangon de puissance de Zul’Gurub ? Nous prendrons la force latente de ces objets et nous la ferons nôtre. Quant à vous, si vous réussissez, vous aurez votre propre don de puissance…', 0),
(8077, 'frFR', 'Le Parangon de puissance… êtres-vous revenu avec lui ? Nous ne vous donnerons l’ultime symbole de la puissance des démoniaques que lorsque vous nous l''aurez livré, $N.', 0),
(8078, 'frFR', 'Avez-vous le Parangon de puissance ? Avez-vous terrassé les ennemis de la tribu ? Hakkar doit connaître la colère du redresseur de torts !', 0),
(8079, 'frFR', 'Votre présence signifie-t-elle la victoire ? Avez-vous le Parangon de puissance ? Parlez-moi de la justice que vous avez rendue en ce jour !', 0),
(8102, 'frFR', 'Bienvenue de nouveau, $C. Je vois que le caillou a beaucoup servi. Un grand nombre de nos ennemis a succombé devant vos capacités surnaturelles. Leurs souffrances ont été grandes. Il est temps que j’augmente la puissance du caillou. Donnez-le-moi.', 0),
(8103, 'frFR', 'Les Hakkari vous craignent, $N. Ils parlent d’horreurs qu’ils croyaient n’être l’apanage que de leur dieu sans visage. Vous les avez brûlés grâce à la force de Kajaro. Ils connaissent maintenant la peur en deux endroits.$B$BIl est temps maintenant de renforcer le caillou. Donnez-moi le talisman.', 0),
(8104, 'frFR', 'Donnez-moi le talisman, $N. Je dois vous montrer quelque chose.', 0),
(8107, 'frFR', 'L’honneur se mérite chez les trolls de Zandalar, $N. Avec l’honneur viennent les récompenses : l’amitié, les alliances…$B$BDonnez-moi le talisman pour que je puisse renforcer son pouvoir.', 0),
(8108, 'frFR', 'Je suis prêt, $C. Je vais une nouvelle fois améliorer votre talisman. Je vous demande seulement de continuer votre destruction d’Hakkar et de ses séides.$B$BDonnez-moi le talisman.', 0),
(8109, 'frFR', 'Appelez vos démons, $C. Qu’ils se baignent dans l’énergie de la Souillure de Kezan. Commandez-les sur le champ de bataille ! Décimez nos ennemis !$B$BOui… Le temps est venu d’apporter l’amélioration finale à la Souillure de Kezan. Donnez-moi le talisman.', 0),
(8111, 'frFR', 'Salut ! C’est bien sympathique de revenir nous voir. Toute la tribu raconte comment vous avez tué les Hakkari et tout ça. Molthor m’a fait passer le mot, et m''a demandé de rajouter plus de mojo dans votre talisman. Donnez-le-moi, et Maywiki l’améliorera.', 0),
(8112, 'frFR', 'Comment va votre talisman ? On dirait que c’est l’heure d’ajouter un petit peu plus de magie et de mojo à ses feuilles. Il a besoin d’une petite fleur dans son desséchement. Donnez-le-moi et Maywiki le réparera.', 0),
(8142, 'frFR', 'J’ai le sentiment que vous avez infligé d’innombrables pertes aux Hakkari, $N. Vous portez sur vous la puanteur de leur mojo.$B$BJe suppose que le talisman d’ombre a bien participé au massacre… Donnez-le-moi et permettez-moi d’augmenter son pouvoir.', 0),
(8143, 'frFR', 'Impressionnant, $N. Vous avez un don pour le meurtre que je n’ai pas ressenti chez quelqu’un depuis de longues années. Même Molthor est conscient du travail que vous avez effectué pour Zandalar. Il est temps d’améliorer une nouvelle fois votre talisman. Donnez-le-moi.', 0),
(8144, 'frFR', 'Le talisman brûle d’envie de grandir, $N. Il a absorbé tout ce que vous avez accompli. Les milliers de cadavres de trolls qui jonchent Zul’Gurub ont alimenté son pouvoir. Donnez-le-moi, et j’accomplirai l’amélioration finale.', 0),
(8148, 'frFR', 'Molthor nous a transmis la parole du roi Rastakhan, $N.  La cour royale est très impressionnée par votre décimation des forces hakkari. Je dois vous récompenser par l’enchantement final de votre talisman. Donnez-le-moi.', 0),
(8153, 'frFR', 'Avez-vous trouvé les ramures ?', 0),
(8194, 'frFR', 'Bon, nous avons déjà un gagnant, mais je continue à acheter vos courbines à un prix raisonnable. Ça vous va ?', 0),
(8195, 'frFR', 'Je cherche les Parangons de puissance connus sous le nom de Pièces des Tribus.  Il s''agit de la monnaie utilisée par les différents habitants de Zul''Gurub, et chacune est imprégnée d''un subtil mais puissant mojo.$B$BIl y en existe neuf types distincts.  Certaines sont recherchées par mes compatriotes pour différentes armures qu''ils proposent aux héros des Zandalar.  Si vous en avez, je vous les échangerai contre une de nos marques d''honneur par série de trois.  Vous pouvez utiliser les marques chez Rin''wosho le marchand : il propose à nos héros des articles spéciaux en échange.', 0),
(8201, 'frFR', 'Avez-vous cette collection de têtes, $N ? Nous devons empêcher Hakkar de gagner davantage de puissance !', 0),
(8221, 'frFR', '*Bzzz* *Clic*$B$BJe cherche des poissons rares pour le catalogue du Maître de pêche Perchappât. Si vous m''amenez un Scalaire de Keefer, je vous donnerai cette magnifique récompense.$B$B*Zzzap* *Bzzz*', 0),
(8222, 'frFR', 'Tout ce temps passé à la foire m’a beaucoup appris sur nos clients. Voici l’un de mes axiomes : si ça brille, ça plaît ! Et peu importe ce que c’est en réalité. Vous pouvez prendre des pieds de chaises cassés, s’ils brillent, tous les gamins à des lieues à la ronde feront la queue pour en acheter un !$B$BBref, tout cela pour dire qu’il me faut du sang de scorpide luminescent, $N. Vous pourrez en trouver sur les scorpides de Silithus, des Terres foudroyées ou des Steppes ardentes.', 0),
(8223, 'frFR', 'Ce sang de scorpide fait des merveilles, $N ! C’est fou ce qu’un peu de brillant peut faire – cela suffit à transformer un détritus en objet de valeur. Les clients aiment ça, et vous savez, au fond, tout cela est une question d’amour…$B$BVous m’avez rendu un grand service, $N, et même si je n’ai pas un besoin urgent de plus de sang de scorpide luminescent, si vous m’en ramenez davantage, je vous l’échangerai contre des bons.', 0),
(8224, 'frFR', '*Bzzz* *Clic*$B$BJe cherche des poissons rares pour le catalogue du Maître de pêche Perchappât. Si vous m''amenez un Talang dezien, je vous donnerai cette magnifique récompense.$B$B*Zzzap* *Bzzz*', 0),
(8231, 'frFR', 'Avez-vous réussi ?', 0),
(8232, 'frFR', 'La sagesse brille dans vos yeux, $N. Votre chasse est-elle terminée ?', 0),
(8235, 'frFR', 'Avez-vous trouvé assez de fragments pour que je continue mon travail ?', 0),
(8236, 'frFR', 'Le sac est déjà revenu de chez l’archimage Xylem. Avez-vous trouvé la clé ?', 0),
(8238, 'frFR', 'Je cherche les Parangons de puissance connus sous le nom de Pièces des Tribus.  Il s''agit de la monnaie utilisée par les différents habitants de Zul''Gurub, et chacune est imprégnée d''un subtil mais puissant mojo.$B$BIl y en existe neuf types distincts.  Certaines sont recherchées par mes compatriotes pour différentes armures qu''ils proposent aux héros des Zandalar.  Si vous en avez, je vous les échangerai contre une de nos marques d''honneur par ensemble de trois.  Vous pouvez utiliser les marques chez Rin''wosho le marchand : il propose à nos héros des articles spéciaux en échange.', 0),
(8239, 'frFR', 'Je cherche les Parangons de puissance connus sous le nom de Pièces des Tribus.  Il s''agit de la monnaie utilisée par les différents habitants de Zul''Gurub, et chacune est imprégnée d''un subtil mais puissant mojo.$B$BIl y en existe neuf types distincts.  Certaines sont recherchées par mes compatriotes pour différentes armures qu''ils proposent aux héros des Zandalar.  Si vous en avez, je vous les échangerai contre une de nos marques d''honneur par ensemble de trois.  Vous pouvez utiliser les marques chez Rin''wosho le marchand : il propose à nos héros des articles spéciaux en échange.', 0),
(8240, 'frFR', 'Avez-vous détruit le bijou à l''Autel de Zanza ? Faites-le, et vous serez doublement béni par Zanza !', 0),
(8241, 'frFR', 'Assez perdu de temps à bavarder, $R. Il est temps de nous concentrer sur le réapprovisionnement de nos réserves de flux embrasé qui s''amenuisent.$B$BVoici ce que je veux que vous me rapportiez :$B$B*Ecailles d''incendosaure.$B$B*Barres de fer.$B$B*Charbon.$B$BJe prendrai tout ce que vous me donnerez !$B$BEt vous le ferez vite si vous voulez bien vous entendre avec la Confrérie.', 0),
(8242, 'frFR', 'Assez perdu de temps à bavarder, $R. Il est temps de nous concentrer sur le réapprovisionnement de nos réserves de flux embrasé qui s''amenuisent.$B$BVoici ce que je veux que vous me rapportiez :$B$B*Ecailles d''incendosaure.$B$B*Cuir lourd.$B$B*Charbon.$B$BJe prendrai tout ce que vous me donnerez !$B$BEt vous le ferez vite si vous voulez bien vous entendre avec la Confrérie.', 0),
(8249, 'frFR', 'Mes voleurs ont besoin de s''exercer en crochetage et il me faut des serrures d''un niveau de difficulté adéquat. Ce que Zan nous fabrique ne convient qu''aux plus modestes néophytes.$B$BVous savez quoi, si vous m''apportez 5 Coffrets lourds, je vous procurerai des couteaux de lancer parmi les meilleurs qu''un $C ait jamais eu.$B$BVous pouvez ouvrir les coffrets et les piller, mais laissez au moins quelques pièces dedans... même un apprenti $C a besoin de motivation.', 0),
(8251, 'frFR', 'Avez-vous la poussière ?', 0),
(8252, 'frFR', 'C’est étonnant, mais les sirènes Fouette-bile sont douées pour la magie. Pas aussi douées que vous, j''espère ?', 0),
(8253, 'frFR', 'Alors, avez-vous tué mon vieil ennemi ?', 0),
(8255, 'frFR', 'Vous êtes de retour. Avez-vous réussi ?', 0),
(8256, 'frFR', 'Ne tardez pas à récupérer l’ichor. L’avez-vous déjà trouvé ?', 0),
(8257, 'frFR', 'Avez-vous le sang de Morphaz ?', 0),
(8286, 'frFR', 'Anachronos est-il revenu ?', 0),
(8312, 'frFR', 'Vous avez pu finir la tournée des bonbons ?  Je suis bien triste de ne pas pouvoir y aller, parce que je suis malade, mais vous m''aidez à me sentir un peu mieux…', 0),
(8314, 'frFR', 'Oh ciel ! Qu''avez-vous là, $N ?', 0),
(8315, 'frFR', 'Vous devez saisir l’opportunité quand elle se présentera, et frapper !', 0),
(8319, 'frFR', 'Continuez à me fournir des textes. Nous ne tarderons pas à chasser le Marteau du crépuscule de Silithus.', 0),
(8324, 'frFR', 'Vous avez trouvé d''autres textes cryptés ?  Apportez m''en une bonne pile, car le travail de décodage prend du temps.', 0),
(8333, 'frFR', 'Si vous avez besoin d''un nouveau médaillon de statut de sectateur du crépuscule, je serai heureux de vous le fournir.  Cependant, j’aurai besoin d’un autre éclat brillant et de quelques blasons abyssaux…', 0),
(8341, 'frFR', 'Vous avez les éclats et les chevalières, $N ?  J''en ai besoin pour fabriquer l''anneau d''autorité.', 0),
(8342, 'frFR', '$N, si vous avez l''intention de vous attaquer au Haut conseil abyssal une nouvelle fois, il vous faudra un autre anneau d''autorité du crépuscule. Apportez-moi plus d''éclats et de chevalières et je vous en fabriquerai un.', 0),
(8352, 'frFR', 'Eh bien, ça s’est passé comment ? Je donnerais très cher pour quitter mon poste et me charger moi-même d’une de ces créatures.', 0),
(8358, 'frFR', 'Eh bien, allez-y…', 0),
(8362, 'frFR', 'Vous avez prouvé que vous savez tenir votre place dans un combat, $N. Continuons à harceler le Marteau du crépuscule. Allez combattre  d’autres Templiers abyssaux. Je vous récompenserai avec quelques objets que Huum et moi avons trouvés sur nos adversaires vaincus.', 0),
(8363, 'frFR', 'Vous avez démontré que vous êtes largement capable de vous attaquer à un duc abyssal, $N. Je suis toujours prêt à encourager de bonnes habitudes comme celle-ci.  Apportez-moi d’autres chevalières, et je vous récompenserai.', 0),
(8369, 'frFR', 'Quelles nouvelles apportez-vous des terres des Frostwolf ? Comment tourne la bataille pour la vallée d’Alterac ?', 0),
(8385, 'frFR', 'Ah, $N.  J''espère que vous continuez à faire profiter les différents champs de bataille de votre expérience.  Au front, un grand nombre de soldats sont inspirés par des vétérans endurcis comme vous.', 0),
(8387, 'frFR', 'La bataille pour Alterac fait rage !  Vous devez retourner à la vallée d''Alterac et repousser une fois encore les envahisseurs du territoire des Frostwolf, $N !', 0),
(8410, 'frFR', 'Qu''avez-vous pour moi, $C ?', 0),
(8413, 'frFR', 'Où sont les plumes, l''ami ?', 0),
(8414, 'frFR', 'Quel maléfice m''avez-vous apporté ?', 0),
(8416, 'frFR', 'Thal''danis a-t-il pu purifier les pierres du Fléau ?', 0),
(8419, 'frFR', 'Avez-vous ma gangrétoffe ?', 0),
(8420, 'frFR', 'Vous avez ma gangrétoffe ?', 0),
(8421, 'frFR', 'Vous avez les matériaux ?', 0),
(8422, 'frFR', 'Vous apportez les plumes ? Ma poupée a besoin d’être rembourrée ?', 0),
(8425, 'frFR', 'Vous êtes déjà de retour ?  Je ne ressens plus le temps de la même façon, peut-être qu''en fait ce fut un long voyage pour vous. . .', 0),
(8446, 'frFR', 'Oui, $R ?', 0),
(8461, 'frFR', 'Une fois encore vous avez gagné la confiance des Grumegueules. Je suis sûr que nous pouvons faire quelque chose pour vous en échange de votre loyauté.  Les Grumegueules n''oublient pas leurs alliés, surtout dans des temps aussi difficiles que ceux que nous vivons.', 0),
(8466, 'frFR', 'Même si vous m’avez déjà montré votre valeur, vous devez continuer à faire vos preuves vis-à-vis des autres membres de ma tribu, qui sont plus méfiants que moi.  Je pourrai peut-être vous aider dans cette tâche.$B$BCertains furbolgs Mort-bois portent une coiffe distinctive qui pourraient vous servir à démontrer que vous avez bien diminué leurs rangs.  Apportez-moi une plume de toutes les coiffes que vous vous procurerez. Pour chaque série de cinq plumes que vous m’apporterez, vous gagnerez la reconnaissance des Grumegueules.', 0),
(8467, 'frFR', 'Même si vous m’avez déjà montré votre valeur, vous devez continuer à faire vos preuves vis-à-vis des autres membres de ma tribu, qui sont plus méfiants que moi.  Je pourrai peut-être vous aider dans cette tâche.$B$BCertains furbolgs Mort-bois portent une coiffe distinctive qui pourraient vous servir à démontrer que vous avez bien diminué leurs rangs.  Apportez-moi une plume de toutes les coiffes que vous vous procurerez. Pour chaque série de cinq plumes que vous m’apporterez, vous gagnerez la reconnaissance des Grumegueules.', 0),
(8472, 'frFR', 'Êtes-vous déjà parvenu à récupérer les noyaux arcaniques, $N ?', 0),
(8486, 'frFR', 'Avez-vous réglé le problème des âmes en peine arcaniques ?', 0),
(8487, 'frFR', 'Avez-vous fini de recueillir les échantillons que j''ai demandés, $N ?', 0),
(8492, 'frFR', 'Avez-vous déjà réuni les vingt barres de cuivre, soldat ?', 0),
(8495, 'frFR', 'Déjà de retour ? Mais arrêtez donc de m’obliger à revoir ma mauvaise opinion de vous, $C, j’ai l’impression de devenir un grand sentimental. Donc, comme vous pouvez le voir, nous n’avons pas encore assez de barres de fer pour les armes, les armures, les chars à vapeur et tous les machins que nous devons fabriquer pour la chasse aux cafards. Vous pensez que vous avez assez de tripes pour me rapporter vingt autres barres de fer entre deux voyages à Zul’Gurub, ou quel que soit l’endroit où les gamins comme vous traînent leurs guêtres, ces temps-ci ?', 0),
(8498, 'frFR', 'Vous avez quelque chose pour moi ?', 0),
(8500, 'frFR', 'Ça fait plaisir de vous revoir, $N. J''espère que vous vous portez bien. Nous avons effectivement encore besoin de barres de thorium. Si vous en avez dont vous pouvez vous passer, je les collecte pour l''effort de guerre d''Ahn''Qiraj.', 0),
(8501, 'frFR', 'Vous voulez me dire quelque chose, $N ?', 0),
(8502, 'frFR', 'Vous avez quelque chose à me dire, $C ?', 0),
(8505, 'frFR', 'Avez-vous les lotus pourpres que j''ai demandés ?', 0),
(8509, 'frFR', 'Qu''y a-t-il ? Parlez plus fort, $C ! Avez-vous la cargaison de larmes d''Arthas que j''ai demandée ?', 0),
(8511, 'frFR', 'J’espère que c’est le cuir léger que vous m’aviez promis, $C.', 0),
(8512, 'frFR', 'Je suis heureuse de vous revoir, $N. Il semblerait que nous ayons besoin de plus de cuir léger pour fabriquer toutes les fournitures militaires dont nous avons besoin. Si vous pouviez me rapporter une pile de dix cuirs légers, ce serait parfait.', 0),
(8513, 'frFR', 'Oui messire je me souviens de vous. Vous avez une livraison de cuir moyen pour moi ?', 0),
(8516, 'frFR', 'La pile n’est pas encore assez haute, $N. Nous n’avons toujours pas atteint notre objectif pour le cuir épais. Pensez à ce que nous pourrons fabriquer avec tout ce cuir ! Des armures. Des armes. Des trucs et des machins pour l’intérieur des chars à vapeur. Des lunettes de visée. Des lunettes d’ingénieur, c’est toujours rigolo.$B$BAlors, allez-vous me ramener encore plus de cuir épais ?', 0),
(8518, 'frFR', 'Je suis toujours étonnée par l’altruisme dont font preuve certains, alors que tant de gens se réfugient dans l’égoïsme. $C, j’ai toujours besoin d’un grand nombre de bandages en lin avant que mon objectif ne soit rempli. M’aiderez-vous une fois encore à réunir ces bandages ?', 0),
(8521, 'frFR', 'C’est très sympathique de votre part de revenir m’aider, $C Il semblerait que nous ayons déjà rassemblé une bonne partie des bandages en soie qui m’ont été demandés, mais ce n’est pas suffisant. Dites $N, est-ce que vous auriez le temps de m’en préparer un autre paquet ? L’Alliance vous en serait très reconnaissante… et moi donc !', 0),
(8522, 'frFR', 'Les jours se succèdent, et nous continuons nos efforts, encore et encore. $C, avez-vous ces bandages en étoffe runique ?', 0),
(8523, 'frFR', 'Nous nous retrouvons une fois de plus pour discuter d’une affaire urgente, $C. Je vous remercie encore pour vos précédents efforts. Peu de gens se seraient montrés aussi généreux et altruistes. Mais il reste beaucoup à faire.$B$B$N, acceptez-vous de récolter de nouveaux bandages en étoffe runique et de me les ramener ?', 0),
(8524, 'frFR', 'Je suis prêt à parier que vous êtes revenu avec le thon arc-en-ciel dont nous avons parlé plus tôt, $C. J’ai pas raison ?', 0),
(8526, 'frFR', 'Alors, vous avez tous les rôtis de raptor ?', 0),
(8528, 'frFR', 'Je suis sûre que vous reviendrez très bientôt avec les jaunes-queues tachetés dont nous avons parlé.', 0),
(8529, 'frFR', 'Si vous êtes toujours volontaire, j’aimerai  vous renvoyer là-bas pour me rapporter de nouvelles prises de jaunes-queues tachetés, $N. J’imagine qu’avec l’expertise que vous avez gagné la première fois, cette pêche devrait être plus rapide et plus facile. Cela vous dit ?', 0),
(8532, 'frFR', 'J’espère que votre sac contient bien vingt barres de cuivre, $C.', 0),
(8533, 'frFR', 'Déjà de retour? On fera de vous un vrai mineur en un rien de temps, $C. Bon, vous connaissez l’exercice ; j’ai besoin que vous vous baladiez, que vous miniez un bon filon de cuivre, que vous le fondiez en barres et que vous me les rapportiez ici. Je sais parfaitement que vous en êtes capable. La véritable question est, est-ce que vous portez volontaire ?', 0),
(8534, 'frFR', 'L’éclaireur Azenel se trouve dans la Ruche’Zora. Hâtez-vous, $N ! Le temps presse.', 0),
(8535, 'frFR', 'Avez-vous rempli votre mission, $N ?', 0),
(8536, 'frFR', 'Avez-vous rempli votre mission, $N ?', 0),
(8537, 'frFR', 'Avez-vous rempli votre mission, $N ?', 0),
(8538, 'frFR', 'Avez-vous rempli votre mission, $N ?', 0),
(8539, 'frFR', 'Vous avez quelque chose à me dire, $C ?', 0),
(8542, 'frFR', 'Combien de barres d’étain avez-vous, $C ? Après la guerre, il faudra que je trouve quelqu’un pour m’apprendre à compter.', 0),
(8543, 'frFR', 'Très bien, je vois que vous prenez cette guerre au sérieux. Attendre que les combats commencent me tape toujours un peu sur les nerfs – je pense que vous comprenez ça, $C. Mais quand ça va commencer… La Horde chargeant dans les sables de Silithus, armes brandies, et se ruant dans les insectes agglutinés ! Ce sera une belle journée, avec beaucoup d’honneur à gagner !$B$BMais en attendant, il nous faut plus de barres d’étain. C’est drôle qu’un objet si petit fasse une telle différence, pas vrai ?', 0),
(8544, 'frFR', 'Vous êtes-vous procuré les composants dont j’ai besoin ?', 0),
(8545, 'frFR', 'Pour sûr, ça serait bien qu’on ait toutes les barres de mithril dont on a besoin pour l’effort de guerre d’Ahn’Qiraj. C’est pour ça que vous rev’nez ? Pour mes barres ?', 0),
(8556, 'frFR', 'Vous m''avez apporté l''anneau et les matériaux, $N ?', 0),
(8557, 'frFR', 'Vous avez apporté les matériaux pour la cape, $N ?', 0),
(8558, 'frFR', 'M''avez-vous apporté les composants dont j''ai besoin, $N ?', 0),
(8559, 'frFR', 'Vous êtes-vous procuré les articles que j''ai demandés, $N ?', 0),
(8561, 'frFR', 'M’avez-vous ramené les composants demandés, $N ?', 0),
(8562, 'frFR', 'Dans sa demeure d’Ahn’Qiraj, le terrible C’Thun rêve et attend.', 0),
(8573, 'frFR', 'Dans notre propre intérêt, nos alliés les plus loyaux doivent être bien équipés, $N.', 0),
(8574, 'frFR', 'Dans notre propre intérêt, nos alliés les plus loyaux doivent être bien équipés, $N.', 0),
(8575, 'frFR', 'Ooooh ! Un machin magique qui vibre. C''est pour moi ?', 0),
(8578, 'frFR', 'Le Cœur du Magma, hein ? J''espère que mes lunettes sont encore en un seul morceau !', 0),
(8585, 'frFR', 'Mmmmm… Des chimaeroks…', 0),
(8586, 'frFR', 'Allez, allez, on se dépêche. Faudrait pas que cette viande faisande.', 0),
(8587, 'frFR', 'Quelle est cette odeur bouleversante ?', 0),
(8588, 'frFR', 'Si vous êtes juste là pour papoter, vous feriez mieux de dégager, $C. J’ai encore des piles et des piles de cuir épais à nettoyer. Revenez me voir lorsque vous en aurez au moins dix morceaux à me donner.', 0),
(8590, 'frFR', 'Alors, $C, vous êtes déjà de retour ? Avez-vous le cuir épais dont nous avions parlé ?', 0),
(8594, 'frFR', 'Vous êtes-vous procuré les composants dont j’ai besoin ?', 0),
(8595, 'frFR', 'Tuer un seigneur qiraji représente un succès notable pour un mortel, $N. Hélas, ils sont nombreux et puissants. Continuez à les vaincre pour prouver votre valeur en tant que champion.', 0),
(8598, 'frFR', 'Eh bien, que se passe-t-il ?', 0),
(8599, 'frFR', 'Vous sentez le poisson !', 0),
(8600, 'frFR', 'Découper ces dix morceaux de cuir robuste pour moi ne devrait pas vous prendre aussi longtemps ! Vous devriez peut-être aiguiser votre couteau à dépecer ? À moins que je ne me trompe et que vous les ayez sur vous ?', 0),
(8602, 'frFR', 'Vous êtes-vous procuré les composants dont j’ai besoin ?', 0),
(8603, 'frFR', 'Dans sa demeure d’Ahn’Qiraj, le terrible C’Thun rêve et attend.', 0),
(8604, 'frFR', 'Ah, $C. Seriez-vous déjà de retour avec les bandages en laine ?', 0),
(8607, 'frFR', 'N’échouez pas, $C, ce serait désastreux pour mon image ! Revenez me voir aussi rapidement que possible avec les bandages en tisse-mage que je vous ai demandés.', 0),
(8625, 'frFR', 'Vous êtes-vous procuré les composants dont j’ai besoin ?', 0),
(8626, 'frFR', 'Vous êtes-vous procuré les articles que j''ai demandés, $N ?', 0),
(8627, 'frFR', 'Dans sa demeure d’Ahn’Qiraj, le terrible C’Thun rêve et attend.', 0),
(8630, 'frFR', 'Vous êtes-vous procuré les composants dont j’ai besoin ?', 0),
(8633, 'frFR', 'Dans sa demeure d’Ahn’Qiraj, le terrible C’Thun rêve et attend.', 0),
(8634, 'frFR', 'Vous êtes-vous procuré les articles que j''ai demandés, $N ?', 0),
(8637, 'frFR', 'Vous êtes-vous procuré les articles que j''ai demandés, $N ?', 0),
(8638, 'frFR', 'Dans sa demeure d’Ahn’Qiraj, le terrible C’Thun rêve et attend.', 0),
(8639, 'frFR', 'M’avez-vous ramené les composants demandés, $N ?', 0),
(8641, 'frFR', 'Vous êtes-vous procuré les composants dont j’ai besoin ?', 0),
(8656, 'frFR', 'Dans sa demeure d’Ahn’Qiraj, le terrible C’Thun rêve et attend.', 0),
(8657, 'frFR', 'M’avez-vous ramené les composants demandés, $N ?', 0),
(8659, 'frFR', 'Vous êtes-vous procuré les composants dont j’ai besoin ?', 0),
(8662, 'frFR', 'M’avez-vous ramené les composants demandés, $N ?', 0),
(8664, 'frFR', 'Vous êtes-vous procuré les composants dont j’ai besoin ?', 0),
(8666, 'frFR', 'Dans sa demeure d’Ahn’Qiraj, le terrible C’Thun rêve et attend.', 0),
(8669, 'frFR', 'Vous êtes-vous procuré les composants dont j’ai besoin ?', 0),
(8687, 'frFR', 'Vous avez quelque chose à me dire, $C ?', 0),
(8689, 'frFR', 'Vous avez apporté les matériaux pour la cape, $N ?', 0),
(8693, 'frFR', 'Vous avez apporté les matériaux pour la cape, $N ?', 0),
(8694, 'frFR', 'Vous avez apporté les matériaux pour la cape, $N ?', 0),
(8696, 'frFR', 'Vous avez apporté les matériaux pour la cape, $N ?', 0),
(8697, 'frFR', 'Vous m''avez apporté l''anneau et les matériaux, $N ?', 0),
(8699, 'frFR', 'Vous m''avez apporté l''anneau et les matériaux, $N ?', 0),
(8701, 'frFR', 'Vous m''avez apporté l''anneau et les matériaux, $N ?', 0),
(8702, 'frFR', 'Vous m''avez apporté l''anneau et les matériaux, $N ?', 0),
(8704, 'frFR', 'Vous m''avez apporté l''anneau et les matériaux, $N ?', 0),
(8709, 'frFR', 'M''avez-vous apporté les composants dont j''ai besoin, $N ?', 0),
(8728, 'frFR', 'Les bouées d’arcanite ne se fabriquent pas toutes seules, $N. Et NON, vous ne pouvez pas m’emprunter de l’argent.', 0),
(8729, 'frFR', 'Le temps presse, champion.', 0),
(8730, 'frFR', 'Un autre de nos héros succombe sous les griffes du rejeton de l''Aile de mort. Cette douleur nous affligera-t-elle à jamais… ?', 0),
(8735, 'frFR', '<Remulos est perdu dans ses pensées. >', 0),
(8737, 'frFR', 'Avez-vous rempli votre mission, $N ?', 0),
(8738, 'frFR', 'L’éclaireur Landion se trouve dans la Ruche’Regal. Hâtez-vous, $N ! Le temps presse.', 0),
(8740, 'frFR', 'Avez-vous terminé votre tâche, $N ?', 0),
(8746, 'frFR', '$N ! Vous l’avez trouvé ? Les notes contenues dans la sacoche que je vous ai donnée vous ont-elles permis de localiser Metzen ?  Quand je pense aux horreurs que ces cruels bandits pourraient lui faire subir… Hélas, nous n’avons pas les moyens de payer une rançon aussi exorbitante !', 0),
(8748, 'frFR', 'Votre persévérance dans la défense des enfants de Kalimdor a été reconnue. Donnez-moi votre chevalière, que j’augmente ses pouvoirs.', 0),
(8749, 'frFR', 'Vous nous faites honneur, $N. Terrassez les ennemis de Kalimdor ! Montrez-leur que l’on ne profane pas impunément la terre des étoiles éternelles !$B$BVous méritez une nouvelle amélioration. Donnez-moi votre chevalière, que j’accroisse ses pouvoirs.', 0),
(8750, 'frFR', 'Une telle dévotion à une cause est une rareté. Vous fait preuve d’une volonté de fer, $N. Vous veillez sur notre monde sans trêve ni répit. Il est temps de vous récompenser.$B$BDonnez-moi votre chevalière, afin que je renforce l’enchantement qu’elle contient.', 0),
(8753, 'frFR', 'Votre persévérance dans la défense des enfants de Kalimdor a été reconnue. Donnez-moi votre chevalière, que j’augmente ses pouvoirs.', 0),
(8754, 'frFR', 'Vous nous faites honneur, $N. Terrassez les ennemis de Kalimdor ! Montrez-leur que l’on ne profane pas impunément la terre des étoiles éternelles !$B$BVous méritez une nouvelle amélioration. Donnez-moi votre chevalière, que j’accroisse ses pouvoirs.', 0),
(8755, 'frFR', 'Une telle dévotion à une cause est une rareté. Vous fait preuve d’une volonté de fer, $N. Vous veillez sur notre monde sans trêve ni répit. Il est temps de vous récompenser.$B$BDonnez-moi votre chevalière, afin que je renforce l’enchantement qu’elle contient.', 0),
(8757, 'frFR', 'Impressionnant, petit. Vous n’avez épargné aucun effort pour gagner les faveurs du Vol de bronze. Votre dévouement a été noté.$B$BLa chevalière de l''invocateur améliorera considérablement vos capacités naturelles et magiques.$B$BMais attention, une fois que vous aurez choisi votre voie, vous ne pourrez plus revenir en arrière, même si vous changez d’avis.', 0),
(8758, 'frFR', 'Votre persévérance dans la défense des enfants de Kalimdor a été reconnue. Donnez-moi votre chevalière, que j’augmente ses pouvoirs.', 0),
(8759, 'frFR', 'Vous nous faites honneur, $N. Terrassez les ennemis de Kalimdor ! Montrez-leur que l’on ne profane pas impunément la terre des étoiles éternelles !$B$BVous méritez une nouvelle amélioration. Donnez-moi votre chevalière, que j’accroisse ses pouvoirs.', 0),
(8760, 'frFR', 'Une telle dévotion à une cause est une rareté. Vous avez fait preuve d’une volonté de fer, $N. Vous veillez sur notre monde sans trêve ni répit. Il est temps de vous récompenser.$B$BDonnez-moi votre chevalière, afin que je renforce l’enchantement qu’elle contient.', 0),
(8762, 'frFR', '$N ! Vous l’avez trouvé ? Les notes contenues dans la sacoche que je vous ai donnée vous ont-elles permis de localiser Metzen ?  Quand je pense aux horreurs que ces cruels bandits pourraient lui faire subir… Hélas, nous n’avons pas les moyens de payer une rançon aussi exorbitante !', 0),
(8764, 'frFR', 'Si vous décidez de suivre une autre voie, champion, vous devrez me remettre votre chevalière et une montagne de scarabées morts, que vous aurez tués à Ahn’Qiraj.', 0),
(8770, 'frFR', 'Vous avez quelque chose à me dire, $C ?', 0),
(8771, 'frFR', 'Vous avez quelque chose à me dire, $C ?', 0),
(8772, 'frFR', 'Vous avez quelque chose à me dire, $C ?', 0),
(8773, 'frFR', 'Vous avez quelque chose à me dire, $C ?', 0),
(8774, 'frFR', 'Vous voulez me dire quelque chose, $N ?', 0),
(8775, 'frFR', 'Vous voulez me dire quelque chose, $N ?', 0),
(8776, 'frFR', 'Vous voulez me dire quelque chose, $N ?', 0),
(8777, 'frFR', 'Vous voulez me dire quelque chose, $N ?', 0),
(8778, 'frFR', 'Vous avez quelque chose pour moi, $N ?', 0),
(8781, 'frFR', 'Vous avez quelque chose pour moi, $N ?', 0),
(8785, 'frFR', 'Avez les objets dont j''ai besoin, $N ?', 0),
(8786, 'frFR', 'Vous avez quelque chose pour moi, $N ?', 0),
(8787, 'frFR', 'Avez-vous quelque chose pour moi, $N ?', 0),
(8789, 'frFR', 'Allez chercher ce que je vous ai demandé. Vous deviendrez quelque chose de plus que la simple somme de vos éléments, champion.', 0),
(8790, 'frFR', 'Vous les abattrez et vous nous libérerez de ces liens.', 0),
(8802, 'frFR', 'Seigneur $N ! C’est fini…', 0),
(8857, 'frFR', 'Oui ? Qu’avez-vous là ?', 0),
(8858, 'frFR', 'Hmmm…', 0),
(8859, 'frFR', 'Vous avez l’air exténué, mon ami.', 0),
(8862, 'frFR', 'La chandelle d’Elune est un artefact grandement révéré par les disciples de la Fête lunaire.  Elle contient de la véritable lumière lunaire, prête à être libérée !$B$BCette lumière est inoffensive pour la plupart des créatures, mais vous constaterez qu’elle brûle et éblouit Présage et ses serviteurs.', 0),
(8864, 'frFR', 'J’ai tout un choix de robes qui vous intéresseront sûrement. Des robes comme celles-ci ont été portées lors des  fêtes lunaires des temps anciens, et la collection présente est peut-être la plus belle que j’aie jamais vue. Chaque robe a été cousue à la main dans les matériaux les plus fins et les plus doux.$B$BEn échange de quelques pièces des ancêtres, je vous laisserai choisir l’un des trois styles que j’ai en stock. Cela vous convient-il ?', 0),
(8865, 'frFR', 'Je suis ravi de vous informer que je possède un excellent choix d''habits de fête. Vous pouvez les acheter… mais uniquement contre des pièces des ancêtres.  Si la mode est importante à vos yeux, c’est exactement ce qu’il vous faut ! Je vous promets que vous ne trouverez pas leurs pareils dans tout Azeroth.$B$BEn échange de quelques pièces des ancêtres, je vous laisserai choisir l’un des trois styles que j’ai en stock. Cela vous convient-il ?', 0),
(8867, 'frFR', 'Avez-vous trouvé les lanceurs, $N ?', 0),
(8881, 'frFR', 'La fabrication des chapelets de comètes exige beaucoup de ressources et d’habileté, mais leur brillance et leur beauté valent largement les efforts ainsi déployés ! Apportez-moi des pièces des ancêtres et je vous révélerai le secret de leur création.', 0),
(8882, 'frFR', 'Les plus beaux feux d’artifice se doivent de présenter des chapelets de comètes, et ces chapelets ne peuvent être tirés qu’avec un lanceur spécial ! Il me semble donc logique que vous appreniez le secret de la fabrication des lanceurs de chapelets. Apportez-moi des pièces des ancêtres et je partagerai ce secret avec vous.', 0),
(8887, 'frFR', 'Salutations, $C, votre vue me fait bien plaisir. Je sais, maintenant que le mouillage a été conquis par les Déshérités, je ne devrais vraiment pas rester là. Velendris et ses forestiers ont juré de me protéger, à condition que je m''en aille dès que j''aurai récupéré ma cargaison.$B$BQu''avez-vous là... cela me semble vaguement familier ?', 0),
(8893, 'frFR', 'Le Super-Oeuf-O-Matic est la dernière des inventions de Curgle Cranklehop. C''est une machinerie très impressionnante.$B$BLe Super-Oeuf-O-Matic bafouille quelque chose lorsque vous vous approchez du panneau de commande.', 0),
(8924, 'frFR', 'Avez-vous récolté les ectoplasmes, $R ?', 0),
(8925, 'frFR', 'Alors, avez-vous trouvé le seigneur-magma, $N ?', 0),
(8928, 'frFR', 'Êtes-vous parvenu à mettre la main sur le diablotin de la gorge du Sombre murmure ?', 0),
(8932, 'frFR', 'Êtes-vous prêt à honorer notre marché ?', 0),
(8935, 'frFR', 'Êtes-vous prêt à honorer notre marché ?', 0),
(8938, 'frFR', 'Êtes-vous prêt à faire l’échange ?', 0),
(8944, 'frFR', 'Êtes-vous prêt à faire l’échange ?', 0),
(8946, 'frFR', 'Ysida… est-elle en vie ?', 0),
(8947, 'frFR', 'Avez-vous les matériaux dont j’ai besoin, $N ?', 0),
(8948, 'frFR', 'Eh bien, parlez, étranger. Vous ne voyez pas que je suis occupé ?', 0),
(8949, 'frFR', 'Je vous avais demandé une faveur, $N. Avez-vous terminé ?', 0),
(8950, 'frFR', 'Avez-vous les matériaux dont j’ai besoin, $N ?', 0),
(8956, 'frFR', 'Vous revoilà, $N. Vous allez tout me raconter. Mais commençons par parler de votre récompense.', 0),
(8961, 'frFR', 'Ce dernier boulot était une folie qui a scellé notre destin. Si seulement nous n’avions pas volé un morceau de l’esprit du seigneur Valthalak en même temps que l’amulette ! Nous ne savions pas qu''elle contenait son esprit ! Et si nous n’avions pas été cupides, nous ne nous serions pas partagés l’amulette… Je pourrais être en vie aujourd’hui. Je serais peut-être en train de boire une bière ou de jouer avec mes enfants.$B$B$N, prenez garde à ce que la convoitise de notre ancienne compagnie de mercenaires ne vous condamne pas à mort vous aussi.', 0),
(8962, 'frFR', 'Êtes-vous déjà de retour avec ce dont j’ai besoin, $C ?', 0),
(8964, 'frFR', 'Êtes-vous déjà de retour avec ce dont j’ai besoin, $C ?', 0),
(8966, 'frFR', 'Est-ce fait ? Avez-vous retrouvé le Morceau gauche de l’amulette du seigneur Valthalak et apporté le repos à l’esprit de mon vieux compagnon, Mor Grayhoof ?', 0),
(8970, 'frFR', 'Il me faut du varech de sang, $N. Une grande quantité. C''est indispensable pour alimenter mes sorts de divination. Je vous conseille de prendre au moins deux amis avec vous pour la récolte. Ces Strashaz sont peu commodes !', 0),
(8977, 'frFR', 'Vous êtes de retour ?', 0),
(8978, 'frFR', 'De retour avec l’appareil ?', 0),
(8985, 'frFR', 'Êtes-vous déjà de retour avec ce dont j’ai besoin, $C ?', 0),
(8988, 'frFR', 'Êtes-vous déjà de retour avec ce dont j’ai besoin, $C ?', 0),
(8990, 'frFR', 'Vous n’avez sans doute pas encore eu le temps de sauver l’esprit d’Isalien et de récupérer le Morceau droit de l’amulette du seigneur Valthalak, $N. Si ? N’oubliez pas de réassembler les morceaux de l’amulette avant de me la donner.', 0),
(8992, 'frFR', 'Si vous êtes déjà de retour avec l’amulette entière, je vous félicite, $N. Si vous n’êtes pas encore parti, hâtez-vous ! Je vous assure que nous n’avons pas de temps à perdre !', 0),
(8993, 'frFR', 'Êtes-vous venu offrir un présent d’amour et d’adoration à votre chef préféré ?', 0),
(8994, 'frFR', 'Nous avons fait une longue route ensemble, $N, et je voulais vous dire que je vous remercie du fond du cœur, quoi qu''il arrive. Vous avez affronté de terribles dangers pour aider les survivants de la Lame voilée, notre compagnie de mercenaires. En ce qui me concerne, vous êtes désormais l’un des nôtres.', 0),
(8995, 'frFR', 'Vous osez troublez mon repos, $C !', 0),
(8996, 'frFR', 'Vous êtes de retour, $N, et toujours en vie ! Hé bien, cela fait au moins un survivant.$B$BIl va falloir que vous me racontiez ça !', 0),
(9013, 'frFR', 'Êtes-vous prêt à me donner vos pièces d’armure de vaillance en échange d’un Casque et d’une Cuirasse d’héroïsme ?', 0),
(9015, 'frFR', 'Vous êtes de retour, $N !', 0),
(9017, 'frFR', 'Vous êtes de retour, $N, et je vois dans vos yeux que vous avez bien des choses à me dire. Mais occupons-nous d''abord de votre récompense.', 0),
(9022, 'frFR', 'Vous êtes de retour, $N, et je vois dans vos yeux que vous avez bien des choses à me dire. Mais occupons-nous d''abord de votre récompense.', 0),
(9023, 'frFR', 'Ça ne va pas être une petite baston toute simple, $N. Amenez des copains.', 0),
(9052, 'frFR', 'Avez-vous réussi ?', 0),
(9053, 'frFR', 'Avez-vous récupéré la liane ?', 0),
(9064, 'frFR', 'Pourquoi vous permettez-vous d''interrompre ma conférence, $C ?', 0),
(9066, 'frFR', 'Vous avez fait ce que je vous ai demandé, $N ?', 0),
(9091, 'frFR', 'Le coût du matériel est élevé, mais il est vite oublié.', 0),
(9093, 'frFR', 'Le coût du matériel est élevé, mais il est vite oublié.', 0),
(9116, 'frFR', 'M’avez-vous ramené les composants, mon enfant ?', 0),
(9121, 'frFR', 'Personne n''est revenu de Naxxramas pour raconter ce qu''il a vu.', 0),
(9122, 'frFR', 'Personne n''est revenu de Naxxramas pour raconter ce qu''il a vu.', 0),
(9125, 'frFR', 'Votre travail pour le premier lot a été exemplaire, $N. Si vous en avez plus, je peux les prendre maintenant. Pour chaque lot que vous rapporterez, je vous récompenserai avec un insigne.', 0),
(9127, 'frFR', 'Dans mon métier, un homme ne peut jamais avoir trop de fragments d''os, $N.Chaque fois que vous aurez un surplus de fragments, apportez-les-moi, je vous récompenserai avec un autre insigne.', 0),
(9128, 'frFR', 'Je ne peux que vous diriger dans la bonne direction, $N.', 0),
(9129, 'frFR', 'À vrai dire, j’utilise les noyaux pour créer des armures de givrefeu. C’est l’armure que portent les mages qui se battent dans Naxxramas. Sans vous et quelques autres, nous serions incontestablement en train de perdre cette guerre.$B$BCeci dit, vous pouvez m’apporter encore des noyaux et je vous octroierai d’autres insignes.', 0),
(9132, 'frFR', 'Pour chaque brassée de ces morceaux que vous m''apporterez, je vous donnerai un insigne - le plus sera le mieux. Hors de ma vue maintenant, avant que je vous tranche en deux !', 0),
(9135, 'frFR', 'Déjà de retour, $C ? Ce sont les fournitures que vous êtes partie chercher ? Tout ne peux pas tenir là-dedans, c''est impossible !', 0),
(9137, 'frFR', 'Pour chaque fagot de palmes que vous me livrerez, je vous payerai avec un insigne de votre choix, de l’Aube ou de la Croisade.$B$BLes insignes peuvent être échangés auprès des intendants contre toutes sortes de récompenses.', 0),
(9140, 'frFR', 'Avez-vous libéré Coursevent, $C ? Ces maudits magistères du sanctum du Soleil me bombardent de demandes au sujet des morceaux de créatures du Fléau que vous devez me remettre.$B$BNe vous en souciez pas trop, cela dit. Prenez votre temps et faites du bon travail. Je m''occupe des magistères.', 0),
(9143, 'frFR', 'Alors, vous avez ces oreilles de trolls ?$B$BVous savez, si nous recevions des renforts de Tranquillien de temps à autre, le problème ne se poserait pas. Heureusement que vous êtes là.', 0),
(9149, 'frFR', 'Avez-vous obtenu les spécimens que je vous ai demandés, $N ?', 0),
(9150, 'frFR', 'Avez-vous récupéré les essences, $N ?', 0),
(9152, 'frFR', 'Dès que j''aurai récupéré le reste de ma marchandise, je pourrai accueillir les clients. Les troupes n''iront pas bien loin si elles ne peuvent pas acheter ce dont elles ont besoin.$B$BLes zones de guerre sont des endroits tellement profitables ! Vous ne trouvez pas, $C ? Bon, avez-vous réussi à vous frayer un chemin à travers les goules jusqu''à mon chariot ?', 0),
(9153, 'frFR', 'Il nous faudra du temps pour venir à bout de cette menace. Comment ça c’est passé pour vous, $N ?', 0),
(9163, 'frFR', 'Comment progressent vos efforts pour découvrir ce que complotent les elfes de la nuit de l''île de Shalandis, $C ?', 0),
(9178, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9179, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9184, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9185, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9186, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9187, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9188, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9190, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9191, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9194, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9195, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9196, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9198, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9200, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9201, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9202, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9204, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9205, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9206, 'frFR', 'Vous êtes là pour honorer une commission, $C ?', 0),
(9211, 'frFR', 'S’il n’y avait pas ces gardes de l’Aube d’argent, vous ne seriez plus qu’une petite flaque sur le sol.', 0),
(9213, 'frFR', '<Mataus baille. >$B$BDu vent, moustique, sauf si vous avez quelque chose pour moi.', 0),
(9215, 'frFR', 'Qu''est-ce que c''est que cette odeur infecte ?', 0),
(9216, 'frFR', 'Avez-vous les cœurs de zombie que je vous avais demandés, $N ?', 0),
(9217, 'frFR', 'Vous m''avez apporté d''autres cœurs de goules ? Je peux utiliser tous ceux que vous trouverez, $N.', 0),
(9218, 'frFR', 'Avez-vous les échantillons que je vous avais demandés, $N ?', 0),
(9226, 'frFR', 'Choisissez avec soin. Vous ne pourrez être remboursée.', 0),
(9227, 'frFR', 'Choisissez avec soin. Vous ne pourrez être remboursé.', 0),
(9228, 'frFR', 'Choisissez avec soin. Vous ne pourrez être remboursé.', 0),
(9229, 'frFR', 'Des nouvelles de Ramaladni ?', 0),
(9230, 'frFR', 'Vous trouverez probablement des runes de givre à l’intérieur de Naxxramas.', 0),
(9232, 'frFR', 'Vous n’auriez pas croisé Omarion, par hasard ?', 0),
(9233, 'frFR', 'Est-ce que c’est ce que je crois ?$B$B<Wilhelm bave d’envie. >', 0),
(9248, 'frFR', 'Fandu-dath-belore ? Oh, excusez-moi, $N, je ne vous avais pas reconnu. Avez-vous le sceptre ?', 0),
(9252, 'frFR', 'Nous vaincrons, $N.', 0),
(9259, 'frFR', 'Ce chien galeux d''Revilgaz a offert son pardon à tous les anciens membres d''la Voile sanglante qui acceptent d''se r''tourner contre leur ''pitaine ! C''buveur d''eau croupie m''a donné l''boulot d''buter tous mes vieux copains et d''ramener leurs bandeaux comme preuve.$B$BJ''ai pas l''cœur à faire c''genre de truc, et j''vous l''demanderai pas non plus. Apportez-moi d''l''étoffe de soie et d''la teinture rouge, et j''arrangerai l''coup en faisant d''faux bandeaux. J''dirai au baron qu''vous avez r''tourné vot'' veste, mais faites gaffe... ceux d''la Voile sanglante vont pas apprécier !', 0),
(9268, 'frFR', 'Vous voulez vous rabibocher avec les gobelins de Tanaris, $N ? Nous avons besoin de matériaux pour nos voiles et d’armes à feu pour repousser nos vieux ennemis, les boucaniers de la Voile sanglante. Apportez-moi du tisse-mage et des catalyseurs puissants, et nous serons plus à même de vous pardonner vos fautes.', 0),
(9324, 'frFR', 'Vous rayonnez littéralement, $R. Qu''est-ce que vous avez là ?', 0),
(9325, 'frFR', 'Vous rayonnez littéralement, $R. Qu''est-ce que vous avez là ?', 0),
(9326, 'frFR', 'Vous rayonnez littéralement, $R. Qu''est-ce que vous avez là ?', 0),
(9328, 'frFR', 'Vous désirez une audience, $C ? Je n''ai pas le souvenir que vous ayez pris rendez-vous.', 0),
(9330, 'frFR', 'Vous rayonnez littéralement, $R. Qu''est-ce que vous avez là ?', 0),
(9331, 'frFR', 'Vous rayonnez littéralement, $R. Qu''est-ce que vous avez là ?', 0),
(9332, 'frFR', 'Vous rayonnez littéralement, $R. Qu''est-ce que vous avez là ?', 0),
(9338, 'frFR', 'Même si vous n''avez pas besoin des récompenses matérielles que nous proposons, ces badges sont la marque de notre amitié et de notre confiance mutuelle.$B$BApportez-les-moi. Je ne manquerai pas de prendre note des services que vous nous rendrez s''ils allaient au-delà de l''appel du devoir.', 0),
(9362, 'frFR', 'Nous n''avons pas de temps à perdre ! Vous avez la coquille ?', 0),
(9364, 'frFR', 'Avez-vous collecté la magie ?', 0),
(9402, 'frFR', 'Alors, elle est bonne ?', 0),
(9403, 'frFR', 'Seule l''eau des chutes de l''Elrendar nous donnera une eau d''une pureté suffisante. En avez-vous ?', 0),
(9404, 'frFR', 'Vous avez la branche vivante ? Passez-la-moi, vite !', 0),
(9406, 'frFR', 'Que nous apportez-vous, $N ?', 0),
(9422, 'frFR', 'Prenez garde aux périls du désert, $N. L’Alliance rôde entre les dunes. Chaque pas peut être votre dernier.', 0),
(9437, 'frFR', 'Hai liberato Ithania e recuperato il mio carico da quei corsari?', 0),
(9465, 'frFR', 'Avez-vous la torche ?', 0),
(9467, 'frFR', 'Ne m''adressez plus la parole tant que vous n''aurez pas les cendres d''Arrogance.', 0),
(9474, 'frFR', 'La Marque du Porteur de Lumière est un symbole puissant de la foi d''Uther en la Lumière.', 0),
(9484, 'frFR', 'Avez-vous maîtrisé le faucon-dragon ?', 0),
(9485, 'frFR', 'Avez-vous maîtrisé une brumoptère ?', 0),
(9486, 'frFR', 'Avez-vous chassé aux côtés des Prestes-pattes ?', 0),
(9487, 'frFR', 'Vous ne vous êtes pas trop approchée de ces brutes, j''espère ?', 0),
(9488, 'frFR', 'Impossible de terminer la robe sans les composants. Mais vous le saviez déjà, n''est-ce pas ?', 0),
(9495, 'frFR', 'Avez-vous la preuve de la défaite de Kargath Lamepoing ?', 0),
(9504, 'frFR', 'Avez-vous l''eau pure des ruines ?', 0),
(9508, 'frFR', 'Avez-vous réussi ?', 0),
(9509, 'frFR', 'Les éléments m''ont parlé de vos exploits. Approchez, nous devons parler.', 0),
(9521, 'frFR', 'Qu''avez-vous ici, $C ?', 0),
(9526, 'frFR', 'Vous n''avez sûrement pas encore planté toutes mes graines ?', 0),
(9554, 'frFR', 'Déjà de retour ? Vous avez l''air un peu ébouriffé.$B$B<Nobundo sourit finement.>', 0),
(9582, 'frFR', 'Avez-vous tué la bête ?', 0),
(9591, 'frFR', 'Avez-vous pu employer la magie du totem pour apprivoiser un clampant barbelé ? Ce sont de petites créatures teigneuses !', 0),
(9592, 'frFR', 'Le trotteur des bois est un oiseau redoutable. Les prédateurs qui le sous-estiment en payent le prix.', 0),
(9593, 'frFR', 'Les traquenuits ne sont que de gros chats, avec des griffes tranchantes comme des rasoirs et un appétit prononcé pour la viande...', 0),
(9594, 'frFR', 'Oui, $C ? Qu''avez-vous là ?', 0),
(9598, 'frFR', 'Soyez de nouveau le bienvenu, $N.', 0),
(9605, 'frFR', 'Où allez-vous, $C ?', 0),
(9635, 'frFR', 'Alors, vous avez ces pièces ? Faut que je plonge.', 0),
(9642, 'frFR', 'Si vous avez d''autres éclats de cristal irradiés, je serai ravi de les échanger contre l''un de mes cristaux.', 0),
(9646, 'frFR', 'En quoi puis-je vous aider, $C ?', 0),
(9683, 'frFR', 'Vous devez attirer Atoph !', 0),
(9684, 'frFR', 'Avez-vous parlé au magistère Astalor Ligessang ?', 0),
(9692, 'frFR', 'Avez-vous accompli tout ce qui vous était demandé ?', 0),
(9705, 'frFR', 'Qu''avez-vous trouvé, $N ?', 0),
(9706, 'frFR', 'Qu''avez-vous là, $N ? Est-ce un journal ?', 0),
(9707, 'frFR', 'Félicitations, $N. Parvenir au rang d''adepte n''est pas un mince exploit, croyez-moi. J''ai vu tant de personnes entrer dans ce bâtiment, et si peu d''entre elles ont duré assez longtemps pour venir m''apporter ces matériaux.', 0),
(9709, 'frFR', 'Avez-vous tous les champignons dont nous avons besoin pour ensemencer un nouveau jardin pour les seigneurs-tourbe ?', 0),
(9714, 'frFR', 'Nous avons toujours besoin de plus d''hibiscus sanguin provenant des traînards, des géants des tourbières et des basse-tourboptères de Basse-tourbière, dans le réservoir de Glissecroc. Apportez-m''en par paquet de cinq et je vous serai très reconnaissant.', 0),
(9726, 'frFR', 'Avez-vous déjà rendu visite aux nagas ?', 0),
(9727, 'frFR', 'Avez-vous déjà rendu visite aux nagas ?', 0),
(9731, 'frFR', 'Quelles sont les nouvelles, $N ?', 0),
(9737, 'frFR', 'Avez-vous agi selon mes ordres et transmis mon message ? Les faux paladins de ce monde doivent savoir que leur temps est arrivé à sa fin.', 0),
(9744, 'frFR', 'Vous avez tué de nombreux géants, mais il en reste encore beaucoup. Et ils attaquent toujours nos sacs de spores !', 0),
(9766, 'frFR', 'Nous allons forger le propre acier des nagas pour en faire des armes que nous utiliserons contre eux. Apportez-moi toutes les armes que vous parviendrez à récupérer au réservoir de Glissecroc.', 0),
(9784, 'frFR', 'Il me faudrait encore d''autres morceaux de plantes. Avec la baisse du niveau des eaux, j''ai l''impression que le nombre d''espèces envahissantes augmente. J''ai cependant besoin d''un échantillon plus large pour appuyer ma théorie.', 0),
(9788, 'frFR', 'Avez-vous trouvé mes affaires, $N ? La caverne n''est pas loin d''Umbretourbe, près de la frontière avec Nagrand.', 0),
(9806, 'frFR', 'Vous êtes de retour, $N. Vous avez récupéré les spores fertiles ?', 0),
(9807, 'frFR', 'Nous avons toujours l''usage de spores fertiles, $R. Les Grands-pieds sont des champignons extrêmement utiles. Pouvoir les cultiver nous permet de faire d''innombrables choses.', 0),
(9809, 'frFR', 'Je vous prendrai tous les chapeluisants que vous pourrez trouver. Notre village en a toujours besoin.', 0),
(9827, 'frFR', 'Qu''avez-vous là, $N ?', 0),
(9828, 'frFR', 'Qu''avez-vous là, $N ?', 0),
(9831, 'frFR', 'Vous vous êtes procuré le fragment, $C ? Vous feriez bien de ne pas perdre de temps.', 0),
(9841, 'frFR', 'Le bruit semble s''être éloigné. C''est moi qui rêve, ou vous avez vraiment fait quelque chose pour résoudre le problème ?', 0),
(9882, 'frFR', 'Avez-vous récupéré les fragment de cristal que je vous ai demandés, $N ?', 0),
(9883, 'frFR', 'Vous avez d''autres fragments de cristal ? Faites bien attention de ne pas en prendre qui sont encore attachés à la montagne ; nous ne voulons pas de problèmes avec les naaru.', 0),
(9892, 'frFR', 'Avez-vous obtenu d''autres perles de guerre ? Vous trouverez beaucoup d''ogres tout au nord, près de la frontière avec le marécage de Zangar.', 0),
(9893, 'frFR', 'Comment ça se passe avec les Ogres, $N ? Ils sont coriaces, hein ?', 0),
(9894, 'frFR', 'Avez--vous trouvé le seigneur Klaq ? Vous êtes-vous chargé de lui ?', 0),
(9895, 'frFR', 'Avez-vous rencontré Fouettourbe ?', 0),
(9915, 'frFR', 'J''ai encore besoin de paires de défenses en ivoire d''elekk sauvages qui vivent dans cette région. Malheureusement, mon budget ne me permet plus de vous verser votre part des profits. Mais si vous voulez bien continuer à me fournir ce dont j''ai besoin, vous vous attirerez les bonnes grâces du Consortium.', 0),
(9918, 'frFR', 'Il est probablement en train de dormir en haut d''une crête.', 0),
(9919, 'frFR', 'Vous avez quelque chose à me montrer, $N ?', 0),
(9927, 'frFR', '<Lantresor roule des yeux stupéfaits.>$B$BC''est fait ?', 0),
(9935, 'frFR', 'Êtes-vous ici pour chercher une récompense ?', 0),
(9951, 'frFR', 'Nous n''aurions jamais dû les inviter pour dîner. Ça, c''est certain !$B$BNous aurions au moins dû insister pour qu''il y ait quelques plats avant le dessert qu''ils ont apporté.', 0),
(9990, 'frFR', 'Quelles nouvelles apportez-vous, $N ?', 0),
(9994, 'frFR', 'Vous avez l''air préoccupé. Qu''y a-t-il, $C ?', 0),
(9995, 'frFR', 'Vous avez l''air préoccupé. Qu''y a-t-il, $C ?', 0),
(10012, 'frFR', 'Qu''avez-vous là, $N ?', 0),
(10013, 'frFR', 'Qu''est-ce que vous avez là, $N ?', 0),
(10018, 'frFR', 'Avez-vous pu trouver toutes les fourrures dont j''ai besoin ?', 0),
(10024, 'frFR', 'Vous êtes-vous procuré les yeux de basilic pour l''élixir de Voren''thal ?', 0),
(10025, 'frFR', 'il faut beaucoup d''yeux de basilic pour faire ne serait-ce qu''une petite dose d''élixir de Voren''thal. Si vous m''en apportiez plus, cela vous attirerait sans nul doute la faveur des Clairvoyants.', 0),
(10040, 'frFR', 'Avez-vous déjà parlé à chacun d''entre eux ? Qu''est-ce qu''ils ont dit ?', 0),
(10041, 'frFR', 'Avez-vous déjà parlé à chacun d''entre eux ? Qu''est-ce qu''ils ont dit ?', 0),
(10045, 'frFR', 'Bonjour, mon petit.', 0),
(10075, 'frFR', 'Cette base était le principal centre de recherche où les draeneï étudiaient les cristaux naaru.$B$BNous avons découvert une véritable mine d''or sous la forme de notes consacrées aux cristaux de la « montagne de diamant », Oshu''gun. On dirait que tout, dans la région, contient une parcelle de pouvoir des cristaux d''Oshu''gun. Si vous trouvez de la poudre lorsque vous sillonnerez la région, remettez-là moi. En échange, je vous donnerai un petit quelque chose qui vous permettra de faire des achats auprès de notre service d''intendance.', 0),
(10077, 'frFR', 'Cette base était le principal centre de recherche où les draeneï étudiaient les cristaux naaru.$B$BNous avons découvert une véritable mine d''or sous la forme de notes consacrées aux cristaux de la « montagne de diamant », Oshu''gun. On dirait que tout, dans la région, contient une parcelle de pouvoir des cristaux d''Oshu''gun. Si vous trouvez de la poudre lorsque vous sillonnerez la région, remettez-là moi. En échange, je vous donnerai un petit quelque chose qui vous permettra de faire des achats auprès de notre service d''intendance.', 0),
(10079, 'frFR', 'Dites-moi que les tremblements sont finis et que mes gars peuvent se remettre au boulot... s''il vous plaît ?', 0),
(10085, 'frFR', 'Filez comme le vent, $N.', 0),
(10091, 'frFR', 'Oui ? Que puis-je faire pour vous, $C ?', 0),
(10110, 'frFR', 'Revenez me voir lorsque vous aurez participé à la capture de tous ces forts !', 0),
(10142, 'frFR', 'Le bastion de l''Honneur est en sécurité tant que les archers surveillent les cieux.', 0),
(10172, 'frFR', '<La grande-mère Geyah s''allonge.>', 0),
(10183, 'frFR', 'Occupé, occupé, pas de temps à perdre, j''ai une fusée à construire.$B$BVous voulez quoi ?', 0),
(10189, 'frFR', 'Vous êtes-vous procuré les objets que je vous ai demandés, $N ?', 0),
(10191, 'frFR', 'Déjà de retour ?$B$BTout se passe bien avec le Maxx A. Million Mod. V ?!', 0),
(10198, 'frFR', 'Où en est votre espionnage, $N ? Il faudrait vous dépêcher. Je commence à devenir fébrile.', 0),
(10205, 'frFR', 'C''est fini, alors ? L''écumeur-dimensionnel Nesaad est mort ?', 0),
(10208, 'frFR', 'La Légion ne s''attend pas à la surprise que vous lui réservez, n''est-ce pas, $N ?', 0),
(10231, 'frFR', 'Kestu veux ?', 0),
(10233, 'frFR', 'De la fumée s''élève des fortifications du bastion des Solfurie. Est-ce votre œuvre ?', 0),
(10243, 'frFR', 'Les symboles qui défilent devant vous sont étranges et inintelligibles.', 0),
(10245, 'frFR', 'Voyons ce que vous nous avez apporté, $N.', 0),
(10257, 'frFR', 'Vous avez la Pierre cruciale ?', 0),
(10270, 'frFR', 'Êtes-vous prêt à parler affaires maintenant, $N ?', 0),
(10271, 'frFR', 'Je suis certain que vous avez beaucoup de questions à poser. Vous aurez toutes les réponses en temps voulu.', 0),
(10272, 'frFR', 'Avez-vous pu récolter les œufs ?', 0),
(10273, 'frFR', 'Ce Marid est un idiot. Ou, devrais-je dire, était un idiot.', 0),
(10274, 'frFR', 'Avez-vous défié et vaincu Veraku ?', 0),
(10276, 'frFR', 'Bonjour à vous, mon ami. Que donnent vos efforts pour trouver le cristal ?', 0),
(10283, 'frFR', 'Qui êtes-vous ?', 0),
(10284, 'frFR', '<Erozion hoche la tête.>', 0),
(10297, 'frFR', 'Vous ne pouvez utiliser qu''une chrono-balise par niche temporelle.', 0),
(10314, 'frFR', 'Qu''avez-vous découvert, $N ?', 0),
(10327, 'frFR', 'S''il vous reste d''autres insignes, ils m''intéressent. Ne vous en faites pas, vos actions seront dûment rapportées.', 0),
(10330, 'frFR', 'Avez-vous déjà accompli votre tâche, $N ?', 0),
(10339, 'frFR', 'Bon travail, être de chair...', 0),
(10356, 'frFR', 'Nous collectons en ce moment du tisse-mage. Un don de soixante morceaux de tisse-mage vous vaudrait la reconnaissance de tout mon peuple pour vos généreuses actions.$B$BSi vous avez les soixante morceaux de tisse-mage sur vous, vous pouvez les donner maintenant.', 0),
(10359, 'frFR', 'Apportez-moi soixante morceaux d''étoffe de laine et vous recevrez la reconnaissance de Lune-d''argent pour vos généreuses actions.$B$BSi vous les avez maintenant, je peux les prendre.', 0),
(10360, 'frFR', 'Apportez-moi soixante morceaux d''étoffe de soie et vous recevrez la reconnaissance de Lune-d''argent pour vos généreuses actions.$B$BSi vous les avez maintenant, je peux les prendre.', 0),
(10361, 'frFR', 'Apportez-moi soixante morceaux d''étoffe de tisse-mage et vous recevrez la reconnaissance de Lune-d''argent pour vos généreuses actions.$B$BSi vous les avez maintenant, je peux les prendre.', 0),
(10392, 'frFR', 'Faites vite, $N. Pour chaque seconde que ce portail reste ouvert, c''est un nouveau démon abject qui arrive en ce monde !', 0),
(10395, 'frFR', 'Qu''y a-t-il, $C ? Je sens que vous avez trouvé quelque chose qui annonce un malheur imminent.', 0),
(10406, 'frFR', 'Il faut qu''il réussisse !', 0),
(10408, 'frFR', 'Est-il... vraiment mort ? Détruit ?', 0),
(10410, 'frFR', 'Qu''est-ce qui vous tourmente, mon enfant ?', 0),
(10413, 'frFR', 'Hmm, vous avez l''air un peu sale... Où avez-vous donc traîné ?', 0),
(10414, 'frFR', 'Même la plus petite contribution à notre cause est dûment notée, $N. Nos ennemis sont nombreux, mais nous vaincrons !', 0),
(10421, 'frFR', 'Avez-vous trouvé des armes gangrenées dernièrement ? Laissez la Lumière faire son travail, $N. Ne permettez pas à ces objets maléfiques de rester dans ce monde.', 0),
(10439, 'frFR', 'Qu''en est-il du seigneur du Vide ?', 0),
(10450, 'frFR', 'Vous avez affronté les Mâche-les-os, $N ? J’espère que vous avez répandu leur sang à grands flots !', 0),
(10471, 'frFR', 'Vous êtes de retour. Souhaitez-vous me parler ?', 0),
(10472, 'frFR', 'Que le temps soit toujours de votre côté, $N.', 0),
(10473, 'frFR', 'Que le temps soit toujours de votre côté, $N.', 0),
(10474, 'frFR', 'Que le temps soit toujours de votre côté, $N.', 0),
(10475, 'frFR', 'Que le temps soit toujours de votre côté, $N.', 0),
(10476, 'frFR', 'Eh bien, $N ? Est-ce que vous ne savez que parler, ou bien avez-vous quelque chose à me montrer ?', 0),
(10477, 'frFR', 'Vous continuez à nous prouver votre valeur, $N. Que votre force ne vous abandonne jamais.', 0),
(10478, 'frFR', 'Vous continuez à prouver votre force et votre honneur, $N.', 0),
(10479, 'frFR', 'Avez-vous quelque chose à me montrer, $N ?', 0),
(10508, 'frFR', 'Avez-vous récupéré la pierre de téléportation de Socrethar, $N ?', 0),
(10519, 'frFR', 'Soyez patient et écoutez, $N.', 0),
(10538, 'frFR', 'Vous avez le sang bouilli, $N ? J’ai hâte de pouvoir l’étudier à mon aise, et cette fois sans être interrompu.', 0),
(10557, 'frFR', 'N''ayez pas peur ! C''est pour la science, et il faut souffrir pour devenir savant !', 0),
(10590, 'frFR', 'Avez-vous écrasé le Fléau sous vos coups ?', 0),
(10593, 'frFR', 'Comme vous avez survécu, je suppose que vous avez été assez chanceux, et que dame Sylvanas vous a offert ses connaissances plutôt que la mort.', 0),
(10612, 'frFR', 'Vous êtes de retour, j''imagine donc que l''opération s''est bien déroulée. Qu''avez-vous à rapporter ?', 0),
(10649, 'frFR', 'Vous êtes-vous procuré le livre, $N ?', 0),
(10655, 'frFR', 'S''il vous reste d''autres insignes, ils m''intéressent. Ne vous en faites pas, vos actions seront dûment rapportées.', 0),
(10659, 'frFR', 'Même la plus petite contribution à notre cause est dûment notée, $N. Nos ennemis sont nombreux, mais nous vaincrons !', 0),
(10662, 'frFR', 'Qu''est-ce qui vous amène ici, $C ? Je n''ai pas souvent de visite.', 0),
(10665, 'frFR', 'Avez-vous réussi à sortir une cellule de mana du Méchanar ?', 0),
(10666, 'frFR', 'Avez-vous récupéré le livre ?', 0),
(10667, 'frFR', 'Avez-vous récupéré la terre du monde souterrain ?', 0),
(10670, 'frFR', 'Avez-vous pu arracher la gemme à la poigne d''O''mrogg ?', 0),
(10679, 'frFR', 'Avez-vous trempé l''épée dans la lave de la Main de Gul''dan ?', 0),
(10742, 'frFR', 'Nous ne pourrons pas libérer les Mok''Nathal sans passer par la mort de Goc et de Gorgrom le Mange-dragon.', 0),
(10758, 'frFR', 'Avez-vous fait ce que je vous avais demandé, $C ?', 0),
(10764, 'frFR', 'Avez-vous fait ce que je vous avais demandé, $C ?', 0),
(10809, 'frFR', '$N, au rapport ! Serait-ce du sang de l’Orbite-Sanglante que j’aperçois sur votre manche ? J’espère bien que oui !', 0),
(10812, 'frFR', 'Je n''en crois pas mes yeux.', 0),
(10814, 'frFR', 'Permettez-moi d''achever mon récit.', 0),
(10820, 'frFR', 'Ma patience s''épuise, pourquoi n''en avez-vous pas encore fini avec eux ?', 0),
(10822, 'frFR', 'Même la plus petite contribution à notre cause est dûment notée, $N. Nos ennemis sont nombreux, mais nous vaincrons !', 0),
(10828, 'frFR', 'S''il vous reste d''autres insignes, ils m''intéressent. Ne vous en faites pas, vos actions seront dûment rapportées.', 0),
(10832, 'frFR', 'Avez-vous l''échantillon d''essence d''âme en peine du Néant ?', 0),
(10836, 'frFR', 'Est-ce fait ? Je ne peux qu''espérer qu''il n''est pas trop tard...', 0),
(10848, 'frFR', 'Le mal grandit au Voile Rhaze. Mettez-y un terme, $R.', 0),
(10850, 'frFR', 'Vous découvrez une ouverture grâce à laquelle le carburant est versé dans le saccageur gangrené.', 0),
(10864, 'frFR', 'Le scrutateur démonien n''est pas encore apaisé, $N. Revenez me voir quand vous aurez récolté les âmes des orcs de la Main brisée.', 0),
(10867, 'frFR', 'Est-ce fait ? Les âmes de nos ancêtres ont-elles été reprises aux maléfiques éthériens ?', 0),
(10880, 'frFR', 'Vous souhaitez me montrer quelque chose, $N ?', 0),
(10881, 'frFR', 'Avez-vous récupéré les reliques, $N ? Nous ne pouvons pas laisser le Conseil des ombres exploiter leurs pouvoirs à des fins ténébreuses.', 0),
(10897, 'frFR', 'Vous êtes sûr que c''est ce que vous voulez, $N? Si vous vous spécialisez dans les potions, vous ne pourrez plus changer de spécialité.', 0),
(10902, 'frFR', 'Les essences ! Les avez-vous ?', 0),
(10917, 'frFR', 'Est-ce que vous avez les plumes que j''ai demandées, $N ?', 0),
(10918, 'frFR', 'Les laquais de Skettis nous surveillent de près, nous autres parias. Si l''un d''entre nous met un pied hors de Shattrath, c''est comme s''il était mort.$B$BApportez-moi plus de plumes comme preuves de votre victoire sur eux.', 0),
(10919, 'frFR', 'Fei Fei vous regarde, avec l''air d''attendre quelque chose...', 0),
(10921, 'frFR', 'Terokkarantula a-t-elle été tuée ?', 0),
(10938, 'frFR', 'Je vois que vous avez réussi à réunir une suite de Bénédictions ! Félicitations !', 0),
(10940, 'frFR', 'Je vois que vous avez réussi à réunir une suite de Furies ! Félicitations !', 0),
(10941, 'frFR', 'Je vois que vous avez réussi à réunir une suite de Déraison ! Félicitations !', 0),
(10961, 'frFR', 'Avez-vous les ingrédients pour le breuvage ? Prenez garde à ne pas mettre de pollen sur moi, s''il vous plaît. Le pollen me fait éternuer de façon incontrôlable.$B$B<Morthis fait la moue en pensant à l''indignité qu''est pour lui un éternuement.>', 0),
(10962, 'frFR', 'Vous croyez que c''est vrai, ce qu''on raconte sur les Grottes du temps ?', 0),
(10963, 'frFR', 'Si ce qu''on dit sur les Grottes du temps est vrai, alors ça doit être un endroit à la très grande puissance.', 0),
(10964, 'frFR', '<Vous vous préparez à administrer la potion au $C endormi.>', 0),
(10966, 'frFR', 'C''est bon de vous revoir, $C. J''imagine que vous et la jeune Dornaa vous êtes bien amusés ensemble ?', 0),
(10967, 'frFR', 'C''est bon de vous revoir, $C. J''imagine que vous et la jeune Salandria vous êtes bien amusés ensemble ?', 0),
(10971, 'frFR', 'Avez-vous récupéré des plaques d''identité ?', 0),
(10972, 'frFR', 'Il me faut plus de plaques d''identité, $N. Pour l''instant, j''ai découvert qu''il ne s''agit pas seulement d''un moyen de recenser les prisonniers, mais aussi d''en indiquer la localisation !$B$BUne fois le code décrypté, nous pourrons déterminer exactement où nos alliés sont retenus et les libérer avec le minimum de réaction hostile.', 0),
(10973, 'frFR', 'Je sais que je vous demande beaucoup, mais pensez aux vies qui pourraient être sauvées !', 0),
(10974, 'frFR', 'Vous avez survécu ! Alors, avez-vous trouvé ?', 0),
(10975, 'frFR', 'Nous sommes dans une impasse, $N. Les données que vous avez recueillies nous ont fourni assez d''éléments pour libérer nos alliés détenus dans les petites prisons du Raz-de-Néant, mais nous devons aller de l''avant et éradiquer la plus grave menace que constitue l''Ethereum au point d''ancrage de Bash''ir.$B$BJoignez-vous à la bataille contre l''Ethereum ! Apportez-moi des clés de prison de l''Ethereum et je vous forgerai des clés de chambres de stase que vous pourrez utiliser à Bash''ir.', 0),
(10976, 'frFR', 'C''est là votre mission la plus effrayante, $N.', 0),
(10977, 'frFR', 'Je comprendrais si vous décidiez de ne pas continuer, $N.', 0),
(10978, 'frFR', 'Clintar vous a-t-il aidé à récupérer les reliques ?', 0),
(10980, 'frFR', '<Arthorn vous lance un regard plein d''espoir.>$B$BAvez-vous réussi à obtenir des informations sur le livre ?', 0),
(10981, 'frFR', 'Seul le plus solide et aguerri des aventuriers répondra à mon appel, $N. Si vous souhaitez affronter les horreurs de la seconde chambre de stase des Tombes-mana, je peux vous forger une clé. Apportez-moi une marque du roi-nexus, et je la fabriquerai.', 0),
(10985, 'frFR', '<Xi''ri prend note de votre présence.>', 0),
(10987, 'frFR', 'Avez-vous attrapé une crécerelle ?', 0),
(10988, 'frFR', 'Avez-vous récupéré assez de fragments du Livre du Corbeau pour que je puisse le reconstituer ?', 0),
(10990, 'frFR', '<La crécerelle semble parler avec la voix d''Arthorn.>$B$BAvez-vous réussi à libérer l''essence de l''esprit de l''Aigle ?', 0),
(10991, 'frFR', '<Cette fois encore, la voix d''Arthorn vous parvient par la crécerelle.>$B$BAvez-vous l''essence de l''Épervier ?', 0),
(10992, 'frFR', 'Avez-vous triomphé du gardien du faucon pour récupérer son essence ?', 0),
(10993, 'frFR', 'J''attends des nouvelles d''Arthorn. Qu''avez-vous découvert ?', 0),
(10994, 'frFR', 'On dirait que vous en avez vu de toutes les couleurs. La pierre de lune était-elle si difficile que ça à trouver ?', 0),
(11001, 'frFR', 'Quelles nouvelles ramenez-vous des salles des Sethekk ? Anzu est-il vaincu ?', 0),
(11002, 'frFR', 'Pour la première fois, aussi loin que remontent mes souvenirs, le silence règne.', 0),
(11003, 'frFR', 'Pour la première fois, aussi loin que remontent mes souvenirs, le silence règne.', 0),
(11004, 'frFR', 'Vous vous êtes procuré la poussière, $N ?', 0),
(11006, 'frFR', 'Il semblerait que le commandant n''aie pas été en proie à un délire fiévreux, finalement. Apportez-moi plus de poussière, et je vous préparerai un nouvel élixir.', 0),
(11007, 'frFR', 'Vous avez entendu mon appel ? Oui...', 0),
(11008, 'frFR', 'Avez-vous déjà accompli votre mission ?', 0),
(11021, 'frFR', 'Vous avez quelque chose à me montrer ?', 0),
(11026, 'frFR', 'Nous supposons que vous avez utilisé le cristal de bannissement pour renvoyer un tas de démons dans leurs pénates ?!', 0),
(11033, 'frFR', 'Vous êtes revenu sur votre choix ? J''imagine que je peux vous aider à faire marche arrière. Au final, Dalaran se soucie plus de votre loyauté que de la manière dont vous choisissez de l''exercer.$B$BCela va coûter cher. Et, bien sûr, il va falloir que je récupère votre bague.', 0),
(11034, 'frFR', 'Vous êtes revenu sur votre choix ? J''imagine que je peux vous aider à faire marche arrière. Au final, Dalaran se soucie plus de votre loyauté que de la manière dont vous choisissez de l''exercer.$B$BCela va coûter cher. Et, bien sûr, il va falloir que je récupère votre bague.', 0),
(11036, 'frFR', 'C''est la livraison du vieil Orok ?', 0),
(11050, 'frFR', 'Il ne faut pas que ces œufs tombent entre de mauvaises mains, $N. Apportez-moi tous les autres œufs que vous pourriez trouver.$B$BMais n''oubliez pas de garder profil bas et évitez d''attirer les soupçons !', 0),
(11054, 'frFR', 'Il y a des péons à châtier, $N ! On se dépêche !', 0),
(11059, 'frFR', 'Nous abhorrons la violence, mais au moins, la structure que nous vous avons envoyé affronter n''est pas un être vivant.$B$BÀ ce propos, vous avez la tête ?', 0),
(11061, 'frFR', 'Ce flacon du sorcier va sûrement rendre mes fils bien plus intelligents qu’ils ne le sont déjà. Cela devrait beaucoup les aider pour ce qu’ils devront faire quand ils seront entrés dans la Garde-ciel.', 0),
(11065, 'frFR', 'Vous ne m’avez pas encore dompté quelques raies de l’éther ? Vous avez pourtant l’air de savoir vous débrouiller avec un lasso, cela ne devrait pas vous prendre trop de temps.', 0),
(11074, 'frFR', 'Il me faut un attribut de chacun des descendants des plus grands adversaires de Terokk. Alors seulement serons-nous prêts à l''invoquer.', 0),
(11078, 'frFR', 'Comment va vot’ mission, $N ? J’n’ai pas besoin d’vous dire à quel point elle est importante, pour qu’on puisse continuer à voler dans l’coin.', 0),
(11086, 'frFR', 'Après tout, c''est notre seigneur qui a banni les démons de l''Outreterre et fermé leurs portails. Tous devraient s''agenouiller devant la magnificence d''Illidan.', 0),
(11105, 'frFR', 'La puissance qu''abrite votre bague est malléable, même si revenir sur votre choix n''est pas chose aisée. Êtes-vous sûr de vouloir en changer ?', 0),
(11117, 'frFR', 'Vous êtiez assez soûl pour voir ces p''tites canailles ?', 0),
(11118, 'frFR', 'Ces fichus elekk roses sont enfin partis ?', 0),
(11120, 'frFR', 'Vous avez dégagé ce petit problème dont nous avions parlé ?', 0),
(11126, 'frFR', 'Avez-vous chassé les agents des déserteurs de Theramore ?', 0),
(11130, 'frFR', '<Budd jette un coup d''œil suspicieux à la note.>$B$BQu''est-ce que vous avez là, $C ?', 0),
(11131, 'frFR', '$N, vous avez promis de sauver les enfants !', 0),
(11182, 'frFR', 'Où en êtes-vous avec ces cruels dresseurs, mon petit ?', 0),
(11186, 'frFR', 'Que m''apportez-vous, $C ?', 0),
(11243, 'frFR', 'Il est bien possible que le destin du monde dépende de nous.', 0),
(11245, 'frFR', 'Si vous vous approchez trop de ces tours, c’est la mort assurée, tant que ces lanceurs de sort seront là-haut.', 0),
(11247, 'frFR', 'Si je puis me permettre une suggestion… Lorsque nous mettons le feu aux bâtiments, il serait préférable de ne pas traîner à l''intérieur.', 0),
(11259, 'frFR', 'Tant que ces lanceurs de sorts seront là, trop s’approcher de ces tours signifiera une mort assurée.', 0),
(11339, 'frFR', 'Déjà de retour ? Venez-vous nous annoncer la victoire ?', 0),
(11340, 'frFR', 'Déjà de retour ? Venez-vous nous annoncer la victoire ?', 0),
(11342, 'frFR', 'Déjà de retour ? Venez-vous nous annoncer la victoire ?', 0),
(11373, 'frFR', 'Peu savent que la source de magie de Shaffar est uniquement contenue dans son amulette. Sans elle, il est impuissant.$B$BEt pourtant, si vous la possédez cela doit vouloir dire qu''il est mort.', 0),
(11374, 'frFR', 'Pouvez-vous imaginer rester coincé dans une gemme pour l''éternité ?', 0),
(11375, 'frFR', 'Je ne suis même pas sûr de la forme que ce murmure est censé avoir dans le monde physique, mais le professeur m''a assuré que vous le reconnaîtrez quand vous le verrez.$B$BPeut-être que cette chose ressemble au larynx de cet être ?', 0),
(11382, 'frFR', 'Si j''étais vous, je ferais très attention avec les voyages dans le temps. Vous ne voudriez pas faire un impair, comme tuer un de vos ancêtres et vous effacer vous-même du présent !', 0),
(11391, 'frFR', 'Des gargouilles ? Je le savais ! Vous les avez toutes tuées, j’espère ?$B$BOù va le monde, quand un brave nain ne peut plus creuser sans se faire attaquer ?', 0),
(11410, 'frFR', 'Je meurs d''envie d''essayer un nouvel appât.$B$BComment ça se passe avec Givraileron ?', 0),
(11418, 'frFR', 'Le charme d''Aderan a-t-il fonctionné ?', 0),
(11431, 'frFR', 'Vous avez quelque chose pour moi ou vous cherchez juste une nouvelle raison pour vous soûler ?', 0),
(11460, 'frFR', 'C’est un exercice important, $N. Si vous voulez devenir fauconnier, vous devez apprendre à nourrir votre oiseau.', 0),
(11490, 'frFR', 'Allez regarder dans l''orbe, mortel.', 0),
(11506, 'frFR', 'Les esprits d''Auchindoun sont partout autour de nous. Nous accorderont-ils leur bénédiction ?', 0),
(11513, 'frFR', 'Vous êtes-vous procuré les cellules de mana ?', 0),
(11535, 'frFR', 'Vous avez récupéré le minerai qu''il me faut ?', 0),
(11541, 'frFR', 'Mes éclaireurs me rapportent que les nagas n''ont pas encore été suffisamment déstabilisés aujourd''hui.', 0),
(11648, 'frFR', 'Eh bien ? Savez-vous où dame Evanor est détenue ?', 0),
(11661, 'frFR', 'Il faut détruire Orabus !', 0),
(11807, 'frFR', 'Honorez la flamme des Tranchantes.', 0),
(11867, 'frFR', 'Qu’ils soient des chasseurs de trésors ou des trappeurs assoiffés de sang, tous ceux qui soutiennent Nesingwary et osent s’en prendre à notre nature bien-aimée sont des ennemis de la SdPA.$B$BSi vous en veniez à abattre certains de ces ignobles sympathisants de Nesingwary, apportez-moi la preuve de ce haut fait et vous serez récompensé par une bénédiction des druides de la SdPA.', 0),
(11881, 'frFR', 'N''échouez pas ! Je compte sur vous.', 0),
(11886, 'frFR', 'Qu''avez-vous découvert ?', 0),
(11891, 'frFR', 'Avez-vous découvert leurs secrets ?', 0),
(11896, 'frFR', 'Avez-vous déchaîné la puissance de l''orage contre ces créatures contre nature ?', 0),
(11933, 'frFR', 'Vous rayonnez littéralement, $R. Qu''est-ce que vous avez là ?', 0),
(11935, 'frFR', 'Vous rayonnez littéralement, $R. Qu''est-ce que vous avez là ?', 0),
(11940, 'frFR', 'Vous êtes-vous procuré un jeune drake pour mes études ?', 0),
(11944, 'frFR', 'Ça avance ? On est dans une impasse, là.', 0),
(11954, 'frFR', 'Vous revenez victorieux ?', 0),
(11964, 'frFR', 'Mes salutations enflammées, honoré $C. Soyez le bienvenu sur la terre sacrée de la fête du Feu du solstice.', 0),
(11966, 'frFR', 'Mes salutations enflammées, honoré $C. Soyez le bienvenu sur la terre sacrée de la fête du Feu du solstice.', 0),
(11967, 'frFR', 'Vous avez des nouvelles pour moi, $N ?', 0),
(11972, 'frFR', 'Salutations, $N. Vous avez l''air inquiet, alors que vous devriez vous réjouir. Le seigneur du Givre est vaincu !', 0),
(11982, 'frFR', 'Qu''avez-vous à raconter ?', 0),
(11985, 'frFR', 'Avez-vous réussi à tuer le commandant ?', 0),
(11989, 'frFR', 'Bon choix, mec. Z''allez pas vivre. Dans le regret. Z''allez pas vivre dans le regret.', 0),
(12006, 'frFR', 'Je sens que vous n’avez pas encore tué assez de ces profanateurs !', 0),
(12012, 'frFR', 'Qu''est-ce qui vous trouble ainsi, mon enfant ?', 0),
(12031, 'frFR', '<L''ancien Mana''loa vous transperce de son regard, devinant que vous n''avez pas encore accompli sa tâche.>', 0),
(12033, 'frFR', 'Nous écraserons le Fléau !', 0),
(12053, 'frFR', 'C''est un vrai défi, $N !', 0),
(12070, 'frFR', 'Avez-vous transmis ma bénédiction aux géants ?', 0),
(12072, 'frFR', 'Attention, les chevaucheurs de guerre n''ont été entraînés pour se battre que dans Brume-glace. Si vous tentez de les emmener ailleurs, ils vous désarçonneront.', 0),
(12120, 'frFR', 'Vous avez trouvé la massette, $N ?', 0),
(12140, 'frFR', 'Ne perdez pas temps, $N. Angrathar nous attend !', 0),
(12146, 'frFR', 'Oui, $R ?', 0),
(12149, 'frFR', 'Avez-vous vaincu les magnataures ?', 0),
(12191, 'frFR', 'Buvez la chope, et balancez-la sur la C.E.R.V.O.I.S.E. Je crois qu''elle supportera le choc. Je ne l''aurai pas vol... heu.. construite si ce n''était pas le cas !', 0),
(12193, 'frFR', 'Ça biche, mon petit lot ? T''as quelque chose pour moi ?', 0),
(12194, 'frFR', 'Ça biche, mon petit lot ? T''as quelque chose pour moi ?', 0),
(12206, 'frFR', 'Vous l''avez fait ?$B$BOh, j''avais oublié de vous dire qu''il valait mieux faire bien attention à ne pas en mettre sur soi ! Ça sent mauvais, et vous n''arriverez jamais à faire partir les taches, sans parler de tout le temps nécessaire pour soigner ces fichues plaies là où la chair a été dissoute.', 0),
(12207, 'frFR', 'Avez-vous les échantillons, $N ?', 0),
(12214, 'frFR', 'Je suis drôlement content que vous soyiez venu. J''avais peur d''avoir à aller les faucher moi-même.', 0),
(12219, 'frFR', 'Avez-vous collecté ces échantillons, $N ?', 0),
(12227, 'frFR', 'Vous avez remis la main sur ces graines, $R ?', 0),
(12229, 'frFR', 'Avez-vous récupéré ce sang, $N ?', 0),
(12241, 'frFR', 'M''apportez-vous les cendres, $N ?', 0),
(12242, 'frFR', 'Vous êtes-vous déjà procuré les graines de Vordrassil, $N ?', 0),
(12246, 'frFR', 'Alors, avez-vous les échantillons de sang, $N ?', 0),
(12250, 'frFR', 'Avez-vous ces graines, $N ?', 0),
(12252, 'frFR', 'Quelles nouvelles apportez-vous ? Celles de votre succès, sans doute ?', 0),
(12263, 'frFR', 'Je suis las de cette pestilence.', 0),
(12292, 'frFR', 'Vous m''apportez cette boîte, $N ?', 0),
(12300, 'frFR', 'Les gens de Ruissargent… ne sont pas ce qu''ils ont l''air d''être.', 0),
(12328, 'frFR', 'Avez-vous récupéré ma poudre, $N ?', 0),
(12372, 'frFR', 'Comment se déroule le combat ? Sommes-nous en train de les repousser ?', 0),
(12414, 'frFR', 'Vous avez tous les mustangs dont nous aurons besoin ?', 0),
(12436, 'frFR', 'Vous avez cette venaison, $N ?', 0),
(12450, 'frFR', 'Vous êtes de retour ! Avez-vous fait ce que je vous ai demandé ?', 0),
(12470, 'frFR', 'Quelles nouvelles m''apportez-vous ? Que s''est-il passé au Sanctuaire draconique bronze ?$B$BAvez-vous découvert qui est le chef du Vol infini ?', 0),
(12483, 'frFR', 'Vous avez les ingrédients pour le vieux Dasnob, $N ?', 0),
(12491, 'frFR', 'Votre visage est bien sombre, $N. Avez-vous de mauvaises nouvelles ?', 0),
(12518, 'frFR', 'Je vois que vous avez réussi à réunir une suite de Mages ! Félicitations !', 0),
(12541, 'frFR', 'Vous voyez, $N, la véritable alchimie, c''est bien plus que le mélange de quelques ingrédients…', 0),
(12561, 'frFR', 'Ne me faites pas perdre mon temps, mortel. Les créations des titans doivent être protégées !', 0),
(12567, 'frFR', '<Le regard de pierre de Zim''Abwa transperce votre âme.$B$BZim''Abwa est ravi, mais il veut que vous lui montriez plus d''estime et de respect en lui offrant plus d''artéfacts drakkari.$B$BIl vous récompensera en retour.>', 0),
(12581, 'frFR', '<Le phylactère repose sur le sol, près du corps sans vie d''Artruis. Cette vision vous effraie.>', 0),
(12589, 'frFR', 'Satisfait des résultats ?', 0),
(12597, 'frFR', 'Avez-vous déjà récolté ces pavots, $N ?', 0),
(12607, 'frFR', 'Vous vous êtes occupé de tout ?', 0),
(12609, 'frFR', 'Avez-vous trouvé les composants dont j''ai besoin, $C ?', 0),
(12618, 'frFR', '<Zim''Torga vous regarde de manière impassible. Elle se demande si vous cherchez sa bénédiction continuelle en lui présentant plus d''offrandes drakkari pour l''honorer.>', 0),
(12629, 'frFR', 'M''apportez-vous les ingrédients que je vous ai demandés, $N ?', 0),
(12632, 'frFR', 'Tous mes enfants ne sont pas encore libérés de leurs tourments !', 0),
(12647, 'frFR', 'Si vous ne mettez pas bientôt un terme à mes souffrances, $N, tout sera perdu.', 0),
(12656, 'frFR', '<Zim''Rhuk est impressionné et frustré qu''une fois encore, vous ayez esquivé ses gardiens. En tout cas pour le moment.>$B$B<Placez les offrandes devant lui et il vous offrira sa bénédiction à nouveau.>', 0),
(12664, 'frFR', 'Z''avez maté le champ de bataille, mec ?', 0),
(12673, 'frFR', 'Mes larbins, leur avez appris l''goût du fouet, $N ?', 0),
(12686, 'frFR', 'Darmuk, l''a payé son échec, $N ?', 0),
(12690, 'frFR', 'Alors, les Trolls, z''ont mangé, $N ?', 0),
(12698, 'frFR', 'Une petite précision : les mineurs ne deviennent pas toujours des goules. Parfois, ça les tranforme en esprits enragés, déterminés à vous tuer.', 0),
(12713, 'frFR', 'Avez-vous affronté Drakuru, $N ?', 0),
(12729, 'frFR', 'Avez-vous ce qui vous a été demandé, $N ?', 0),
(12740, 'frFR', 'Pourquoi revenez-vous me parler alors que je vois encore mes hommes faire des chutes mortelles ?', 0),
(12750, 'frFR', 'Alors, ça fait quel effet ?', 0),
(12779, 'frFR', 'Tuez-les tous…', 0),
(12785, 'frFR', 'Bienvenue à Orgrimmar, $N. Le grand apothicaire Putrescin nous a prévenus de votre arrivée… Avez-vous le cerveau infecté ?', 0),
(12788, 'frFR', 'Bienvenue à Lune-d''argent, $N. Le grand apothicaire Putrescin nous a prévenus de votre arrivée… Avez-vous le cerveau infecté ?', 0),
(12790, 'frFR', 'Je sens que vous n''avez pas encore testé les deux cristaux de téléportation.$B$BCe n''est pas grave, prenez votre temps.', 0),
(12814, 'frFR', 'Qu''est-ce qui vous a pris aussi longtemps ? Leurs griffons volent lentement ? Nous devrons nous occuper de ça !', 0),
(12820, 'frFR', 'Vous avez aussi eu leurs copains frigbolds, j''espère !', 0),
(12823, 'frFR', 'Ce paquet d''explosifs est mon bébé... Ça m''a pris des semaines pour le perfectionner. Des SEMAINES !$B$BEt c''est vraiment long... D''accord.', 0),
(12841, 'frFR', 'Et mes runes, $N ? Vous les avez ?', 0),
(12844, 'frFR', 'Notre équipement, ça donne quoi, $N ?', 0),
(12855, 'frFR', 'Qui êtes-vous ?', 0),
(12886, 'frFR', 'Disparaissez !', 0),
(12887, 'frFR', 'L''Oculaire est encore entier ! Thassarian était fou de croire en vous.$B$BQui que vous soyez, ne revenez pas tant qu''il n''aura pas été détruit. Ma position ici ne doit pas être compromise !', 0),
(12906, 'frFR', 'C''est fait ? J''espère que vous n''avez pas tué trop de ces bâtards. Nous avons besoin de main-d''œuvre.', 0),
(12907, 'frFR', 'Vous revoilà. Avez-vous tué le porc désobéissant ?', 0),
(12916, 'frFR', 'Je suis un géant de parole, petit être.', 0),
(12918, 'frFR', 'C''est très généreux de votre part. Le moins que je puisse faire est de vous apprendre à rendre une gemme parfaite.', 0),
(12920, 'frFR', 'Qu''avez-vous trouvé ?', 0),
(12977, 'frFR', 'De puissantes rafales de vent tournent autour du cor, faisant résonner ses accents dans les montagnes environnantes.$B$BPour un passant ignorant, on dirait qu''il joue tout seul...', 0),
(12994, 'frFR', 'La mère de la tanière worg de givre vous regarde avec curiosité.', 0),
(13086, 'frFR', 'Les cris des mourants me hanteront toujours ! Aidez-les !', 0),
(13127, 'frFR', 'Vous vous êtes occupé du seigneur-mage Urom ?', 0),
(13133, 'frFR', 'Où est l''ancien héros ?$B$BNous n''avons pas le temps de discuter. Allez à la salle des Ancêtres et trouvez-le avant qu''il ne soit trop tard !', 0),
(13166, 'frFR', 'Achérus sera à nous !', 0),
(13182, 'frFR', 'Avez-vous débarrassé notre demeure de ces œufs flaellés ?', 0),
(13191, 'frFR', 'Eh bien ? Avez-vous réussi à trouver des braises ou est-ce que vous venez pleurnicher parce que l''Alliance vous a devancé ?', 0),
(13193, 'frFR', 'Déjà de retour ? Mince, j''espérais pouvoir me reposer un instant.', 0),
(13268, 'frFR', 'Vous ressemblez à quelqu''un qui se débrouille avec du fil et une aiguille, donc je peux peut-être vous aider.$B$BLes humanoïdes du nord portent des vêtements qui peuvent être rapidement transformé en étoffe si vous avez le savoir-faire.$B$BPour un peu d''or, je suis prêt à vous apprendre l''art de la récupération de tissu, qui vous permettra d''obtenir plus d''étoffe sur les humanoïdes du Norfendre.', 0),
(13269, 'frFR', 'Les humanoïdes des terres du nord portent des vêtements qui peuvent être transformés en tissu si vous avez le savoir-faire.$B$BPour un peu d''or, je serai ravie de vous apprendre l''art de la récupération de tissu qui vous permettra de prendre plus d''étoffe en tisse-givre sur les humanoïdes du nord que vous tuez.', 0),
(13270, 'frFR', 'Z''avez l''air du genre à savoir coudre et donc, j''ai qu''que chose pour vous.$B$BLes humanoïdes du nord portent des choses qui peuvent être transformées en étoffe si vous z''avez la manière.$B$BSi ça vous tente de lâcher un peu d''argent, je peux vous apprendre la comp''tence Récupération de tissu, et z''obtiendrez plus d''étoffe en tisse-givre sur les humanoïdes du Norfendre.', 0),
(13272, 'frFR', 'En tant que tailleur, je pense que vous êtes prêt à apprendre ce que j''ai à enseigner.$B$BDe nombreux humanoïdes du nord portent des vêtements qui peuvent être rapidement transformés en étoffe si vous avez la compétence nécessaire.$B$BPour une poignée de pièces d''or, je peux vous apprendre la compétence Récupération de tissu qui vous permettra de prendre plus d''étoffe sur les humanoïdes du Norfendre.', 0),
(13310, 'frFR', 'Le boulot est fait ?', 0),
(13311, 'frFR', 'Je vois que vous avez réussi à réunir une suite de Démons ! Félicitations !', 0),
(13324, 'frFR', 'Je vois que vous avez réussi à réunir une suite de Prismes ! Félicitations !', 0),
(13355, 'frFR', 'C''est quoi que vous avez là, $C ?', 0),
(13366, 'frFR', 'Avez-vous découvert ce que trafiquent les chercheurs, $C ?', 0),
(13373, 'frFR', 'Vous n''avez pas atteint votre quota, $N. Les bombardiers sont-ils si durs à manœuvrer ?', 0),
(13406, 'frFR', 'Vous n''avez pas atteint votre quota, $N. Sortez d''ici et faites exploser des trucs !', 0),
(13479, 'frFR', 'Avez-vous les fragments ?', 0),
(13480, 'frFR', 'Avez-vous les fragments ?', 0),
(13502, 'frFR', 'Avez-vous les chocolats ?', 0),
(13503, 'frFR', 'Avez-vous les dix chocolats du Jardin des nobles ?', 0),
(13559, 'frFR', 'Aucun tribut ordinaire n''était suffisant pour le grand Hodir quand il vivait parmi les géants du givre.$B$BIl n''est peut-être plus parmi nous, mais nous avons conservé la tradition consistant à offrir un tribut à sa force et sa sagesse. Si vous preniez part à cette tradition, votre réputation en sortirait sûrement grandie, petit $C.', 0),
(13604, 'frFR', 'Une énergie puissante fait gronder la console alors que le réceptacle circulaire s''ouvre.', 0),
(13614, 'frFR', 'Les lumières brillantes de la console parcourent plusieurs fois la surface de verre, comme si elles attendaient qu''on leur fournisse des données, d''une manière ou d''une autre.', 0),
(13625, 'frFR', 'Comment se passe la pratique du combat monté ?', 0),
(13627, 'frFR', 'Vous avez les « marchandises » dont nous avons parlé ?', 0),
(13681, 'frFR', 'Avez-vous trouvé des pierres ?', 0),
(13743, 'frFR', 'Avez-vous gagné la lame que je recherche ?', 0),
(13748, 'frFR', 'Avez-vous gagné la lame que je recherche ?', 0),
(13754, 'frFR', 'Avez-vous gagné la lame que je recherche ?', 0),
(13759, 'frFR', 'Avez-vous gagné la lame que je recherche ?', 0),
(13790, 'frFR', 'Avez-vous terminé de vous entraîner avec les autres champions ?', 0),
(13793, 'frFR', 'Avez-vous terminé de vous entraîner avec les autres champions ?', 0),
(13811, 'frFR', 'Avez-vous terminé de vous entraîner avec les autres champions ?', 0),
(13814, 'frFR', 'Avez-vous terminé de vous entraîner avec les autres champions ?', 0),
(13817, 'frFR', 'Une énergie puissante fait gronder la console alors que le réceptacle circulaire s''ouvre.', 0),
(13818, 'frFR', 'Les lumières brillantes de la console parcourent plusieurs fois la surface de verre, comme si elles attendaient qu''on leur fournisse des données, d''une manière ou d''une autre.', 0),
(13821, 'frFR', 'Le cachet de Freya, $N ? Vous l''avez ?', 0),
(13822, 'frFR', 'Vous avez récupéré le cachet, $N ?', 0),
(13823, 'frFR', 'Eh bien, $N ? Vous l''avez ?', 0),
(13824, 'frFR', 'Vous avez pu récupérer le cachet, $N ?', 0),
(13833, 'frFR', 'Vous avez réussi à vous débrouiller, avec les dents-sanglantes ? N''oubliez pas ce que je vous ai dit, à propos des flaques de sang.', 0),
(13834, 'frFR', 'Restez sur vos gardes quand vous pêcherez le terrochet.', 0),
(13836, 'frFR', 'Bonjour. Vous m''avez rapporté quelque chose ?', 0),
(13845, 'frFR', 'Est-ce que cette chose est bien ce que je pense, $C?', 0),
(13846, 'frFR', 'Vous voulez faire un don ?', 0),
(13887, 'frFR', 'Avez-vous trouvé ces œufs ?', 0),
(13905, 'frFR', 'Votre jeune peau-de-venin vous regarde avec excitation.', 0),
(13906, 'frFR', 'Alors, vous avez pris soin de ce raptor ?', 0),
(13914, 'frFR', 'Votre jeune peau-de-venin vous regarde avec excitation.', 0),
(13931, 'frFR', 'Ça biche, mon petit lot ? T''as quelque chose pour moi ?', 0),
(13932, 'frFR', 'Ça biche, mon petit lot ? T''as quelque chose pour moi ?', 0),
(13952, 'frFR', 'Vous n’auriez pas un peu de pain des morts, par hasard ?', 0),
(13986, 'frFR', 'Ah ! Bonjour. Je ne pense pas que nous ayons été présentés. Puis-je faire quelque chose pour vous ?', 0),
(14017, 'frFR', 'Avez-vous découvert ce qu''ils font avec les restes du Chevalier noir ?', 0),
(14023, 'frFR', 'Nous n''aurons jamais trop de cette délicieuse farce au pain épicé. Elle a beaucoup de succès.', 0),
(14024, 'frFR', 'De nouvelles parts de tarte à la citrouille ? Juste à temps.', 0),
(14028, 'frFR', 'Je rêve, ou ça sent la sauce aux canneberges ?', 0),
(14030, 'frFR', 'Êtes-vous venu participer à la fête des Bienfaits du pèlerin ?', 0),
(14033, 'frFR', 'C''est bon de vous revoir, $N.', 0),
(14035, 'frFR', 'Qu''est-ce qui vous ramène à Darnassus, $N ?', 0),
(14037, 'frFR', 'Les tables auraient bien besoin de plus de farce au pain épicé.', 0),
(14040, 'frFR', 'Nous n''aurons jamais trop de tarte à la citrouille.', 0),
(14043, 'frFR', 'Rebonjour, $N.', 0),
(14044, 'frFR', 'C''est bon de vous revoir, $N.', 0),
(14048, 'frFR', 'Alors, vous avez trouvé ces dindes ?', 0),
(14051, 'frFR', 'Alors, vous avez cette farce ?', 0),
(14053, 'frFR', 'Vous êtes-vous procuré de la sauce aux canneberges ?', 0),
(14054, 'frFR', 'Alors, ces tartes, ça se passe comment ?', 0),
(14055, 'frFR', 'Avez-vous ces patates douces confites ?', 0),
(14058, 'frFR', 'Avez-vous ces patates douces confites ?', 0),
(14059, 'frFR', 'Vous êtes-vous procuré de la sauce aux canneberges ?', 0),
(14060, 'frFR', 'Alors, ces tartes, ça se passe comment ?', 0),
(14061, 'frFR', 'Comment se passe la chasse aux dindes ?', 0),
(14062, 'frFR', 'Alors, vous avez cette farce ?', 0),
(14074, 'frFR', 'Avez-vous réussi à récupérer les provisions manquantes ?', 0),
(14076, 'frFR', 'Alors, vous avez ces œufs ? Si nous ne les nourrissons pas rapidement, les vers vont manger leurs dresseurs.', 0),
(14077, 'frFR', 'Avez-vous vu les esprits des villageois tualiq massacrés ?', 0),
(14079, 'frFR', 'Ah, vous avez reçu ma lettre ? Bien.', 0),
(14081, 'frFR', 'Ah, vous avez reçu ma lettre ? Bien.', 0),
(14082, 'frFR', 'Ah, vous avez reçu ma lettre ? Bien.', 0),
(14085, 'frFR', 'Ah, vous avez reçu ma lettre ? Bien.', 0),
(14088, 'frFR', 'Ah, vous avez reçu ma lettre ? Bien.', 0),
(14092, 'frFR', 'Alors, vous avez ces œufs ? Si nous ne les nourrissons pas, les jormungars vont bientôt devenir désagréables.', 0),
(14108, 'frFR', 'Avez-vous chassé le kraken ? Dépêchez-vous, croisé ! Le temps va nous manquer.', 0),
(14111, 'frFR', 'Je sens les esprits s''agiter en vous. Qu''est-ce qui vous pousse à rechercher l''aide du Cercle terrestre ?', 0),
(14112, 'frFR', 'J''espère que vous avez quelque chose à donner à manger à Glace-hurlante, sinon je vais vraiment commencer à mettre des Saccage-soleil dans sa cage.', 0),
(14143, 'frFR', 'Avez-vous réussi à récupérer les provisions manquantes ?', 0),
(14144, 'frFR', 'Avez-vous vu les esprits des villageois tualiq massacrés ?', 0),
(14145, 'frFR', 'J''espère que vous avez quelque chose à donner à manger à Glace-hurlante, sinon je vais vraiment commencer à mettre des membres du Concordat argenté dans sa cage.', 0),
(14166, 'frFR', 'Vous n’auriez pas un peu de pain des morts, par hasard ?', 0),
(14167, 'frFR', 'Vous n’auriez pas un peu de pain des morts, par hasard ?', 0),
