(14176, 'frFR', 'Vous n’auriez pas un peu de pain des morts, par hasard ?', 0),
(14177, 'frFR', 'Vous n’auriez pas un peu de pain des morts, par hasard ?', 0),
(14183, 'frFR', 'Déjà de retour ? Venez-vous nous annoncer la victoire ?', 0),
(14356, 'frFR', 'Avez-vous mis les livres en sécurité ? Ils ne doivent pas rester entre de mauvaises mains.', 0),
(14483, 'frFR', 'Vous êtes-vous occupé de cette bande de malfaisants ?', 0),
(20438, 'frFR', 'Est-ce que Shandy a pu vous aider à trouver un tabard saccage-soleil ?', 0),
(24428, 'frFR', 'Par les crocs de Nozdormu !', 0),
(24429, 'frFR', 'Que signifie ceci ?', 0),
(24431, 'frFR', 'Comme je le dis toujours, les vins fins ne conviennent qu''aux personnes raffinées.', 0),
(24442, 'frFR', 'Qu''avez-vous trouvé, $N ?', 0),
(24576, 'frFR', 'Avez-vous trouvé mon homme, ou s''est-il caché sous un rocher ?', 0),
